-- Guarded, versioned release for Perfect Video modules 7–9.
-- Existing lesson rows and versions remain intact; progress is snapshotted before rebasing.

CREATE OR REPLACE FUNCTION academy_private.lesson_validation(p_version uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v public.academy_lesson_versions;
  errors jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
  n integer;
  kinds text[];
BEGIN
  SELECT * INTO v FROM public.academy_lesson_versions WHERE id=p_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF;

  SELECT count(*),coalesce(array_agg(DISTINCT block_type),'{}')
    INTO n,kinds
  FROM public.academy_lesson_blocks WHERE version_id=p_version;

  IF btrim(v.objective)='' THEN errors:=errors||jsonb_build_array('missing_objective'); END IF;
  IF btrim(v.hook)='' THEN errors:=errors||jsonb_build_array('missing_hook'); END IF;
  IF n<5 THEN errors:=errors||jsonb_build_array('too_few_blocks'); END IF;
  IF NOT (kinds && ARRAY[
    'sequence_sort','matching','image_hotspot','decision_tree','scenario',
    'client_simulation','calculator','prompt_builder','practical_response',
    'reflection','checklist','quiz','homework','submission','flip_cards'
  ]) THEN errors:=errors||jsonb_build_array('missing_interaction'); END IF;
  IF NOT ('quiz'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_knowledge_check'); END IF;
  IF NOT (
    kinds && ARRAY['prompt_builder','practical_response','homework','submission']
    OR (
      EXISTS (
        SELECT 1 FROM public.academy_lessons l
        WHERE l.id=v.academy_lesson_id
          AND l.module_id IN (
            's02-m01','s02-m02','s02-m03','s02-m04','s02-m05','s02-m06',
            's02-m07','s02-m08','s02-m09'
          )
      )
      AND kinds && ARRAY[
        'sequence_sort','matching','image_hotspot','decision_tree',
        'scenario','client_simulation','calculator'
      ]
    )
  ) THEN errors:=errors||jsonb_build_array('missing_practice'); END IF;
  IF NOT ('summary'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_summary'); END IF;
  IF EXISTS (
    SELECT 1 FROM public.academy_lesson_blocks b
    WHERE b.version_id=p_version AND b.required AND b.points=0
  ) THEN warnings:=warnings||jsonb_build_array('required_block_has_no_xp'); END IF;
  IF EXISTS (
    SELECT 1
    FROM public.academy_lesson_blocks b
    LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
    WHERE b.version_id=p_version
      AND b.block_type IN (
        'sequence_sort','matching','image_hotspot','decision_tree','scenario',
        'client_simulation','calculator','quiz'
      )
      AND k.block_id IS NULL
  ) THEN errors:=errors||jsonb_build_array('missing_server_evaluation'); END IF;

  RETURN jsonb_build_object(
    'errors',errors,
    'warnings',warnings,
    'block_count',n,
    'interactive',kinds && ARRAY[
      'sequence_sort','matching','image_hotspot','decision_tree','scenario',
      'client_simulation','calculator','prompt_builder','practical_response',
      'reflection','checklist','quiz','homework','submission','flip_cards'
    ],
    'has_quiz','quiz'=ANY(kinds),
    'has_assignment',kinds && ARRAY['practical_response','homework','submission']
  );
END
$function$;

DO $release$
DECLARE
  payload jsonb := $curriculum$[{"module_id":"s02-m07","lesson_id":"pv07-01","title":"Телефонът на терен: какво записва и кога спира","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще избереш надежден режим за конкретен телефон и ще докажеш, че той издържа снимачната задача.","hook":"Кадърът изглежда чудесно на екрана, докато телефонът не прегрее, не спре записа или файлът не се отвори в монтажната програма.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш надежден режим за конкретен телефон и ще докажеш, че той издържа снимачната задача."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Кадърът изглежда чудесно на екрана, докато телефонът не прегрее, не спре записа или файлът не се отвори в монтажната програма."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Спецификацията на модела е начало на проверката, не гаранция за резултат. Различните обективи на един телефон може да имат различни ограничения за кадри в секунда, стабилизация и HDR. Log профилът и ProRes са налични само при конкретни модели и режими; не ги включвай по навик. Високият битрейт увеличава нуждата от място, захранване и по-силен монтажен компютър.\n\nИзбери режима според изхода: къде ще се публикува, кой ще коригира цвета и какво устройство ще монтира. При кратко вертикално видео със срок SDR може да даде по-добър резултат от Log, който никой няма време да преобразува и провери."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Преди платена задача запиши точния модел, версия на системата и камера приложение. Заснеми тест с избраните резолюция, кадрова честота, обектив, микрофон и формат; остави телефона да работи поне колкото най-дългия дубъл. Провери температурата, мястото, батерията, фокуса, звука и отварянето на файла в монтажния софтуер. Телефонът може да превключи обектив при слаба светлина или избрана честота."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Препиши от брифа формат, ориентация, кадрова честота, цветови изход и срок.\n2. Провери ръководството за точния модел и кои обективи поддържат режима.\n3. Освободи място, зареди телефона, изключи известията и свържи същия микрофон.\n4. Запиши тест с най-дългия планиран дубъл; следи фокус, експозиция, спиране и температура.\n5. Прехвърли оригиналния файл и провери картина, звук, ориентация и синхрон.\n6. Запази режима като пресет само след тест; запиши и резервен режим."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Ресторант иска шест вертикални клипа за два часа. Телефонът предлага няколко режима, но 4K с висок битрейт пълни мястото, а Log не е подготвен в монтажната програма. Екипът пробва SDR с микрофона и прехвърля файла на монтажната станция, преди да снима менюто.\n\nКритерий за добър ход: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът."},"after":{"label":"Как го поправяш","text":"Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта за собственото си устройство: модел, камера приложение, надежден режим, налични цветови профили, свободно място и лимит за дълъг дубъл. Запиши 90-секунден тест с реалния комплект, прехвърли го и го изгледай на голям екран.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Провери ръководството за точния модел и кои обективи поддържат режима. Запиши тест с най-дългия планиран дубъл; следи фокус, експозиция, спиране и температура.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно.\n\nТестът е минал едва когато: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Ресторант иска шест вертикални клипа за два часа. Телефонът предлага няколко режима, но 4K с висок битрейт пълни мястото, а Log не е подготвен в монтажната програма. Екипът пробва SDR с микрофона и прехвърля файла на монтажната станция, преди да снима менюто.\n\nДоставката ти е: Направи карта за собственото си устройство: модел, камера приложение, надежден режим, налични цветови профили, свободно място и лимит за дълъг дубъл. Запиши 90-секунден тест с реалния комплект, прехвърли го и го изгледай на голям екран.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Apple изброява поддържаните модели и условията за ProRes; сверявай точния модел: https://support.apple.com/en-gb/109041"},"points":0,"required":false},{"position":12,"block_key":"field_note_1","block_type":"rich_text","title":"Измери компромиса","content":{"body":"Сними още един кратък тест с по-лек режим. Сравни продължителност, размер на файла, плавност и време за прехвърляне; не избирай по менюто само."},"points":1,"required":false},{"position":13,"block_key":"quiz_1","block_type":"quiz","title":"Избери работния режим","content":{"question":"Какво доказва, че режимът е подходящ за снимачния ден?","options":[{"id":"a","label":"Че това е най-високата настройка в менюто."},{"id":"b","label":"Тест със същите настройки, обектив, звук и продължителност, после проверка на прехвърления файл."},{"id":"c","label":"Че кратък клип изглежда добре на дисплея на телефона."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Пълен тест показва лимитите на устройството, носителя, температурата и монтажната станция.\n\nВариантът „Че това е най-високата настройка в менюто.“ не доказва: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Вариантът „Че кратък клип изглежда добре на дисплея на телефона.“ оставя нерешено: Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът. Безопасната корекция е: Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_1","block_type":"scenario","title":"Клиентът иска Log","content":{"prompt":"Клиентът иска Log, но приложението не го предлага при нужната честота. Как постъпваш?","options":[{"id":"a","label":"Записваш стандартен профил, но го обозначаваш като Log."},{"id":"b","label":"Показваш ограничението, тестваш поддържан режим и потвърждаваш избора с клиента преди снимане."},{"id":"c","label":"Сменяш обектива и приемаш, че ограничението ще изчезне."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Режимът трябва да съответства на действителния запис и уговорения процес.\n\nВариантът „Сменяш обектива и приемаш, че ограничението ще изчезне.“ не доказва: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Вариантът „Записваш стандартен профил, но го обозначаваш като Log.“ оставя нерешено: Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът. Безопасната корекция е: Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"quiz_2","block_type":"quiz","title":"Къде е компромисът","content":{"question":"Кое твърдение за Log и висок битрейт е надеждно?","options":[{"id":"a","label":"Ползвай ги, когато тестът и монтажният процес показват полза за този проект."},{"id":"b","label":"Високият битрейт винаги прави телефона по-стабилен при дълъг запис."},{"id":"c","label":"Винаги използвай Log; той автоматично създава правилен цвят."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тези режими добавят свобода или данни, но и увеличават изискванията към устройството и постпродукцията.\n\nВариантът „Винаги използвай Log; той автоматично създава правилен цвят.“ не доказва: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Вариантът „Високият битрейт винаги прави телефона по-стабилен при дълъг запис.“ оставя нерешено: Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът. Безопасната корекция е: Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"scenario_2","block_type":"scenario","title":"Резервният план","content":{"prompt":"След 25 минути корпусът е горещ, а предстоят още интервюта. Как пазиш материала?","options":[{"id":"a","label":"Продължаваш до автоматичното изключване."},{"id":"b","label":"Изтриваш пробните клипове, докато телефонът още записва."},{"id":"c","label":"Спираш контролирано, проверяваш клипа, охлаждаш телефона и минаваш на предварително тестван резервен режим."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Първо защити записаното; после върни системата към доказано надежден режим.\n\nВариантът „Продължаваш до автоматичното изключване.“ не доказва: Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим. Вариантът „Изтриваш пробните клипове, докато телефонът още записва.“ оставя нерешено: Включват се най-висока резолюция, Log и максимални кадри в секунда, без да се тества моделът, обективът, мястото и софтуерът. Безопасната корекция е: Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":17,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Провери ръководството за точния модел и кои обективи поддържат режима."},{"id":"s3","text":"Освободи място, зареди телефона, изключи известията и свържи същия микрофон."},{"id":"s4","text":"Запиши тест с най-дългия планиран дубъл; следи фокус, експозиция, спиране и температура."},{"id":"s1","text":"Препиши от брифа формат, ориентация, кадрова честота, цветови изход и срок."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Препиши от брифа формат, ориентация, кадрова честота, цветови изход и срок.\n2. Провери ръководството за точния модел и кои обективи поддържат режима.\n3. Освободи място, зареди телефона, изключи известията и свържи същия микрофон.\n4. Запиши тест с най-дългия планиран дубъл; следи фокус, експозиция, спиране и температура."},"scoring":{"mode":"exact_order"}},{"position":18,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще избереш надежден режим за конкретен телефон и ще докажеш, че той издържа снимачната задача.","Сравни два режима в истинската сцена. Избери този, който покрива брифа, записва непрекъснато и се възпроизвежда коректно.","Пробата минава без прекъсване; файлът се отваря, звукът е синхронен и няма нежелано превключване на обектив. В картата има резервен режим."],"nextStep":"Направи карта за собственото си устройство: модел, камера приложение, надежден режим, налични цветови профили, свободно място и лимит за дълъг дубъл. Запиши 90-секунден тест с реалния комплект, прехвърли го и го изгледай на голям екран."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-02","title":"Мобилен комплект за платена задача: звук, опора и захранване","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще сглобиш лек комплект, който покрива конкретен кадър и се настройва без изненади.","hook":"На място микрофонът влиза в телефона само след покупката на грешен адаптер; стойката закрива бутон, а батерията е празна преди интервюто.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще сглобиш лек комплект, който покрива конкретен кадър и се настройва без изненади."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"На място микрофонът влиза в телефона само след покупката на грешен адаптер; стойката закрива бутон, а батерията е празна преди интервюто."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Комплектът започва от задачата, не от списък с аксесоари. За интервю може да са нужни телефон, микрофон, слушалки, опора, светлина и резервно захранване; за продуктови кадри може да са по-ценни статив, отражател и поставка. Проверявай връзката, физическия баланс и възможността да следиш звук, докато записваш.\n\nКейсът може да пречи на конектор, безжичният приемник заема порт, а захранването може да внася шум. Лекото решение, което работи часове, е по-полезно от тежък rig, който операторът сваля след два дубъла."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Провери веригата от микрофона до файла: конектор, адаптер според устройството, захранване и мониторинг. Запиши тест с човек, който се движи; слушай със слушалки, не само по индикатора. Добави клетка само ако тя дава нужния монтаж и не закрива камерата, бутоните или порта. Носи резервен кабел и адаптер, маркирани за комплекта."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи нужните кадър, звук, продължителност и движение.\n2. Напиши списък: телефон, микрофон, адаптер, слушалки, опора, светлина, батерия и кабели.\n3. Сглоби комплекта у дома; провери достъп до бутони, камери и портове.\n4. Запиши говор на тихо и шумно място; прослушай и двата файла.\n5. Сними с опората и провери дали кабел или аксесоар влиза в кадъра.\n6. Упакувай критичните адаптери и кабели отделно, с резерв за всеки."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Майстор обяснява ремонт в тесен сервиз. Лавалиерният микрофон е на ризата, телефонът стои на мини статив и операторът следи през слушалки. Малката лампа е отделена от телефона, за да остави място на ръцете и инструмента в кадъра.\n\nКритерий за добър ход: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно."},"after":{"label":"Как го поправяш","text":"Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Сложи на масата всичко, което ще носиш на интервю. Запиши 60 секунди с говор, движение и светлина; преброй колко ръце трябват за настройка, провери кабелите в кадъра и измери времето за сглобяване.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Напиши списък: телефон, микрофон, адаптер, слушалки, опора, светлина, батерия и кабели. Запиши говор на тихо и шумно място; прослушай и двата файла.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста.\n\nТестът е минал едва когато: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Майстор обяснява ремонт в тесен сервиз. Лавалиерният микрофон е на ризата, телефонът стои на мини статив и операторът следи през слушалки. Малката лампа е отделена от телефона, за да остави място на ръцете и инструмента в кадъра.\n\nДоставката ти е: Сложи на масата всичко, което ще носиш на интервю. Запиши 60 секунди с говор, движение и светлина; преброй колко ръце трябват за настройка, провери кабелите в кадъра и измери времето за сглобяване.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"field_note_1","block_type":"rich_text","title":"Полеви инвентар","content":{"body":"Снимай сглобения комплект отгоре и запиши какво свързва всеки кабел. След снимане сверявай снимката, за да не оставиш адаптер на локацията."},"points":1,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Провери цялата верига","content":{"question":"Кое е най-доброто изпитание за микрофонния комплект?","options":[{"id":"a","label":"Гледане на нивомера без прослушване."},{"id":"b","label":"Запис на реалното място, прослушване през слушалки и проверка на готовия файл."},{"id":"c","label":"Проверка дали приемникът свети."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Индикаторът не показва всички проблеми с конектора, шум, прекъсване и избрания вход.\n\nВариантът „Проверка дали приемникът свети.“ не доказва: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Вариантът „Гледане на нивомера без прослушване.“ оставя нерешено: Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно. Безопасната корекция е: Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Несъвместим порт","content":{"prompt":"Телефонът няма свободен порт за захранване след включване на микрофона. Какво правиш?","options":[{"id":"a","label":"Избираш съвместим маршрут за звук и захранване, после тестваш действителния запис."},{"id":"b","label":"Слагаш разклонител, без да провериш посоката и съвместимостта."},{"id":"c","label":"Оставяш микрофона неподключен; телефонът ще използва вградения."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Портът е част от системата; потвърди го с реален запис, не само с механично пасване.\n\nВариантът „Оставяш микрофона неподключен; телефонът ще използва вградения.“ не доказва: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Вариантът „Слагаш разклонител, без да провериш посоката и съвместимостта.“ оставя нерешено: Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно. Безопасната корекция е: Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Избери какво носиш","content":{"question":"Кой аксесоар заслужава място в комплекта?","options":[{"id":"a","label":"Най-скъпият, защото е универсален."},{"id":"b","label":"Всеки аксесоар, който някога може да потрябва."},{"id":"c","label":"Този, който решава риска от брифа и не създава по-голям проблем с тегло, кабели или достъп."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Оразмери комплекта за задача, време и човека, който го носи.\n\nВариантът „Най-скъпият, защото е универсален.“ не доказва: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Вариантът „Всеки аксесоар, който някога може да потрябва.“ оставя нерешено: Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно. Безопасната корекция е: Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Шум в записа","content":{"prompt":"Приемникът работи, но в слушалките има пукане при движение. Следващият ход?","options":[{"id":"a","label":"Разчитай, че компресията ще го поправи в монтажа."},{"id":"b","label":"Вдигни усилването, за да заглушиш пукането."},{"id":"c","label":"Провери кабела и захвата, обезопаси връзката и повтори теста с движение преди интервюто."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Първо отстрани механичната причина; обработката не поправя прекъсващ конектор.\n\nВариантът „Вдигни усилването, за да заглушиш пукането.“ не доказва: Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер. Вариантът „Разчитай, че компресията ще го поправи в монтажа.“ оставя нерешено: Купуват аксесоари поотделно, без да проверят дали се свързват и дали могат да работят едновременно. Безопасната корекция е: Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Напиши списък: телефон, микрофон, адаптер, слушалки, опора, светлина, батерия и кабели."},{"id":"s1","text":"Определи нужните кадър, звук, продължителност и движение."},{"id":"s4","text":"Запиши говор на тихо и шумно място; прослушай и двата файла."},{"id":"s3","text":"Сглоби комплекта у дома; провери достъп до бутони, камери и портове."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи нужните кадър, звук, продължителност и движение.\n2. Напиши списък: телефон, микрофон, адаптер, слушалки, опора, светлина, батерия и кабели.\n3. Сглоби комплекта у дома; провери достъп до бутони, камери и портове.\n4. Запиши говор на тихо и шумно място; прослушай и двата файла."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще сглобиш лек комплект, който покрива конкретен кадър и се настройва без изненади.","Сглоби пълния комплект и запиши веригата. При проблем смени един елемент и повтори теста.","Комплектът се сглобява за пет минути, може да записва и следи звук едновременно, не закрива обектива и има резервен кабел или адаптер."],"nextStep":"Сложи на масата всичко, което ще носиш на интервю. Запиши 60 секунди с говор, движение и светлина; преброй колко ръце трябват за настройка, провери кабелите в кадъра и измери времето за сглобяване."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-03","title":"Движение без треперене: ръка, гимбъл или статив","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще избереш стабилизация по смисъла на кадъра и ще изпълниш движението без разклащане и люлеене.","hook":"Гимбълът прави кадъра плавен, но камерата продължава да се движи без причина и зрителят не разбира към какво го водиш.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш стабилизация по смисъла на кадъра и ще изпълниш движението без разклащане и люлеене."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Гимбълът прави кадъра плавен, но камерата продължава да се движи без причина и зрителят не разбира към какво го водиш."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Стабилността е избор на движение. Стативът държи гледната точка неподвижна; моноподът помага при дълъг запис и смяна на позиция; ръчният кадър може да е естествен, ако стоиш и движиш тялото контролирано. Гимбълът изглажда част от движението, но не решава лоша траектория, вертикално подскачане или претоварване.\n\nПреди включване балансирай телефона с кейса и всички аксесоари. Провери допустимата маса, ориентацията и свободното въртене. Планирай начална точка, край и скорост; ако камерата просто се плъзга през стаята, стабилизацията вече е ефект без задача.\n\nПолеви наръчник: Сними кратък кадър с движение пеша, после същия кадър от опора. Сравни хоризонта, трептенето на стъпките и края на движението, не само плавността на средната част. По-дълго фокусно разстояние прави малкото ъглово движение видимо; широк кадър прощава повече, но не премахва вертикалното подскачане. При гимбъл настрой баланса преди калибрация, отключи осите според ръководството и провери моторите с избрания обектив. На статив изключи стабилизацията, ако тестът показва плаване на заключен кадър. Избери ръчна опора, когато носенето, батерията или безопасният път са по-важни от сложна траектория.\n\nРаботна проверка: Провери и дали операторът може да повтори движението: отбележи начална и крайна позиция, посоката на погледа и къде се измества фокусът. Снимай пет секунди преди и след действието, за да има място за монтаж. Ако стъпките се люлеят, приближи маршрута, смени посоката или снижи темпото; не компенсирай всяко отклонение с агресивна стабилизация, която изкривява краищата на кадъра.\n\nДопълнителен ход от практиката: За предвидим кадър прецени и фокусното разстояние, височината и скоростта на оператора. Планирай къде започва/свършва движението, остави handle и следи дали автофокусът не прескача към фона. Заключен хоризонт не значи, че кадърът трябва да е неподвижен: мотивирай панорама или следване с действието и приключи в четима позиция. Преди дълъг дубъл направи кратка репетиция с актьор или водещ и махни препятствията от маршрута.\n\nПрактически разбор: Сравни кадрите на един маршрут: ръчна опора, статив и гимбъл. Не променяй фокус и скорост по средата. Избери гледната точка, която запазва линиите вертикални, не закрива човека и оставя място за текст. На гладък под направи пробен проход; в тесен лошо осветен коридор провери завой, препятствия и спиране."},"points":2,"required":true},{"position":3,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Назови какво трябва зрителят да види и защо камерата се движи.\n2. Избери ръка, статив, монопод или гимбъл според дължината и траекторията.\n3. Монтирай целия комплект, балансирай и калибрирай според ръководството.\n4. Маркирай началната и крайната позиция; репетирай без запис.\n5. Запиши два дубъла с постоянна скорост; спри движението преди важната реплика.\n6. Изгледай на голям екран и изхвърли движението, което не добавя смисъл."},"points":2,"required":true},{"position":4,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Кафене иска кадър от вратата до бариста. Пътят е кратък, но по него минават хора. Екипът прави един предварително репетиран проход с гимбъл и отделен статичен кадър на бариста. Движението свършва преди началото на действието, за да остане чиста точка за срез.\n\nХод, който се проваля: Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент.\n\nКорекция: Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение.\n\nКритерий за добър ход: Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани."},"points":2,"required":true},{"position":5,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Заснеми един човек, който влиза в кадър, ръчно, на статив и с гимбъл. Сравни хоризонт, подскачане, видимост на лицето и дали движението подчертава действието. Избери дубъл и запиши какво казва движението.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":6,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":7,"block_key":"quiz_1","block_type":"quiz","title":"Дай движение причина","content":{"question":"Кога гимбълът е оправдан?","options":[{"id":"a","label":"Когато предвидено движение разкрива обект или действие и операторът може да го повтори контролирано."},{"id":"b","label":"Когато композицията не е решена и търсиш нещо интересно."},{"id":"c","label":"При всеки кадър, защото плавността винаги е професионална."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Гимбълът е опора за конкретна траектория, не заместител на композицията.\n\nВариантът „При всеки кадър, защото плавността винаги е професионална.“ не доказва: Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани. Вариантът „Когато композицията не е решена и търсиш нещо интересно.“ оставя нерешено: Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент. Безопасната корекция е: Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":8,"block_key":"scenario_1","block_type":"scenario","title":"Накланящ се хоризонт","content":{"prompt":"Хоризонтът бавно се накланя, въпреки че телефонът е центриран. Какво проверяваш?","options":[{"id":"a","label":"Увеличаваш скоростта, за да не личи наклонът."},{"id":"b","label":"Добавяш монтажна стабилизация, без да провериш баланса."},{"id":"c","label":"Баланс на пълния комплект, калибриране и режим на мотора; после правиш нов тест."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Неправилен баланс натоварва моторите; провери комплекта преди да ходиш на локация.\n\nВариантът „Увеличаваш скоростта, за да не личи наклонът.“ не доказва: Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани. Вариантът „Добавяш монтажна стабилизация, без да провериш баланса.“ оставя нерешено: Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент. Безопасната корекция е: Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"quiz_2","block_type":"quiz","title":"Избери простата опора","content":{"question":"Кой кадър печели от статив?","options":[{"id":"a","label":"Кадър, който ще бъде ускорен в монтажа."},{"id":"b","label":"Всеки кадър в движение."},{"id":"c","label":"Интервю или демонстрация, в която зрителят трябва да следи лице и ръце спокойно."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Стабилният хоризонт помага при продължително гледане и точни действия.\n\nВариантът „Всеки кадър в движение.“ не доказва: Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани. Вариантът „Кадър, който ще бъде ускорен в монтажа.“ оставя нерешено: Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент. Безопасната корекция е: Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_2","block_type":"scenario","title":"Тесен коридор","content":{"prompt":"Гимбълът закача стената по маршрута, а кадърът трябва да покаже само табела и врата. Какво правиш?","options":[{"id":"a","label":"Фиксираш телефона на опора или снимаш кратък ръчен кадър от безопасна позиция."},{"id":"b","label":"Правиш по-бърз проход и се надяваш да не удариш."},{"id":"c","label":"Добавяш аксесоари към гимбъла за стабилност."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Избирай решение по задачата и пространството; не рискувай хора и техника за ненужно движение.\n\nВариантът „Правиш по-бърз проход и се надяваш да не удариш.“ не доказва: Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани. Вариантът „Добавяш аксесоари към гимбъла за стабилност.“ оставя нерешено: Операторът натиска джойстика постоянно и ускорява в края; хоризонтът се накланя, а движението продължава след важния момент. Безопасната корекция е: Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Маркирай началната и крайната позиция; репетирай без запис."},{"id":"s1","text":"Назови какво трябва зрителят да види и защо камерата се движи."},{"id":"s2","text":"Избери ръка, статив, монопод или гимбъл според дължината и траекторията."},{"id":"s3","text":"Монтирай целия комплект, балансирай и калибрирай според ръководството."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Назови какво трябва зрителят да види и защо камерата се движи.\n2. Избери ръка, статив, монопод или гимбъл според дължината и траекторията.\n3. Монтирай целия комплект, балансирай и калибрирай според ръководството.\n4. Маркирай началната и крайната позиция; репетирай без запис."},"scoring":{"mode":"exact_order"}},{"position":12,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще избереш стабилизация по смисъла на кадъра и ще изпълниш движението без разклащане и люлеене.","Планирай начало, край и постоянна скорост. За кадър без нужда от пътешествие използвай опора и не добавяй движение.","Има ясна начална и крайна точка, операторът спира камерата преди следващото действие, а хоризонтът и обектът остават контролирани."],"nextStep":"Заснеми един човек, който влиза в кадър, ръчно, на статив и с гимбъл. Сравни хоризонт, подскачане, видимост на лицето и дали движението подчертава действието. Избери дубъл и запиши какво казва движението."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-04","title":"Чист говор и използваема светлина с малък комплект","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще поставиш микрофон и светлина така, че гласът да е разбираем, лицето да е четимо, а комплектът безопасен.","hook":"Интервюто е в кухня; музиката е тиха, но вентилаторът на лампата и шумът от улицата правят отговора неизползваем.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще поставиш микрофон и светлина така, че гласът да е разбираем, лицето да е четимо, а комплектът безопасен."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Интервюто е в кухня; музиката е тиха, но вентилаторът на лампата и шумът от улицата правят отговора неизползваем."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Постави микрофона близо до говорещия, без триене в дреха и без да влиза в кадър. Запиши тест и го прослушай със слушалки. Насочи наличната светлина спрямо лицето; не осветявай фона по-силно от човека, освен ако това е замислено. Ограничѝ смесването на дневна светлина и лампи с различна температура.\n\nЕдна лампа не е длъжна да прави сцената равна. Премести човека, завърти стола или използвай бяла повърхност за запълване. Дифузията омекотява сянката, но поглъща светлина. Провери трептенето на конкретната лампа при избраните настройки на камерата."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Не пипай шумопотискане, преди да премахнеш очевидната причина: далечен микрофон, свободен кабел, климатик или вятър. Постави приемника така, че да не закрива камерата; следи пиковете и слушай речта. За светлината провери тест с реална експозиция, отблясък в очите, детайл по лицето и цветни отражения от стените."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Изслушай стаята 20 секунди и изключи шумовете, които контролираш.\n2. Постави микрофона близо до устата и закрепи кабела без да докосва плат или коса.\n3. Запиши нормална и най-силна реплика; провери ги през слушалки.\n4. Премести човека спрямо прозореца или лампата, преди да увеличиш яркостта.\n5. Добави бяла повърхност от сенчестата страна само ако лицето губи детайл.\n6. Провери теста на телефон и отделен екран; повтори при смяна на място."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Интервю с готвач в работеща кухня. Аспираторът не може да се изключи. Вместо да чисти шума после, операторът приближава лавалиерния микрофон, избира по-тих ъгъл и записва тест по време на реалната работа. Прозорецът остава ключова светлина, а малка лампа връща детайл в очите.\n\nКритерий за добър ход: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице."},"after":{"label":"Как го поправяш","text":"Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Запиши едно изречение с три положения на микрофона и две положения на светлината. Изслушай шестте варианта при еднаква сила и сравни разбираемост, търкане, сенки и отблясъци.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Постави микрофона близо до устата и закрепи кабела без да докосва плат или коса. Премести човека спрямо прозореца или лампата, преди да увеличиш яркостта.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест.\n\nТестът е минал едва когато: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Интервю с готвач в работеща кухня. Аспираторът не може да се изключи. Вместо да чисти шума после, операторът приближава лавалиерния микрофон, избира по-тих ъгъл и записва тест по време на реалната работа. Прозорецът остава ключова светлина, а малка лампа връща детайл в очите.\n\nДоставката ти е: Запиши едно изречение с три положения на микрофона и две положения на светлината. Изслушай шестте варианта при еднаква сила и сравни разбираемост, търкане, сенки и отблясъци.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Shure обяснява позиционирането и характеристиките на микрофони: https://www.shure.com/en-US/docs/education/Microphone-Techniques-for-Recording"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Започни от причината","content":{"question":"Интервюто има силен шум от стаята. Кой е първият ход?","options":[{"id":"a","label":"Включи максимално шумопотискане върху целия диалог."},{"id":"b","label":"Вдигни усилването, за да компенсираш далечния микрофон."},{"id":"c","label":"Приближи микрофона, намали контролируемия шум и прослушай нов тест."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Позицията спрямо гласа често е по-важна от последващата обработка.\n\nВариантът „Включи максимално шумопотискане върху целия диалог.“ не доказва: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Вариантът „Вдигни усилването, за да компенсираш далечния микрофон.“ оставя нерешено: Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице. Безопасната корекция е: Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Шум от дрехата","content":{"prompt":"В слушалките чуваш търкане при завъртане. Как продължаваш?","options":[{"id":"a","label":"Преместваш микрофона по-далеч от говорещия."},{"id":"b","label":"Продължаваш, защото зрителят няма да забележи."},{"id":"c","label":"Пренареждаш микрофона и кабела, повтаряш движението и прослушваш нов тест."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Премахни механичния шум на площадката; шумодавът може да повреди речта.\n\nВариантът „Продължаваш, защото зрителят няма да забележи.“ не доказва: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Вариантът „Преместваш микрофона по-далеч от говорещия.“ оставя нерешено: Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице. Безопасната корекция е: Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Омекоти лицето","content":{"question":"Сянката под носа е твърда. Какво пробваш?","options":[{"id":"a","label":"Променяш посоката или видимия размер на източника и проверяваш нов кадър."},{"id":"b","label":"Вдигаш мощността и насочваш лампата право към лицето."},{"id":"c","label":"Изсветляваш всички сенки максимално в монтажа."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Посоката и размерът определят характера на сянката; повече мощност не омекотява светлина.\n\nВариантът „Вдигаш мощността и насочваш лампата право към лицето.“ не доказва: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Вариантът „Изсветляваш всички сенки максимално в монтажа.“ оставя нерешено: Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице. Безопасната корекция е: Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Смесен цвят","content":{"prompt":"Лицето е зеленикаво от таванните лампи, но прозорецът е чист. Какво правиш?","options":[{"id":"a","label":"Оставяш всички лампи и избираш произволен баланс на бялото."},{"id":"b","label":"Изключваш или изключваш от сцената зеления източник, после балансираш бялото спрямо ключовата светлина."},{"id":"c","label":"Коригираш оттенъка по памет след снимките."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Премахни цветен източник, когато той разваля кожата и не е сюжетно необходим.\n\nВариантът „Оставяш всички лампи и избираш произволен баланс на бялото.“ не доказва: Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл. Вариантът „Коригираш оттенъка по памет след снимките.“ оставя нерешено: Микрофонът остава върху телефона, а ярката лампа сочи директно към лъскаво лице. Безопасната корекция е: Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Премести човека спрямо прозореца или лампата, преди да увеличиш яркостта."},{"id":"s3","text":"Запиши нормална и най-силна реплика; провери ги през слушалки."},{"id":"s2","text":"Постави микрофона близо до устата и закрепи кабела без да докосва плат или коса."},{"id":"s1","text":"Изслушай стаята 20 секунди и изключи шумовете, които контролираш."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Изслушай стаята 20 секунди и изключи шумовете, които контролираш.\n2. Постави микрофона близо до устата и закрепи кабела без да докосва плат или коса.\n3. Запиши нормална и най-силна реплика; провери ги през слушалки.\n4. Премести човека спрямо прозореца или лампата, преди да увеличиш яркостта."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще поставиш микрофон и светлина така, че гласът да е разбираем, лицето да е четимо, а комплектът безопасен.","Приближи микрофона до източника, намали шума и промени позицията на светлината; оцени записан тест.","Гласът се разбира през телефонен говорител, няма пукане или търкане, а светлите части на лицето запазват детайл."],"nextStep":"Запиши едно изречение с три положения на микрофона и две положения на светлината. Изслушай шестте варианта при еднаква сила и сравни разбираемост, търкане, сенки и отблясъци."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-05","title":"Монтаж на телефона и AI функции: ускорявай без да губиш контрол","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще редактираш кратък клип на телефон, ще използваш автоматични инструменти като чернова и ще провериш финалния файл.","hook":"Автоматичните субтитри изглеждат почти правилни, но грешат името на лекарство и закриват логото на клиента.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще редактираш кратък клип на телефон, ще използваш автоматични инструменти като чернова и ще провериш финалния файл."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Автоматичните субтитри изглеждат почти правилни, но грешат името на лекарство и закриват логото на клиента."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Мобилното приложение може да ускори подрязване, синхронизация, субтитри и версии за различен формат. То не поема отговорността за смисъл, факти, съгласие или цвят. Транскриптът е чернова: провери собствени имена, числа, отрицания, пунктуация и паузи. Не качвай чувствителен материал в облачен инструмент, преди да разбереш условията за обработка.\n\nРаздели оригинали, монтаж и експорти. Не унищожавай оригинала с автоматично изрязване или презапис. За музика, шрифт, шаблон или стоков клип провери лиценз за клиентската и платформена употреба. При предаване кажи коя част е автоматично генерирана и коя е редактирана."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Малкият екран скрива кадър, който е твърде тъмен, текст върху лице или грешна последователност на думите. Изгледай експорта от начало до край; отвори субтитрите отделно и провери четливостта им спрямо речта. Ако AI инструментът изрязва паузи, сравни с оригинала: паузата може да пази смисъл или естествено дишане."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Импортирай копия и пази оригиналните медии отделно.\n2. Сглоби ясна чернова по брифа, преди автоматични ефекти и преходи.\n3. Генерирай транскрипт само ако е полезен; посочи езика и свери всяка реплика.\n4. Провери кадър по кадър за изрязано лице, продукт, лого или текст.\n5. Експортирай проба и гледай я на телефон със звук и без звук.\n6. Запази нова версия, изходен проект и бележка за лицензи и инструменти."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Клиент изпраща 40 секунди съвет от физиотерапевт и иска 25-секундно вертикално видео. Автоматичният инструмент предлага изрязване и субтитри. Монтажистът пази оригинала, проверява медицинските термини, връща важно уточнение, добавя читим надпис и експортира проба за одобрение.\n\nКритерий за добър ход: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед."},"after":{"label":"Как го поправяш","text":"Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Избери 20 секунди собствен говор. Създай транскрипт, отбележи грешките в имена, числа и паузи, коригирай ръчно и направи два варианта — със и без надписи. Провери ги на телефон.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Сглоби ясна чернова по брифа, преди автоматични ефекти и преходи. Провери кадър по кадър за изрязано лице, продукт, лого или текст.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат.\n\nТестът е минал едва когато: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Клиент изпраща 40 секунди съвет от физиотерапевт и иска 25-секундно вертикално видео. Автоматичният инструмент предлага изрязване и субтитри. Монтажистът пази оригинала, проверява медицинските термини, връща важно уточнение, добавя читим надпис и експортира проба за одобрение.\n\nДоставката ти е: Избери 20 секунди собствен говор. Създай транскрипт, отбележи грешките в имена, числа и паузи, коригирай ръчно и направи два варианта — със и без надписи. Провери ги на телефон.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe описва автоматичната транскрипция и редактирането на текст; провери резултата спрямо записа: https://helpx.adobe.com/premiere/desktop/add-text-images/insert-captions/auto-transcribe-video-using-speech-to-text.html"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Автоматичният текст е чернова","content":{"question":"Кога транскриптът е готов за клиент?","options":[{"id":"a","label":"Когато е избран правилният език, дори без прослушване."},{"id":"b","label":"Когато приложението няма червено подчертаване."},{"id":"c","label":"След сверяване дума по дума за имена, числа, отрицания и синхрон."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Сходно звучаща дума може да промени медицински, финансов или правен смисъл.\n\nВариантът „Когато приложението няма червено подчертаване.“ не доказва: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Вариантът „Когато е избран правилният език, дори без прослушване.“ оставя нерешено: Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед. Безопасната корекция е: Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Поверителен запис","content":{"prompt":"Записът съдържа данни на клиент, а облачното приложение не обяснява къде ги пази. Какво правиш?","options":[{"id":"a","label":"Не качваш материала, докато условията не са одобрени; ползваш разрешен или локален процес."},{"id":"b","label":"Качваш го за кратко и изтриваш проекта след експорта."},{"id":"c","label":"Премахваш логото, но оставяш имена и съдържание."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Изтриването след качване не доказва какво е било обработено. Провери условията преди качване.\n\nВариантът „Качваш го за кратко и изтриваш проекта след експорта.“ не доказва: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Вариантът „Премахваш логото, но оставяш имена и съдържание.“ оставя нерешено: Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед. Безопасната корекция е: Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Пази оригинала","content":{"question":"Защо оригиналните клипове трябва да останат отделно?","options":[{"id":"a","label":"Приложенията работят само при дублирани файлове."},{"id":"b","label":"Позволяват поправка, друг формат и предаване без загуба от презапис или автоматично изрязване."},{"id":"c","label":"Оригиналът винаги има по-добър цвят от експорта."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Непромененият източник може да се възстанови; експортираният клип е само един изход.\n\nВариантът „Приложенията работят само при дублирани файлове.“ не доказва: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Вариантът „Оригиналът винаги има по-добър цвят от експорта.“ оставя нерешено: Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед. Безопасната корекция е: Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Грешно име в надписа","content":{"prompt":"Субтитърът променя името на лекарство. Какво е първото действие?","options":[{"id":"a","label":"Изрязваш репликата, без да провериш дали смисълът остава."},{"id":"b","label":"Сверяваш го с аудиото и потвърденото изписване, после преглеждаш целия текст отново."},{"id":"c","label":"Оставяш автокорекцията, защото думата изглежда близка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Съдържанието трябва да е вярно. При съмнение поискай потвърждение, не предполагай.\n\nВариантът „Оставяш автокорекцията, защото думата изглежда близка.“ не доказва: Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство. Вариантът „Изрязваш репликата, без да провериш дали смисълът остава.“ оставя нерешено: Автоматичните субтитри се приемат за финални, оригиналът се изтрива и монтажът се експортира без преглед. Безопасната корекция е: Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Сглоби ясна чернова по брифа, преди автоматични ефекти и преходи."},{"id":"s3","text":"Генерирай транскрипт само ако е полезен; посочи езика и свери всяка реплика."},{"id":"s4","text":"Провери кадър по кадър за изрязано лице, продукт, лого или текст."},{"id":"s1","text":"Импортирай копия и пази оригиналните медии отделно."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Импортирай копия и пази оригиналните медии отделно.\n2. Сглоби ясна чернова по брифа, преди автоматични ефекти и преходи.\n3. Генерирай транскрипт само ако е полезен; посочи езика и свери всяка реплика.\n4. Провери кадър по кадър за изрязано лице, продукт, лого или текст."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще редактираш кратък клип на телефон, ще използваш автоматични инструменти като чернова и ще провериш финалния файл.","Пази оригинала, сверявай автоматичния текст със звука и гледай целия експорт в целевия формат.","Текстът съвпада с речта, оригиналът е запазен, надписите не закриват важен обект, а изходът се отваря на друго устройство."],"nextStep":"Избери 20 секунди собствен говор. Създай транскрипт, отбележи грешките в имена, числа и паузи, коригирай ръчно и направи два варианта — със и без надписи. Провери ги на телефон."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-06","title":"Една снимачна смяна, няколко готови формата","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще заснемеш материал за няколко формата, без да губиш важен детайл и място за кадриране.","hook":"Рекламният кадър е красив в хоризонтално видео, но вертикалната версия отрязва лицето и надписа върху опаковката.","estimated_minutes":35,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще заснемеш материал за няколко формата, без да губиш важен детайл и място за кадриране."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Рекламният кадър е красив в хоризонтално видео, но вертикалната версия отрязва лицето и надписа върху опаковката."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Планирай форматите преди запис. Ако са нужни вертикален и хоризонтален изход, направи отделни композиции или остави място за прекомпозиране. Централната зона не е универсална: интерфейс на платформа, субтитри и марка имат различни граници. Провери актуалното изискване на канала, вместо да използваш стара схема.\n\nСписъкът с кадри трябва да покрива действие, детайл, реакция и монтажни свръзки. Сними чист кадър без надпис и остави пауза до и след действието. Серийното снимане не означава една и съща поза дванадесет пъти.\n\nДопълнителен ход от практиката: Не снимай отделен клип за всяка форма, ако действието може да се заснеме веднъж с безопасно място за вертикално и хоризонтално кадриране. Но не разчитай на auto-reframe за критични надписи, продукт или двама говорители: провери всеки crop на целевия размер. В shot list маркирай кадри, които изискват отделен дубъл, текстова версия, лицензирана музика или преведени субтитри. Именувай output по канал и версия и потвърди с клиента къде всяка форма ще се публикува."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Смени едно нещо наведнъж: ориентация, ракурс, план или действие. Кажи на таланта кога започва дубълът, задръж кадър след движението и не закривай продукт с субтитри. За хоризонталния вариант провери дали има широк кадър, който показва мястото."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Извади от брифа форматите, продължителности, надписи и канали.\n2. Начертай рамка за всеки формат и маркирай зона за текст и интерфейс.\n3. Подреди shot list по сет и действие; отбележи отделните композиции.\n4. Сними установяващ кадър, действие, детайл, реакция и чисти свръзки.\n5. След ключов дубъл провери дали всеки формат пази лице, продукт и текст.\n6. Избери добър дубъл и запиши кога прекомпозиране не е подходящо."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Производител на чай иска 16:9 за сайт и 9:16 за социална публикация. В широкия кадър чашата и ръката са далеч една от друга. Екипът прави отделен вертикален детайл на наливането; не разчита, че изрязването ще запази парата и етикета.\n\nКритерий за добър ход: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон."},"after":{"label":"Как го поправяш","text":"Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Заснеми просто действие в широк и вертикален формат. Направи три кадъра за всеки и провери мащаба на лицето или продукта, текстовата зона и началото/края на действието.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Начертай рамка за всеки формат и маркирай зона за текст и интерфейс. Сними установяващ кадър, действие, детайл, реакция и чисти свръзки.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство.\n\nТестът е минал едва когато: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"YouTube публикува актуални препоръки за съотношение и резолюция; изискванията на целевия канал сверявай преди снимане: https://support.google.com/youtube/answer/6375112"},"points":0,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Планирай изходите","content":{"question":"Кога решаваш дали трябват отделни вертикални кадри?","options":[{"id":"a","label":"Преди снимките, когато форматът и мястото на надписите са част от брифа."},{"id":"b","label":"След като хоризонталният монтаж е заключен."},{"id":"c","label":"Когато автоматичното изрязване не разпознае лице."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Форматът влияе на композицията още на снимачната площадка.\n\nВариантът „След като хоризонталният монтаж е заключен.“ не доказва: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване. Вариантът „Когато автоматичното изрязване не разпознае лице.“ оставя нерешено: Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон. Безопасната корекция е: Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Отрязана опаковка","content":{"prompt":"В пробата за телефон етикетът излиза от кадър. Какво правиш?","options":[{"id":"a","label":"Оставяш го, понеже се вижда в 16:9."},{"id":"b","label":"Снимаш отделен вертикален дубъл с етикета в безопасната зона и място около него."},{"id":"c","label":"Увеличаваш цифровото приближение, докато влезе."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Отделен ракурс често запазва детайла по-добре от силно цифрово изрязване.\n\nВариантът „Оставяш го, понеже се вижда в 16:9.“ не доказва: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване. Вариантът „Увеличаваш цифровото приближение, докато влезе.“ оставя нерешено: Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон. Безопасната корекция е: Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Остави материал за монтаж","content":{"question":"За какво служат секундите преди и след действието?","options":[{"id":"a","label":"Нужни са само при хоризонтален формат."},{"id":"b","label":"Дават чисти точки за монтаж и позволяват движение да започне или завърши естествено."},{"id":"c","label":"Увеличават дължината без друга цел."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Handle-ите улесняват ритъма и могат да спестят повторно заснемане.\n\nВариантът „Увеличават дължината без друга цел.“ не доказва: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване. Вариантът „Нужни са само при хоризонтален формат.“ оставя нерешено: Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон. Безопасната корекция е: Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Искат и сайт, и сторис","content":{"prompt":"Клиентът добавя хоризонтален вариант след вертикалната снимка. Какво правиш?","options":[{"id":"a","label":"Проверяваш наличната ширина; за липсващото действие планираш допълнителен дубъл."},{"id":"b","label":"Обрязваш лицето, за да запълниш хоризонталния кадър."},{"id":"c","label":"Разпъваш вертикалното изображение до широк екран."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Не разтягай пропорции и не жертвай съдържание; договори нужната добавка.\n\nВариантът „Разпъваш вертикалното изображение до широк екран.“ не доказва: И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване. Вариантът „Обрязваш лицето, за да запълниш хоризонталния кадър.“ оставя нерешено: Всички кадри се записват хоризонтално, защото монтажистът ще ги изреже после за телефон. Безопасната корекция е: Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Начертай рамка за всеки формат и маркирай зона за текст и интерфейс."},{"id":"s1","text":"Извади от брифа форматите, продължителности, надписи и канали."},{"id":"s4","text":"Сними установяващ кадър, действие, детайл, реакция и чисти свръзки."},{"id":"s3","text":"Подреди shot list по сет и действие; отбележи отделните композиции."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Извади от брифа форматите, продължителности, надписи и канали.\n2. Начертай рамка за всеки формат и маркирай зона за текст и интерфейс.\n3. Подреди shot list по сет и действие; отбележи отделните композиции.\n4. Сними установяващ кадър, действие, детайл, реакция и чисти свръзки."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще заснемеш материал за няколко формата, без да губиш важен детайл и място за кадриране.","Запиши ключовото действие отделно във всеки нужен формат; изрязвай само ако източникът има достатъчно резолюция и пространство.","И двата формата имат установяващ кадър, детайл и свръзка; нищо важно не изчезва при реалното изрязване."],"nextStep":"Заснеми просто действие в широк и вертикален формат. Направи три кадъра за всеки и провери мащаба на лицето или продукта, текстовата зона и началото/края на действието."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-07","title":"Провери кадрите още на локацията","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще одитираш суровия материал, преди екипът и картите да напуснат мястото.","hook":"Снимките приключват и светлината е прибрана; в монтажната стая става ясно, че важният отговор е извън фокус.","estimated_minutes":31,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще одитираш суровия материал, преди екипът и картите да напуснат мястото."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Снимките приключват и светлината е прибрана; в монтажната стая става ясно, че важният отговор е извън фокус."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Проверявай по критериите, които могат да провалят задачата: покритие, фокус и експозиция, звук, непрекъснатост и наличност на файл. Галерията не доказва, че файлът е цял или микрофонът е записал правилния канал. Увеличи детайлите и прослушай ключовите реплики.\n\nПрави одита преди да местиш камера, таланти или реквизит. Ако има проблем, отбележи точно коя реплика или кадър липсва и направи pickup. Не форматирай карта, докато няма потвърдено копие извън телефона.\n\nДопълнителен ход от практиката: Провери веднага след дубъла, не в края на деня: файлът се отваря, последният кадър е цял, фокусът не е избягал, звукът не е отрязан и всички нужни реплики са налични. Запиши номера на дубъла и кратка бележка какво е различно; използвай slate/voice note, когато в кадъра няма slate. На следваща локация тествай отново радио връзка, шум и светлина. Не форматирай носител, преди поне едно проверено копие да е видимо на друг носител."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Провери дали клипът съдържа началото и края на репликата, дали очите и продуктът са на фокус, дали светлите части пазят детайл и звукът няма щракване. Свери бележката с номерата на клиповете. Ако копираш на място, провери броя файлове и отвори поне един оригинал от копието."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Сравни shot list с наличните файлове и маркирай пропуските.\n2. Изгледай начало, среда и край на ключовите клипове с увеличен екран.\n3. Прослушай всяка важна реплика; провери канал, пикове и фонов шум.\n4. Провери фокус, експозиция и дали кадърът не е закрит от ръка или аксесоар.\n5. Повтори липсващия кадър и отбележи добрия дубъл в листа.\n6. Направи копие и отвори файл от него преди форматиране на носителя."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"В интервюто има добър отговор, но дубълът започва след първата дума. Операторът проверява картата на място, намира че микрофонът е записал отделен канал и прави pickup на цялата реплика с пауза преди и след нея.\n\nКритерий за добър ход: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен."},"after":{"label":"Как го поправяш","text":"Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи одитен лист с покритие, фокус/експозиция, звук, непрекъснатост и копие. Провери три реални клипа и отбележи резултатите; ако кадър липсва, заснеми го отново.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Изгледай начало, среда и край на ключовите клипове с увеличен екран. Провери фокус, експозиция и дали кадърът не е закрит от ръка или аксесоар.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук.\n\nТестът е минал едва когато: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: В интервюто има добър отговор, но дубълът започва след първата дума. Операторът проверява картата на място, намира че микрофонът е записал отделен канал и прави pickup на цялата реплика с пауза преди и след нея.\n\nДоставката ти е: Направи одитен лист с покритие, фокус/експозиция, звук, непрекъснатост и копие. Провери три реални клипа и отбележи резултатите; ако кадър липсва, заснеми го отново.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Първо място за одит","content":{"question":"Кога проверяваш важните клипове?","options":[{"id":"a","label":"След като картата е форматирана."},{"id":"b","label":"Докато човекът, реквизитът и локацията са готови за повторение."},{"id":"c","label":"Когато монтажистът поиска нов дубъл."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Ранното откриване спестява повторна логистика и липсващ материал.\n\nВариантът „След като картата е форматирана.“ не доказва: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Вариантът „Когато монтажистът поиска нов дубъл.“ оставя нерешено: Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен. Безопасната корекция е: Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Неясен глас","content":{"prompt":"Миниатюрата изглежда добре, но не си чул звука. Какво правиш преди да освободиш госта?","options":[{"id":"a","label":"Добавяш компресия в монтажната програма."},{"id":"b","label":"Слушаш ключовите реплики през слушалки и при проблем повтаряш дубъла или записваш нужния тон."},{"id":"c","label":"Приемаш, че телефонът е записал, защото микрофонът светеше."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Индикацията не замества прослушването; отстрани дефекта на локацията, ако можеш.\n\nВариантът „Приемаш, че телефонът е записал, защото микрофонът светеше.“ не доказва: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Вариантът „Добавяш компресия в монтажната програма.“ оставя нерешено: Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен. Безопасната корекция е: Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери копието","content":{"question":"Кое доказва, че файлът е прехвърлен?","options":[{"id":"a","label":"Отваряш оригинал от новото място и проверяваш целия му ход."},{"id":"b","label":"Копираш само папка с миниатюри."},{"id":"c","label":"Виждаш папка със същото име."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Папката и иконата не доказват, че медиата е цяла.\n\nВариантът „Виждаш папка със същото име.“ не доказва: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Вариантът „Копираш само папка с миниатюри.“ оставя нерешено: Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен. Безопасната корекция е: Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Фокусът е избягал","content":{"prompt":"На ключовата реплика лицето е размазано. Кое решение е правилно?","options":[{"id":"a","label":"Оставяш го, защото малък екран скрива размазването."},{"id":"b","label":"Прилагаш sharpening до максимум върху клипа."},{"id":"c","label":"Проверяваш за друг остър дубъл; ако няма, повтаряш репликата с проверен фокус."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Оцени наличния материал честно и поправи заснемането, ако е възможно.\n\nВариантът „Оставяш го, защото малък екран скрива размазването.“ не доказва: Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие. Вариантът „Прилагаш sharpening до максимум върху клипа.“ оставя нерешено: Клипът се гледа като миниатюра, а звукът се приема за добър, защото нивомерът не е червен. Безопасната корекция е: Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Провери фокус, експозиция и дали кадърът не е закрит от ръка или аксесоар."},{"id":"s1","text":"Сравни shot list с наличните файлове и маркирай пропуските."},{"id":"s2","text":"Изгледай начало, среда и край на ключовите клипове с увеличен екран."},{"id":"s3","text":"Прослушай всяка важна реплика; провери канал, пикове и фонов шум."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Сравни shot list с наличните файлове и маркирай пропуските.\n2. Изгледай начало, среда и край на ключовите клипове с увеличен екран.\n3. Прослушай всяка важна реплика; провери канал, пикове и фонов шум.\n4. Провери фокус, експозиция и дали кадърът не е закрит от ръка или аксесоар."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще одитираш суровия материал, преди екипът и картите да напуснат мястото.","Проверявай с увеличен образ и слушалки. За критичен кадър потвърди съдържанието, цял дубъл и четим звук.","Показваш къде е всеки кадър от брифа, кой дубъл е избран и че файл се отваря от отделно копие."],"nextStep":"Направи одитен лист с покритие, фокус/експозиция, звук, непрекъснатост и копие. Провери три реални клипа и отбележи резултатите; ако кадър липсва, заснеми го отново."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-08","title":"60 минути от бриф до проверен файл","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще превърнеш ограничен бриф в един кратък клип, като разпределиш време и не прескочиш контрола.","hook":"Шейсет минути стигат за прост клип, но не и за неуточнен сценарий, пет локации и неограничени редакции.","estimated_minutes":45,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще превърнеш ограничен бриф в един кратък клип, като разпределиш време и не прескочиш контрола."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Шейсет минути стигат за прост клип, но не и за неуточнен сценарий, пет локации и неограничени редакции."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Спринтът е рамка за ограничен обхват, не обещание за всяко видео. Използвай една теза, един говорещ, една локация, одобрен текст и ясна дължина. Добави време за тест и предаване. Ако брифът изисква графика, права или множество монтажи, преоцени срока преди старта.\n\nРазпредели времето за подготовка, снимане, импорт, чернова, преглед и експорт. Записвай търсене на файлове и грешни дубъли. Не харчи целия буфер за украса; остави време за финален преглед и възпроизвеждане на експорта."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Преди таймера заключи формат, име на файл, лого, музикален лиценз, начин за одобрение и кой може да поиска поправка. Направи shot list от малко кадри. Таймерът свършва, когато клиентът получи линк или файл, не когато натиснеш Export."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. 0–8 минути: преформулирай целта, аудиторията, едно действие и задължителното твърдение.\n2. 8–18: подреди 4–6 кадъра; провери телефон, звук, светлина и място.\n3. 18–30: заснеми основното действие и резервен дубъл за трудните кадри.\n4. 30–42: импортирай и сглоби ясна последователност без украса.\n5. 42–52: провери субтитри, лого и музика, само ако са нужни.\n6. 52–60: експортирай, изгледай целия файл, провери името и изпрати статуса."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Пекарна иска 20-секунден клип за нов сладкиш: едно изречение от собственика, кадър на продукта и покана за поръчка. Няма актьор, външна локация или графика. Един час е реалистичен, ако има готови права, текст и одобрител.\n\nКритерий за добър ход: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4."},"after":{"label":"Как го поправяш","text":"Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи спринт за 15–25-секундно видео. Пусни таймер, запиши минутите за фазите и едно неочаквано забавяне. След експорта отбележи какво би махнал от обхвата при следващ поръчков срок.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: 8–18: подреди 4–6 кадъра; провери телефон, звук, светлина и място. 30–42: импортирай и сглоби ясна последователност без украса.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук.\n\nТестът е минал едва когато: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Пекарна иска 20-секунден клип за нов сладкиш: едно изречение от собственика, кадър на продукта и покана за поръчка. Няма актьор, външна локация или графика. Един час е реалистичен, ако има готови права, текст и одобрител.\n\nДоставката ти е: Направи спринт за 15–25-секундно видео. Пусни таймер, запиши минутите за фазите и едно неочаквано забавяне. След експорта отбележи какво би махнал от обхвата при следващ поръчков срок.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"field_note_1","block_type":"rich_text","title":"Кога преоценяваш","content":{"body":"Без одобрен текст, права, локация или отговорен одобрител спринтът започва след изчистване на блокиращото условие."},"points":1,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Договори реалния обхват","content":{"question":"Кога едночасовият срок е приемлив?","options":[{"id":"a","label":"Когато монтажистът прескочи проверката."},{"id":"b","label":"Когато съдържанието, локацията, правата и одобрението са ясни, а обхватът е ограничен."},{"id":"c","label":"При всяко видео под 60 секунди."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Кратката дължина не значи проста продукция; обхватът прави срока възможен.\n\nВариантът „При всяко видео под 60 секунди.“ не доказва: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Вариантът „Когато монтажистът прескочи проверката.“ оставя нерешено: Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4. Безопасната корекция е: Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Брифът се разширява","content":{"prompt":"Клиентът добавя две локации и втори език след старта. Как реагираш?","options":[{"id":"a","label":"Преоценяваш срока, показваш влиянието и договаряш нов обхват или дата."},{"id":"b","label":"Продължаваш мълчаливо и изпращаш непълен файл."},{"id":"c","label":"Пропускаш проверка на субтитрите."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Професионалистът прави промяната видима и пази качеството и доверието.\n\nВариантът „Пропускаш проверка на субтитрите.“ не доказва: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Вариантът „Продължаваш мълчаливо и изпращаш непълен файл.“ оставя нерешено: Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4. Безопасната корекция е: Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Последно след експорта","content":{"question":"Коя дейност задължително остава след експорта?","options":[{"id":"a","label":"Незабавна смяна към следващия клиент."},{"id":"b","label":"Изтриване на изходния монтаж."},{"id":"c","label":"Пълно възпроизвеждане и проверка на име, формат, звук и линк."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Експортът може да прекъсне или да приложи грешни настройки; отвори готовия файл.\n\nВариантът „Незабавна смяна към следващия клиент.“ не доказва: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Вариантът „Изтриване на изходния монтаж.“ оставя нерешено: Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4. Безопасната корекция е: Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Тесен срок","content":{"prompt":"Остават пет минути, а музиката няма потвърден лиценз. Какво правиш?","options":[{"id":"a","label":"Оставяш музиката тиха, без да кажеш на клиента."},{"id":"b","label":"Ползваш популярна песен за еднократна публикация."},{"id":"c","label":"Махаш я, проверяваш диалога и изпращаш чист вариант или съгласуваш промяната."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Правата са част от доставката. Предпочети чисто предаване пред неизвестен риск.\n\nВариантът „Ползваш популярна песен за еднократна публикация.“ не доказва: Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано. Вариантът „Оставяш музиката тиха, без да кажеш на клиента.“ оставя нерешено: Времето отива за шрифт и преходи; файлът се изпраща без гледане и се казва final_final2.mp4. Безопасната корекция е: Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"30–42: импортирай и сглоби ясна последователност без украса."},{"id":"s3","text":"18–30: заснеми основното действие и резервен дубъл за трудните кадри."},{"id":"s2","text":"8–18: подреди 4–6 кадъра; провери телефон, звук, светлина и място."},{"id":"s1","text":"0–8 минути: преформулирай целта, аудиторията, едно действие и задължителното твърдение."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. 0–8 минути: преформулирай целта, аудиторията, едно действие и задължителното твърдение.\n2. 8–18: подреди 4–6 кадъра; провери телефон, звук, светлина и място.\n3. 18–30: заснеми основното действие и резервен дубъл за трудните кадри.\n4. 30–42: импортирай и сглоби ясна последователност без украса."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще превърнеш ограничен бриф в един кратък клип, като разпределиш време и не прескочиш контрола.","Заключи обхват и защити буфер за QA. Провери файла като получател: отваря ли се, правилно ли е ориентиран и има ли звук.","Получателят отваря правилния файл и вижда едно ясно послание. Проверени са титри, ориентация и звук; фазовото време е записано."],"nextStep":"Направи спринт за 15–25-секундно видео. Пусни таймер, запиши минутите за фазите и едно неочаквано забавяне. След експорта отбележи какво би махнал от обхвата при следващ поръчков срок."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-09","title":"Комплект до 300 €: поправи първо най-слабата връзка","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще разпределиш малък бюджет според реалните проблеми в снимането, без да купуваш техника за чужд бриф.","hook":"Нова камера е купена, но интервютата продължават да звучат далечно и файловете се губят между приложенията.","estimated_minutes":35,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще разпределиш малък бюджет според реалните проблеми в снимането, без да купуваш техника за чужд бриф."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Нова камера е купена, но интервютата продължават да звучат далечно и файловете се губят между приложенията."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"До 300 € не купувай камера, преди да знаеш какво пречи на сегашната. За разговор често най-голямата полза е близък микрофон; за статична демонстрация — устойчива опора; за лице до прозорец — отражател или подходяща лампа. Остави бюджет за кабели, карта, адаптер и резерв.\n\nЦените се сменят. Сравнявай общата цена с доставка, съвместимост, гаранция и бъдеща употреба. Не приемай, че евтино значи лошо или че скъп аксесоар ще пасне на телефона.\n\nРаботна проверка: Сравни три реални кошници: комплект от наличното, наем на слабата част и покупка на цял пакет. Включи време за връщане, доставка, съвместимост, повреда и кой ще носи резерв. Ако проблемът е шумна стая, нов телефон няма да поправи акустиката; ако липсва звук, първата инвестиция вероятно е микрофон или оператор. Избери най-малката промяна, която минава повторяем тест.\n\nДопълнителен ход от практиката: Подреди бюджета според риска за клиента: разбираем говор обикновено струва повече от декоративен аксесоар, а резервното копие пази цялата смяна. Раздели задължително, резерв и подобрение; запиши данък, доставка, адаптери и заместваща част. Тествай най-слабата връзка с един реален дубъл и слушай суровия запис със слушалки. Ако парите не стигат за резервен микрофон, предвиди наем и задай ясно какво става при повреда; не обещавай безотказност на единична част."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Подреди ограниченията по щета и честота. Ако звукът се проваля на всяко интервю, микрофонът може да спести повече от нова лампа. Ако интервютата са стабилни, но няма копие, носителят е по-важен от ефектен аксесоар. Запиши три реални задачи от следващия месец и свери покупката с тях."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Опиши три типа видеа и най-честия технически проблем във всяко.\n2. Избери един bottleneck, който пречи на годен материал или губи време.\n3. Сравни телефон, микрофон, опора, светлина, носител и адаптери по съвместимост и обща цена.\n4. Остави резерв за доставка, кабел или ремонт; не харчи сумата на хартия.\n5. Пробвай наем, заем или тестов комплект, ако съвместимостта е неясна.\n6. Повтори същия кадър след покупката и измери какво се подобри."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Самостоятелен треньор снима уроци у дома. Проблемът е отекващият глас и треперещ телефон, а прозорецът дава достатъчно светлина. Планът дава приоритет на микрофон, стойка и правилен адаптер; LED панелът отпада, докато тестът не покаже нужда.\n\nКритерий за добър ход: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис."},"after":{"label":"Как го поправяш","text":"Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи три кошници: нужно днес, полезно при конкретен вид работа и засега ненужно. За всяка покупка запиши съвместимост, цена с адаптери, решаван проблем и тест на ефекта.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Избери един bottleneck, който пречи на годен материал или губи време. Остави резерв за доставка, кабел или ремонт; не харчи сумата на хартия.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката.\n\nТестът е минал едва когато: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Къде отива бюджетът","content":{"question":"Нямаш пари за всичко. Как подреждаш покупките?","options":[{"id":"a","label":"По риска за използваемия материал и честотата, с която проблемът се появява."},{"id":"b","label":"Първо купуваш най-скъпия компонент за бъдещето."},{"id":"c","label":"По реда на новите модели в магазина."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Измерим bottleneck показва къде вложението може да върне време или качество.\n\nВариантът „По реда на новите модели в магазина.“ не доказва: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв. Вариантът „Първо купуваш най-скъпия компонент за бъдещето.“ оставя нерешено: Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис. Безопасната корекция е: Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Камера или микрофон","content":{"prompt":"Кадърът е приемлив, но клиентите връщат клип за неясен говор. Какво проверяваш?","options":[{"id":"a","label":"Камера с повече мегапиксели."},{"id":"b","label":"Добавяш субтитри, без да поправиш звука."},{"id":"c","label":"Микрофон, адаптер, място и мониторинг с реален запис."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Повтори проблема и избери покупката, която отстранява причината.\n\nВариантът „Камера с повече мегапиксели.“ не доказва: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв. Вариантът „Добавяш субтитри, без да поправиш звука.“ оставя нерешено: Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис. Безопасната корекция е: Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Сметни цялата покупка","content":{"question":"Кое сравнение е пълно?","options":[{"id":"a","label":"Броят функции, отпечатани на опаковката."},{"id":"b","label":"Само цената на корпуса."},{"id":"c","label":"Устройство, адаптери, стойка, захранване, доставка, гаранция и връщане."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Аксесоар без съвместима връзка или монтаж е неизползваем.\n\nВариантът „Само цената на корпуса.“ не доказва: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв. Вариантът „Броят функции, отпечатани на опаковката.“ оставя нерешено: Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис. Безопасната корекция е: Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Офертата изтича","content":{"prompt":"Не знаеш дали стойката пасва, а отстъпката важи само днес. Какво правиш?","options":[{"id":"a","label":"Проверяваш размер, товароносимост и връщане; пропускаш покупката, ако съвместимостта е неясна."},{"id":"b","label":"Купуваш, защото отстъпката е по-важна от теста."},{"id":"c","label":"Поръчваш два модела без да планираш връщане."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Спешността не е техническо доказателство; съвместимостта и условията са част от цената.\n\nВариантът „Купуваш, защото отстъпката е по-важна от теста.“ не доказва: Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв. Вариантът „Поръчваш два модела без да планираш връщане.“ оставя нерешено: Купува се камера, защото спецификациите изглеждат професионално, без бюджет за оптика, звук, опора и запис. Безопасната корекция е: Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Избери един bottleneck, който пречи на годен материал или губи време."},{"id":"s3","text":"Сравни телефон, микрофон, опора, светлина, носител и адаптери по съвместимост и обща цена."},{"id":"s4","text":"Остави резерв за доставка, кабел или ремонт; не харчи сумата на хартия."},{"id":"s1","text":"Опиши три типа видеа и най-честия технически проблем във всяко."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Опиши три типа видеа и най-честия технически проблем във всяко.\n2. Избери един bottleneck, който пречи на годен материал или губи време.\n3. Сравни телефон, микрофон, опора, светлина, носител и адаптери по съвместимост и обща цена.\n4. Остави резерв за доставка, кабел или ремонт; не харчи сумата на хартия."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще разпределиш малък бюджет според реалните проблеми в снимането, без да купуваш техника за чужд бриф.","Похарчи първо за доказан bottleneck и провери ефекта със същия кадър преди и след покупката.","Списъкът има проблем, доказателство, обща цена и тест на резултата; бюджетът пази резерв."],"nextStep":"Направи три кошници: нужно днес, полезно при конкретен вид работа и засега ненужно. За всяка покупка запиши съвместимост, цена с адаптери, решаван проблем и тест на ефекта."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-10","title":"До 700 €: надгради само онова, което вече ползваш","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще планираш следващото ниво на мобилен комплект и ще провериш дали покупката спестява време в повтаряща се работа.","hook":"Аксесоарите се наслагват; телефонът е тежък, батерията не стига и никой не е тествал комплекта като система.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще планираш следващото ниво на мобилен комплект и ще провериш дали покупката спестява време в повтаряща се работа."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Аксесоарите се наслагват; телефонът е тежък, батерията не стига и никой не е тествал комплекта като система."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"До 700 € можеш да увеличиш надеждността, но всяка част трябва да служи на повтарящи се задачи. Затвори пропуските в базовия комплект: мониторинг, съвместима опора, захранване, място и светлина, която не трепти при настройките ти. Не купувай функции, които телефонът вече изпълнява.\n\nИзчисли общото тегло, времето за сглобяване и броя работни дни. Аксесоар, който спестява пет минути веднъж на тримесечие, може да не оправдава цената. Остави основен комплект, който можеш да носиш сам.\n\nПолеви наръчник: Преди покупка назови кои платени задачи ще използват новата част, колко пъти месечно и коя загуба премахва: лош говор, повреден кадър, бавен трансфер или неудобен монтаж. Смятай целия комплект: съвместим адаптер, батерии, карта, калъф, кабели, резерв и време за настройка. Поискай тест и пробвай с точния телефон/камера и софтуер. Включи и поддръжката: батерията е консуматив, безжичният микрофон има ограничен обхват, а стативът трябва да държи тежестта. Ако покупката не отстранява измерим тесен участък, остави бюджета за наем, резерв или монтаж.\n\nРаботна проверка: Определи кой ще използва новата техника, къде се пази и кой отговаря за заряд, актуализация и връщане. Запиши дата на теста, купена версия, гаранция и резервна съвместима част. Провери и споделен сценарий: друг оператор получава комплекта с кратка карта и успява да го настрои без устна помощ. Това показва дали покупката вдига капацитета на екипа или само прави един човек по-бърз.\n\nДопълнителен ход от практиката: Сравни цената за покупка с наем и цена на използваем клип за разумен период на ползване. Добави консумативи, сервиз, обучение, престой при повреда и стойността на старото оборудване. Провери кой подписва приемането, къде стои серийният номер и какво се случва при загуба. Направи изчисление при ниско и очаквано използване; ако сметката е положителна само при пълна заетост всяка седмица, планът няма резерв за реалната работа."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Направи проба с пълната сборка: държач, микрофон, лампа, батерия, кабели и кейс. Телефонът трябва да се завърта вертикално и хоризонтално без да изпуска връзка или да закрива камера. Провери дали зарядното внася шум; записвай с финалната сглобка, не с отделен аксесоар."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Събери реалните записи и отбележи забавянията и отказите.\n2. Избери един надграждащ компонент и резерв, които решават тези проблеми.\n3. Сглоби всички части и провери вертикална и хоризонтална конфигурация.\n4. Запиши с включено и изключено захранване; сравни звук и нивомер.\n5. Времи сглобяване, прехвърляне и смяна на режим.\n6. Сравни обща цена с наем за следващите шест месеца."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Агенция прави четири интервюта седмично и иска втори микрофон. Тестът показва, че текущият звук е годен, а истинското забавяне е прехвърляне към лаптопа. Бюджетът първо отива в сигурен ingest и резервен носител.\n\nКритерий за добър ход: Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум."},"after":{"label":"Как го поправяш","text":"Провери целия риг във всички планирани ориентации и при реално захранване."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи бюджет до 700 € за един работен тип. Сравни покупка, наем и сегашния комплект за шест месеца; добави време за настройка, транспорт, кабели и ремонт.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Оцени възвръщаемостта","content":{"question":"Кога има смисъл да надградиш компонент?","options":[{"id":"a","label":"Когато моделът току-що е излязъл."},{"id":"b","label":"Когато колега го е купил."},{"id":"c","label":"Когато повтарящ се проблем се измерва и новото устройство подобрява достатъчно реални задачи."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Ползата се оценява по употреба, време и разход, не по новост.\n\nВариантът „Когато моделът току-що е излязъл.“ не доказва: Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време. Вариантът „Когато колега го е купил.“ оставя нерешено: Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум. Безопасната корекция е: Провери целия риг във всички планирани ориентации и при реално захранване. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Ригът губи порт","content":{"prompt":"При завъртане към вертикал кабелът на приемника се измъква. Какво правиш?","options":[{"id":"a","label":"Снимаш само хоризонтално, без да кажеш на клиента."},{"id":"b","label":"Залепяш конектора по време на интервюто."},{"id":"c","label":"Променяш маршрута на кабела или монтажа, после тестваш ориентация и звук."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Критичните връзки трябва да работят в очакваните ориентации и движение.\n\nВариантът „Залепяш конектора по време на интервюто.“ не доказва: Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време. Вариантът „Снимаш само хоризонтално, без да кажеш на клиента.“ оставя нерешено: Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум. Безопасната корекция е: Провери целия риг във всички планирани ориентации и при реално захранване. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Не плащай два пъти","content":{"question":"Какво предшества покупка на втори микрофон?","options":[{"id":"a","label":"Проверка дали сегашният микрофон и прехвърлянето му работят за видовете задачи."},{"id":"b","label":"Покупка на втори приемник без тест."},{"id":"c","label":"Намаляване на качеството, докато чуеш записа."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Затвори настоящия bottleneck, после оцени нуждата от резерв.\n\nВариантът „Покупка на втори приемник без тест.“ не доказва: Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време. Вариантът „Намаляване на качеството, докато чуеш записа.“ оставя нерешено: Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум. Безопасната корекция е: Провери целия риг във всички планирани ориентации и при реално захранване. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Захранването внася шум","content":{"prompt":"При зареждане в звука има брум. Какво правиш?","options":[{"id":"a","label":"Вдигаш шумопотискането и приемаш резултата."},{"id":"b","label":"Сравняваш със захранване изключено, проверяваш кабел и адаптер, избираш чиста конфигурация."},{"id":"c","label":"Скриваш кабела, без нов тест."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Промяната на захранване променя аудио веригата; тествай финалния комплект.\n\nВариантът „Вдигаш шумопотискането и приемаш резултата.“ не доказва: Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време. Вариантът „Скриваш кабела, без нов тест.“ оставя нерешено: Към телефона се добавят лампа, клетка, батерия и приемник, без тест за достъп до портове, баланс и шум. Безопасната корекция е: Провери целия риг във всички планирани ориентации и при реално захранване. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Избери един надграждащ компонент и резерв, които решават тези проблеми."},{"id":"s1","text":"Събери реалните записи и отбележи забавянията и отказите."},{"id":"s4","text":"Запиши с включено и изключено захранване; сравни звук и нивомер."},{"id":"s3","text":"Сглоби всички части и провери вертикална и хоризонтална конфигурация."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Събери реалните записи и отбележи забавянията и отказите.\n2. Избери един надграждащ компонент и резерв, които решават тези проблеми.\n3. Сглоби всички части и провери вертикална и хоризонтална конфигурация.\n4. Запиши с включено и изключено захранване; сравни звук и нивомер."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще планираш следващото ниво на мобилен комплект и ще провериш дали покупката спестява време в повтаряща се работа.","Провери целия риг във всички планирани ориентации и при реално захранване.","Всяка покупка решава посочен проблем, общата сума остава под лимита с резерв, а ригът минава тест за звук, ориентация, захранване и време."],"nextStep":"Направи бюджет до 700 € за един работен тип. Сравни покупка, наем и сегашния комплект за шест месеца; добави време за настройка, транспорт, кабели и ремонт."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-11","title":"До 1500 €: резерв и цена на използваемия клип","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще превърнеш среден бюджет в надежден комплект с резервен план и реалистична цена на продукцията.","hook":"Екипът има добър телефон и микрофон, но едно повредено гнездо отменя цял снимачен ден.","estimated_minutes":43,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще превърнеш среден бюджет в надежден комплект с резервен план и реалистична цена на продукцията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Екипът има добър телефон и микрофон, но едно повредено гнездо отменя цял снимачен ден."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"На това ниво бюджетът трябва да купи надеждност, не само спецификация. Разгледай резервен запис, втори носител, батерия, кабел и защитен транспорт. Първо подсигури частите, чиято повреда спира цялата работа.\n\nИзчисли цена на използваем клип: подготовка, снимане, монтаж, транспорт, лицензи, амортизация и поправки. При рядка употреба наемът може да е по-добър от покупка. При седмични задачи стандартният комплект спестява време, но провери съвместимост при обновяване на телефон или приложение."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Задай граница за преносимост и човекочасове. Постави резерв в отделна чанта и провери, че екипът знае как да го използва. Картите и батериите са консумативи; не ги планирай до пълния капацитет. Фърмуер се обновява между проекти, не точно преди платена снимка."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Изчисли снимачните дни за 12 месеца и цената на наем за същия период.\n2. Начертай веригата и огради единичните точки на отказ.\n3. Избери резерв за най-скъпото прекъсване и предвиди място, захранване и поддръжка.\n4. Назначи кой тества, зарежда и връща всеки компонент.\n5. Проведи репетиция с основния и резервния маршрут.\n6. Изчисли цена на използваем клип и актуализирай офертата си."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Медийно студио снима пет интервюта месечно. Рискът е липса на резерв при прекъснал запис. Част от бюджета остава за втори аудио маршрут и носители; камерата за редки външни кадри се наема според поръчката.\n\nКритерий за добър ход: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем."},"after":{"label":"Как го поправяш","text":"Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Сметни комплект до 1500 € за интервю, продуктова снимка и събитие. Отбележи общото оборудване, наемните позиции, резервната точка, употребата и хода при отказ.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Начертай веригата и огради единичните точки на отказ. Назначи кой тества, зарежда и връща всеки компонент.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка.\n\nТестът е минал едва когато: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Медийно студио снима пет интервюта месечно. Рискът е липса на резерв при прекъснал запис. Част от бюджета остава за втори аудио маршрут и носители; камерата за редки външни кадри се наема според поръчката.\n\nДоставката ти е: Сметни комплект до 1500 € за интервю, продуктова снимка и събитие. Отбележи общото оборудване, наемните позиции, резервната точка, употребата и хода при отказ.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"field_note_1","block_type":"rich_text","title":"Планирай подмяната","content":{"body":"Запиши за всяка батерия, карта и кабел по какво ще познаеш, че трябва да излезе от работа. Не чакай повредата да е на локацията."},"points":1,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Изолирай риска","content":{"question":"Кое трябва да получи резерв първо?","options":[{"id":"a","label":"Най-новият елемент."},{"id":"b","label":"Аксесоар, който подобрява кадъра, но не е нужен."},{"id":"c","label":"Компонент, чиято повреда спира поръчката и няма лесна замяна."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Резервирай най-скъпия отказ, не най-видимата покупка.\n\nВариантът „Аксесоар, който подобрява кадъра, но не е нужен.“ не доказва: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Вариантът „Най-новият елемент.“ оставя нерешено: Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем. Безопасната корекция е: Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Едно USB-C гнездо","content":{"prompt":"Портът на телефона отказва по време на интервю. Как спасяваш работата?","options":[{"id":"a","label":"Преминаваш към предварително тестван резервен запис и проверяваш синхрона."},{"id":"b","label":"Включваш всеки адаптер от чантата, докато нещо проработи."},{"id":"c","label":"Продължаваш без микрофон и обещаваш да чистиш звука."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Резервният маршрут трябва да е изпитан и да запазва използваем диалог.\n\nВариантът „Включваш всеки адаптер от чантата, докато нещо проработи.“ не доказва: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Вариантът „Продължаваш без микрофон и обещаваш да чистиш звука.“ оставя нерешено: Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем. Безопасната корекция е: Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Купи или наеми","content":{"question":"Кога наемът заслужава предпочитание?","options":[{"id":"a","label":"Когато наемът не изисква тест."},{"id":"b","label":"Когато техниката е нужна рядко, специфична е и пълният наем струва по-малко от притежанието."},{"id":"c","label":"Винаги, защото собствената техника се износва."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Сравни доставка, обучение, застраховка и риск, не само цената за ден.\n\nВариантът „Когато наемът не изисква тест.“ не доказва: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Вариантът „Винаги, защото собствената техника се износва.“ оставя нерешено: Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем. Безопасната корекция е: Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Обновяване преди клиента","content":{"prompt":"Приложението предлага голяма актуализация вечерта преди снимките. Какво правиш?","options":[{"id":"a","label":"Обновяваш само телефона, без да тестваш приложението."},{"id":"b","label":"Оставяш работната система непроменена до края на проекта и тестваш новата отделно."},{"id":"c","label":"Инсталираш, защото новата версия може да подобри камерата."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Променяй стабилна конфигурация в тестов прозорец, не преди платена снимка.\n\nВариантът „Инсталираш, защото новата версия може да подобри камерата.“ не доказва: Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат. Вариантът „Обновяваш само телефона, без да тестваш приложението.“ оставя нерешено: Целият бюджет отива за корпус, но няма резервен аудио маршрут, копие или план за наем. Безопасната корекция е: Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Назначи кой тества, зарежда и връща всеки компонент."},{"id":"s1","text":"Изчисли снимачните дни за 12 месеца и цената на наем за същия период."},{"id":"s2","text":"Начертай веригата и огради единичните точки на отказ."},{"id":"s3","text":"Избери резерв за най-скъпото прекъсване и предвиди място, захранване и поддръжка."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Изчисли снимачните дни за 12 месеца и цената на наем за същия период.\n2. Начертай веригата и огради единичните точки на отказ.\n3. Избери резерв за най-скъпото прекъсване и предвиди място, захранване и поддръжка.\n4. Назначи кой тества, зарежда и връща всеки компонент."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще превърнеш среден бюджет в надежден комплект с резервен план и реалистична цена на продукцията.","Раздели сумата на основна система, критичен резерв, транспорт/съхранение и поддръжка.","Всяка задача има основен и резервен път за звук и запис; сметката е под лимита и отчита цена на използваем резултат."],"nextStep":"Сметни комплект до 1500 € за интервю, продуктова снимка и събитие. Отбележи общото оборудване, наемните позиции, резервната точка, употребата и хода при отказ."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-12","title":"Над 5000 €: купи работна система, не витрина","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще защитиш голяма инвестиция чрез натоварване, нужди на екипа, наем и срок на използване.","hook":"Купена е професионална камера, но никой не може да настрои цвета, да копира медията и да върне проекта на монтажиста.","estimated_minutes":48,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще защитиш голяма инвестиция чрез натоварване, нужди на екипа, наем и срок на използване."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Купена е професионална камера, но никой не може да настрои цвета, да копира медията и да върне проекта на монтажиста."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Голям бюджет оправдава стандартизирана система, когато обемът и клиентските изисквания я налагат. Определи кой снима, записва звук, копира материал, монтира и одобрява. После избери съвместими камера, оптика, звук, светлина, носители, захранване, транспорт и мониторинг. Купи това, което използваш често; специфичната оптика или рекордер може да се наемат.\n\nПредвиди поддръжка, батерии, калибрация, обучение, съхранение и ремонт. Цветовият профил има стойност, ако постпродукцията може да го обработи и клиентът приема изхода. Голяма сума не отстранява липсата на дисциплина."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Преди покупка тествай процеса с нает комплект: снимане, синхрон, копиране, монтаж, цветова корекция и експорт. Провери рендер, място, общо тегло, цена на монтажен ден и време за подготовка. Направи демонстрация с критерии за приемане, а не само със спецификация от каталога."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Събери последните 10 брифа и извлечи общите изисквания към кадър, звук и срок.\n2. Раздели задължителните възможности от редките нужди, които ще наемаш.\n3. Наеми пилотния комплект и изпълни задача с реалния екип и софтуер.\n4. Запиши време за подготовка, копиране, рендер и предаване; събери проблемите.\n5. Сметни общата цена за няколко години и сравни с наем, ремонт и обучение.\n6. Вземи решение с бюджет, собственик, резерв и процедура за обновяване."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Студио продава месечни пакети интервюта и продуктови клипове. Екипът наема две конфигурации за месец: една с допълнителна цветова корекция и една мобилна. След сравнение на клиентския резултат, монтажа и носителите купува само често използвания комплект.\n\nКритерий за добър ход: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет."},"after":{"label":"Как го поправяш","text":"Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Подготви инвестиционна бележка за техника над 5000 €: поръчки, наем срещу покупка, пълна цена за три години, капацитет, резерви и критерий за отказ.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Раздели задължителните възможности от редките нужди, които ще наемаш. Запиши време за подготовка, копиране, рендер и предаване; събери проблемите.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания.\n\nТестът е минал едва когато: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Студио продава месечни пакети интервюта и продуктови клипове. Екипът наема две конфигурации за месец: една с допълнителна цветова корекция и една мобилна. След сравнение на клиентския резултат, монтажа и носителите купува само често използвания комплект.\n\nДоставката ти е: Подготви инвестиционна бележка за техника над 5000 €: поръчки, наем срещу покупка, пълна цена за три години, капацитет, резерви и критерий за отказ.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Система преди спецификация","content":{"question":"Какво стои начело на инвестиционното решение?","options":[{"id":"a","label":"Повтарящите се изисквания на брифовете и хората, които ще снимат, монтират и предават."},{"id":"b","label":"Най-високият динамичен диапазон в бюджета."},{"id":"c","label":"Две камери, които изглеждат еднакво в каталога."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Системата включва хора и прехвърляне на медия, не само камера.\n\nВариантът „Най-високият динамичен диапазон в бюджета.“ не доказва: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Вариантът „Две камери, които изглеждат еднакво в каталога.“ оставя нерешено: Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет. Безопасната корекция е: Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Неподготвен Log","content":{"prompt":"Наетата камера записва Log, но монтажът няма цветово управление, а клиентът иска бърз файл. Какво правиш?","options":[{"id":"a","label":"Оставяш плоския Log образ за финал."},{"id":"b","label":"Ползваш тестван профил или първо подготвяш и тестваш целия процес за цветова корекция."},{"id":"c","label":"Вдигаш наситеността на око при експорта."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Суровият профил има стойност, когато монтажната верига може да го обработи.\n\nВариантът „Оставяш плоския Log образ за финал.“ не доказва: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Вариантът „Вдигаш наситеността на око при експорта.“ оставя нерешено: Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет. Безопасната корекция е: Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Пълният разход","content":{"question":"Кой разход често липсва в първата сметка?","options":[{"id":"a","label":"Нищо: производителят включва всичко в корпуса."},{"id":"b","label":"Оптика, носители, батерии, транспорт, ремонт, калибрация, обучение и монтажен капацитет."},{"id":"c","label":"Само цената на шрифта за титри."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Цената на системата надвишава цената на основното тяло.\n\nВариантът „Само цената на шрифта за титри.“ не доказва: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Вариантът „Нищо: производителят включва всичко в корпуса.“ оставя нерешено: Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет. Безопасната корекция е: Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Рядък обектив","content":{"prompt":"Обективът трябва два пъти годишно, а наемът включва тест и застраховка. Какво сравняваш?","options":[{"id":"a","label":"Общата цена на притежание и реалната честота спрямо целия разход за наем."},{"id":"b","label":"Отказваш наем без да сметнеш монтажния ефект."},{"id":"c","label":"Купуваш го, защото бюджетът трябва да се похарчи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Избери по употребата и общите разходи, не по размера на бюджета.\n\nВариантът „Купуваш го, защото бюджетът трябва да се похарчи.“ не доказва: Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ. Вариантът „Отказваш наем без да сметнеш монтажния ефект.“ оставя нерешено: Камерата е избрана по динамичен диапазон, без разход за оптика, логистика, съхранение и монтажен капацитет. Безопасната корекция е: Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Запиши време за подготовка, копиране, рендер и предаване; събери проблемите."},{"id":"s3","text":"Наеми пилотния комплект и изпълни задача с реалния екип и софтуер."},{"id":"s2","text":"Раздели задължителните възможности от редките нужди, които ще наемаш."},{"id":"s1","text":"Събери последните 10 брифа и извлечи общите изисквания към кадър, звук и срок."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Събери последните 10 брифа и извлечи общите изисквания към кадър, звук и срок.\n2. Раздели задължителните възможности от редките нужди, които ще наемаш.\n3. Наеми пилотния комплект и изпълни задача с реалния екип и софтуер.\n4. Запиши време за подготовка, копиране, рендер и предаване; събери проблемите."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще защитиш голяма инвестиция чрез натоварване, нужди на екипа, наем и срок на използване.","Тествай наетата система през целия процес и сравни цената с приход, натоварване и клиентски изисквания.","Инвестицията има измерена употреба; целият процес е тестван, има отговорник и план за ремонт или наем при отказ."],"nextStep":"Подготви инвестиционна бележка за техника над 5000 €: поръчки, наем срещу покупка, пълна цена за три години, капацитет, резерви и критерий за отказ."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-13","title":"Карта не е архив: копирай и провери преди изтриване","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще защитиш суровия материал с подредено копиране и ясно правило кога носителят може да се освободи.","hook":"Папката на лаптопа има само част от клиповете, но картата вече е форматирана за следващия снимачен ден.","estimated_minutes":37,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще защитиш суровия материал с подредено копиране и ясно правило кога носителят може да се освободи."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Папката на лаптопа има само част от клиповете, но картата вече е форматирана за следващия снимачен ден."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Карта в камерата е работен носител, не архив. Копирай цялата структура, провери броя файлове или използвай checksum при ingest, после направи независимо копие на друг носител. Правилото 3-2-1 е отправна точка, но копията трябва да се проверяват и възстановяват.\n\nНе форматирай оригинала, докато копието не е проверено и отворено. Облачният sync може да прехвърля изтривания, затова провери версионирането и сроковете. Достъпът, шифроването и периодът на съхранение също са част от клиентската безопасност."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Остави оригиналните имена или веди таблица, която свързва имена и нови названия; не преименувай карта по файл. При checksum сравни отчет на източник и копие. Ако такъв инструмент липсва, провери количество, размери и клипове от началото, средата и края. Измери и колко време отнема целият трансфер."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Маркирай картата като оригинал и спри запис след снимането.\n2. Копирай цялата структура в папката по стандарта на проекта.\n3. Пусни checksum или сравни отчета за брой и размер на файловете.\n4. Отвори избрани клипове от копието и провери звук, картина и дължина.\n5. Направи второ копие на отделен физически носител и отбележи мястото.\n6. Форматирай само след потвърждение и според срока за съхранение."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Сватбен оператор снима цял ден на две карти. В края папките се копират на SSD, checksum отчетът съвпада и клипове от церемонията и вечерта се отварят. Второто копие се пази отделно; картите остават заключени до повторна проверка.\n\nКритерий за добър ход: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира."},"after":{"label":"Как го поправяш","text":"Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Подготви папка с 20 смесени файла. Копирай я на два носителя, направи checksum или сравнение на размери, отвори произволни файлове и запиши кое копие е отделено от работния компютър.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Копирай цялата структура в папката по стандарта на проекта. Отвори избрани клипове от копието и провери звук, картина и дължина.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане.\n\nТестът е минал едва когато: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Сватбен оператор снима цял ден на две карти. В края папките се копират на SSD, checksum отчетът съвпада и клипове от церемонията и вечерта се отварят. Второто копие се пази отделно; картите остават заключени до повторна проверка.\n\nДоставката ти е: Подготви папка с 20 смесени файла. Копирай я на два носителя, направи checksum или сравнение на размери, отвори произволни файлове и запиши кое копие е отделено от работния компютър.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"CISA препоръчва offline копия и редовна проверка за възстановяване: https://www.cisa.gov/stopransomware/ransomware-guide"},"points":0,"required":false},{"position":12,"block_key":"field_note_1","block_type":"rich_text","title":"Проба за възстановяване","content":{"body":"Възстанови един клип в празна тестова папка, отвори го и запиши колко време отнема и кой може да повтори процеса."},"points":1,"required":false},{"position":13,"block_key":"quiz_1","block_type":"quiz","title":"Кога да форматираш","content":{"question":"Кое трябва да е вярно преди изтриване на оригиналната карта?","options":[{"id":"a","label":"На лаптопа се вижда папка със същото име."},{"id":"b","label":"Копието е проверено, клипове се отварят и има независим резерв според правилата на проекта."},{"id":"c","label":"Копирането приключи без съобщение."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Успешният прозорец за копиране не доказва, че материалът се възстановява.\n\nВариантът „На лаптопа се вижда папка със същото име.“ не доказва: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Вариантът „Копирането приключи без съобщение.“ оставя нерешено: Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира. Безопасната корекция е: Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_1","block_type":"scenario","title":"Не съвпада броят","content":{"prompt":"Копието има по-малко клипове от картата. Какво правиш?","options":[{"id":"a","label":"Копираш само избраните миниатюри."},{"id":"b","label":"Спираш форматирането, проверяваш отчета и липсващите пътища, после повтаряш копието."},{"id":"c","label":"Форматираш — вероятно са дубликати."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Несъответствието е стоп-сигнал; запази оригинала, докато го обясниш.\n\nВариантът „Форматираш — вероятно са дубликати.“ не доказва: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Вариантът „Копираш само избраните миниатюри.“ оставя нерешено: Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира. Безопасната корекция е: Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"quiz_2","block_type":"quiz","title":"Разбери 3-2-1","content":{"question":"Какво описва 3-2-1?","options":[{"id":"a","label":"Три копия, на два типа носител, с едно извън основното място."},{"id":"b","label":"Три версии на монтажа без сурови клипове."},{"id":"c","label":"Три папки на една карта и две копия на същия SSD."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Различните носители и физическото разделяне намаляват общия риск.\n\nВариантът „Три папки на една карта и две копия на същия SSD.“ не доказва: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Вариантът „Три версии на монтажа без сурови клипове.“ оставя нерешено: Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира. Безопасната корекция е: Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"scenario_2","block_type":"scenario","title":"Sync не е архив","content":{"prompt":"Облачният sync предава и изтривания. Какво добавяш?","options":[{"id":"a","label":"Наричаш sync папката архив."},{"id":"b","label":"Изключваш локалното копие, защото облакът е извън офиса."},{"id":"c","label":"Отделно версионирано или offline копие и периодичен тест за възстановяване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Синхронизацията не винаги пази предишно състояние; провери retention и restore.\n\nВариантът „Наричаш sync папката архив.“ не доказва: Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение. Вариантът „Изключваш локалното копие, защото облакът е извън офиса.“ оставя нерешено: Drag-and-drop приключва, на лаптопа се вижда папка и картата се форматира. Безопасната корекция е: Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":17,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Копирай цялата структура в папката по стандарта на проекта."},{"id":"s3","text":"Пусни checksum или сравни отчета за брой и размер на файловете."},{"id":"s4","text":"Отвори избрани клипове от копието и провери звук, картина и дължина."},{"id":"s1","text":"Маркирай картата като оригинал и спри запис след снимането."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Маркирай картата като оригинал и спри запис след снимането.\n2. Копирай цялата структура в папката по стандарта на проекта.\n3. Пусни checksum или сравни отчета за брой и размер на файловете.\n4. Отвори избрани клипове от копието и провери звук, картина и дължина."},"scoring":{"mode":"exact_order"}},{"position":18,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще защитиш суровия материал с подредено копиране и ясно правило кога носителят може да се освободи.","Провери файловете на целевия носител, направи отделно копие и освободи картата само след приемане.","Има две копия на различни физически носители, проверка, отчет за място и известен срок и отговорник за съхранение."],"nextStep":"Подготви папка с 20 смесени файла. Копирай я на два носителя, направи checksum или сравнение на размери, отвори произволни файлове и запиши кое копие е отделено от работния компютър."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-14","title":"Избери опора според кадъра: статив, монопод или гимбъл","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще избереш опора според дължината на записа, движението, пространството и нуждата от повторяем кадър.","hook":"Тежък гимбъл се настройва за десетсекунден неподвижен кадър, а стативът стои в багажника за интервю от час.","estimated_minutes":33,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш опора според дължината на записа, движението, пространството и нуждата от повторяем кадър."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Тежък гимбъл се настройва за десетсекунден неподвижен кадър, а стативът стои в багажника за интервю от час."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Стативът дава повторяем кадър и освобождава ръцете; моноподът помага при дълго снимане и честа смяна на позиция; гимбълът е за контролирано движение; ръката е бърза и естествена, но иска стабилна стойка и кратък дубъл. Няма универсален победител.\n\nПровери товар, височина, повърхност, захват и ориентация. На открито защити статива от вятър; в тълпа не оставяй крака в пътя на хората. За неподвижен обект първо пробвай опора, която изисква най-малко настройка.\n\nПолеви наръчник: Използвай статив за заключен кадър, повторяемо интервю или демонстрация, когато стабилността е по-важна от пренасянето. Моноподът носи тежестта и позволява бързо преместване, но изисква оператор и внимание към основата. Гимбълът помага при движение по маршрут и проследяване, но иска балансиране, зареждане и място за безопасна траектория. Преди решение мини маршрута без запис: врати, стълби, тълпа, отражения и мястото за спиране. Запиши по един пример с всеки наличен вариант и гледай началото и спирането — клатенето при края често личи най-много. Ако няма повторяемо движение, не включвай гимбъл само защото го имаш; бавен пан е по-добър от плаващ кадър.\n\nРаботна проверка: Запиши решението в малка карта: тип кадър, движение, продължителност, повърхност, тежест, шум от мотор, захранване и място за оператора. Изпробвай старт, движение и спиране с точната камера и аксесоар; балансът се променя при смяна на телефон, калъф или микрофон. Провери дали оборудването не влиза в кадър и не създава риск за участници. Екипът трябва да може да обясни избора си без фразата „така е по-кинематографично“.\n\nДопълнителен ход от практиката: При снимане на хора провери нуждата от съгласие, прохода за публика и кой държи безопасния край на стойката. За пан следи начална и крайна композиция, скорост на мотора и достатъчен запас за монтаж. За locked shot провери дали подът или масата не вибрира. Сними тест от монтажната височина, не от позицията, в която си проверил оборудването. Съхрани едно референтно движение и настройка, за да не започва следващата смяна от нулата.\n\nПрактически разбор: За интервю провери кадъра след няколко минути и дали стативът провисва. За монопод тествай опора към тялото и колко дълго задържаш кадъра. За гимбъл провери баланс, мотор и свободен маршрут. Времето за смяна на опора влиза в офертата и графика."},"points":2,"required":true},{"position":3,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи дали кадърът стои, следва човек или променя гледната точка.\n2. Оцени продължителността и колко често се сменя позицията.\n3. Провери стабилност, товар, ориентация и безопасно пространство.\n4. Репетирай монтаж и демонтаж с телефона и кейса.\n5. Запиши кратък тест и го изгледай преди цялата сцена.\n6. Използвай най-простата опора, която покрива задачата."},"points":2,"required":true},{"position":4,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"В болничен коридор има кратко интервю и ходене на специалист. Интервюто е на статив; после се заснема къс ръчен проход. Гимбълът остава за по-широк маршрут, където има пространство и реална нужда от движение.\n\nХод, който се проваля: Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката.\n\nКорекция: Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата.\n\nКритерий за добър ход: Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление."},"points":2,"required":true},{"position":5,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Избери фиксиран продукт, интервю от 30 секунди и движение през врата. За всеки посочи опора, време за настройка, риск за околните и критерий за приемане.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":6,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":7,"block_key":"quiz_1","block_type":"quiz","title":"Най-простата опора","content":{"question":"Какво е добро начало за дълго интервю без движение?","options":[{"id":"a","label":"Телефонът върху коляното."},{"id":"b","label":"Статив, който дава повторяем кадър и не пречи на звука и погледа."},{"id":"c","label":"Гимбъл, защото моторът спира всяко движение."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Опората трябва да отговаря на задачата, не да внася сложност.\n\nВариантът „Гимбъл, защото моторът спира всяко движение.“ не доказва: Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление. Вариантът „Телефонът върху коляното.“ оставя нерешено: Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката. Безопасната корекция е: Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":8,"block_key":"scenario_1","block_type":"scenario","title":"Пътят е зает","content":{"prompt":"Краката на статива заемат път в оживена зала. Какво правиш?","options":[{"id":"a","label":"Преместваш снимането или избираш по-безопасна опора и освобождаваш прохода."},{"id":"b","label":"Намаляваш височината без проверка на стабилността."},{"id":"c","label":"Оставяш статива и молиш гостите да го заобикалят."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Безопасността на хората е част от избора на кадър и опора.\n\nВариантът „Оставяш статива и молиш гостите да го заобикалят.“ не доказва: Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление. Вариантът „Намаляваш височината без проверка на стабилността.“ оставя нерешено: Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката. Безопасната корекция е: Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"quiz_2","block_type":"quiz","title":"Разграничи монопода","content":{"question":"Къде моноподът може да е практичен?","options":[{"id":"a","label":"Когато камерата трябва да стои сама без оператор."},{"id":"b","label":"Когато е нужно механично плавно движение по маршрут."},{"id":"c","label":"При дълго снимане с честа смяна на позиция, когато стативът пречи."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Моноподът помага за опора и бърза смяна, но не замества статив или гимбъл.\n\nВариантът „Когато камерата трябва да стои сама без оператор.“ не доказва: Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление. Вариантът „Когато е нужно механично плавно движение по маршрут.“ оставя нерешено: Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката. Безопасната корекция е: Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_2","block_type":"scenario","title":"Несигурна стойка","content":{"prompt":"Стойката едва удържа телефона и се накланя при докосване. Как постъпваш?","options":[{"id":"a","label":"Добавяш тежест отгоре без проверка на основата."},{"id":"b","label":"Снимаш, стига да не докосваш телефона."},{"id":"c","label":"Не я използваш; проверяваш товароносимостта и вземаш съвместима опора."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Нестабилната опора рискува техника, кадър и хора; не компенсирай неизвестен товар.\n\nВариантът „Снимаш, стига да не докосваш телефона.“ не доказва: Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление. Вариантът „Добавяш тежест отгоре без проверка на основата.“ оставя нерешено: Една опора се използва за всички сцени, без оглед на дължината, движението и безопасността на публиката. Безопасната корекция е: Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Оцени продължителността и колко често се сменя позицията."},{"id":"s1","text":"Определи дали кадърът стои, следва човек или променя гледната точка."},{"id":"s4","text":"Репетирай монтаж и демонтаж с телефона и кейса."},{"id":"s3","text":"Провери стабилност, товар, ориентация и безопасно пространство."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи дали кадърът стои, следва човек или променя гледната точка.\n2. Оцени продължителността и колко често се сменя позицията.\n3. Провери стабилност, товар, ориентация и безопасно пространство.\n4. Репетирай монтаж и демонтаж с телефона и кейса."},"scoring":{"mode":"exact_order"}},{"position":12,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще избереш опора според дължината на записа, движението, пространството и нуждата от повторяем кадър.","Направи матрица кадър–опора. Тествай една сцена с два подхода и избери този, който намалява риска и работата.","Обясняваш защо опората пасва и монтираш телефона безопасно, без да закриваш камера или управление."],"nextStep":"Избери фиксиран продукт, интервю от 30 секунди и движение през врата. За всеки посочи опора, време за настройка, риск за околните и критерий за приемане."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-15","title":"Телепромптер без скрито четене: текст, поглед и темпо","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще превърнеш написан текст в естествено изпълнение, което говорещият произнася ясно.","hook":"Водещият гледа право в обектива, но гласът е равен и очите препускат през думи, които не би казал в разговор.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще превърнеш написан текст в естествено изпълнение, което говорещият произнася ясно."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Водещият гледа право в обектива, но гласът е равен и очите препускат през думи, които не би казал в разговор."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Телепромптерът помага за последователен текст, не замества изпълнението. Редактирай за говор: една идея на изречение, ясни паузи, произносими имена и продължителност, която пасва на кадъра. Постави текста близо до обектива, после провери движението на очите.\n\nСкоростта се наглася към човека, не обратното. Прочети на глас без камера, отбележи писмените фрази и замени ги с естествени. Ако говорещият се спъва, скъси изречението. Заснеми няколко реда и гледай без звук: лицето пак ли изглежда естествено?\n\nПолеви наръчник: Подготви текста за говорене, не за четене: една мисъл на ред, кратки изречения и маркирани паузи. Разположи екрана близо до обектива; ако погледът прескача, намали скоростта и размера на текста. Изпробвай scroll с реалния говорител и неговото темпо, не само с таймер. Направи проба без запис и после със запис; провери дали очите следят думите или задържат контакт. Остави място за вдишване и повторение на трудна реплика. При прекъсване отбележи откъде продължавате. Не прикривай телепромптера изцяло с монтаж: неподвижните очи личат, а бързият текст кара говорителя да изпуска окончанията.\n\nРаботна проверка: Отбележи имена, числа и думи, които често се произнасят грешно; съгласувай правилното произношение с говорителя преди снимка. При грешка повтори цялата мисъл с пауза, за да остане монтажен handle. Провери и дали текстът на екрана не съдържа поверителни данни, които не трябва да се появят в кадъра. Ако говорителят не може да поддържа темпото, изключи scroll и снимай по изречения; естественият говор е по-ценен от безупречното четене.\n\nДопълнителен ход от практиката: Репетирай първо без телепромптер: така ще чуеш дали текстът звучи като говорим език. Съкрати редовете, където човекът губи въздух, и постави маркер при думи за акцент; не добавяй на екрана инструктаж, който говорителят не е одобрил. Ако текстът се редактира по време на снимки, запиши версията и смени контролната дума в началото на дубъла. При грешна цифра или обещание спри и потвърди факта с отговорния човек, преди да направиш нов дубъл."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Подреди абзаците като смислови части и маркирай паузи, усмивка или показване на предмет. Шрифтът трябва да е четим от работното разстояние; редовете да не изискват широко движение на очите. Репетирай темпо с обикновен таймер, а не с дълго четене на екран. Остави водещия да повтори трудните думи преди дубъл."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Прочети текста на глас и измери реалната продължителност.\n2. Замени писмени фрази, дълги изречения и неизговорими съкращения.\n3. Раздели текста на дишаеми части и отбележи паузи и действия.\n4. Постави текста близо до обектива и нагласи четим шрифт и скорост.\n5. Запиши кратка проба и изгледай очите, темпото и естествените паузи.\n6. Снимай по смислови части и отбелязвай използваемите дубъли."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Собственик на клиника трябва да обясни нова услуга за 45 секунди. Писменият бриф е два пъти по-дълъг. Монтажистът запазва фактите, маха повторенията, разделя обяснението на три мисли и задава телепромптера на темпо, при което говорещият може да вдигне поглед.\n\nКритерий за добър ход: Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи."},"after":{"label":"Как го поправяш","text":"Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Вземи 120 думи от бриф, прочети ги, скъси до нужната дължина и отбележи паузи. Заснеми тест с и без телепромптер; сравни поглед и естественост.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Направи текста говорим","content":{"question":"Водещият постоянно се спъва в дълги изречения. Какво променяш първо?","options":[{"id":"a","label":"Съкращаваш и разделяш фразите, като запазваш потвърдените факти."},{"id":"b","label":"Намаляваш размера на текста."},{"id":"c","label":"Ускоряваш скрола, за да завърши по-бързо."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Текстът трябва да се произнася естествено; скоростта не поправя писмен стил.\n\nВариантът „Ускоряваш скрола, за да завърши по-бързо.“ не доказва: Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина. Вариантът „Намаляваш размера на текста.“ оставя нерешено: Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи. Безопасната корекция е: Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Фактът не се побира","content":{"prompt":"Клиентският бриф е 90 секунди, но договорът иска 45. Какво правиш?","options":[{"id":"a","label":"Ускоряваш водещия до неестествено темпо."},{"id":"b","label":"Премахваш важно условие без клиентско потвърждение."},{"id":"c","label":"Съкращаваш повторенията, пазиш задължителните факти и потвърждаваш съкратения вариант."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Олекоти текста, не променяй смисъла или условията по предположение.\n\nВариантът „Ускоряваш водещия до неестествено темпо.“ не доказва: Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина. Вариантът „Премахваш важно условие без клиентско потвърждение.“ оставя нерешено: Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи. Безопасната корекция е: Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Постави текста разумно","content":{"question":"Кое разположение намалява видимото четене?","options":[{"id":"a","label":"Текстът превърта по-бързо от говорещия."},{"id":"b","label":"Екранът стои далеч встрани, но шрифтът е много голям."},{"id":"c","label":"Текстът е близо до обектива, а редовете и шрифтът са четими от позицията на водещия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Разстоянието и хоризонталното движение на очите се проверяват в реален кадър.\n\nВариантът „Екранът стои далеч встрани, но шрифтът е много голям.“ не доказва: Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина. Вариантът „Текстът превърта по-бързо от говорещия.“ оставя нерешено: Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи. Безопасната корекция е: Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Грешка в репликата","content":{"prompt":"Водещият греши една дума в изречение с важни условия. Как продължаваш?","options":[{"id":"a","label":"Спираш, сверяваш одобрения текст и снимаш цялата мисъл наново с чисто начало и край."},{"id":"b","label":"Поправяш думата с надпис, който променя изговореното."},{"id":"c","label":"Оставяш дубъла, защото смисълът ти е ясен."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Не маскирай промяна на факт; осигури точен дубъл или потвърди редакцията.\n\nВариантът „Поправяш думата с надпис, който променя изговореното.“ не доказва: Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина. Вариантът „Оставяш дубъла, защото смисълът ти е ясен.“ оставя нерешено: Скролът е ускорен, за да побере целия дълъг текст; операторът чака водещият да се справи. Безопасната корекция е: Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Постави текста близо до обектива и нагласи четим шрифт и скорост."},{"id":"s1","text":"Прочети текста на глас и измери реалната продължителност."},{"id":"s2","text":"Замени писмени фрази, дълги изречения и неизговорими съкращения."},{"id":"s3","text":"Раздели текста на дишаеми части и отбележи паузи и действия."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Прочети текста на глас и измери реалната продължителност.\n2. Замени писмени фрази, дълги изречения и неизговорими съкращения.\n3. Раздели текста на дишаеми части и отбележи паузи и действия.\n4. Постави текста близо до обектива и нагласи четим шрифт и скорост."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще превърнеш написан текст в естествено изпълнение, което говорещият произнася ясно.","Редактирай текста за реч, запази задължителните факти и заснемай на кратки смислови части.","Водещият произнася ключовото твърдение точно, погледът е близо до обектива и времето пасва на договорената дължина."],"nextStep":"Вземи 120 думи от бриф, прочети ги, скъси до нужната дължина и отбележи паузи. Заснеми тест с и без телепромптер; сравни поглед и естественост."},"points":1,"required":true}]},{"module_id":"s02-m07","lesson_id":"pv07-16","title":"Преди да тръгнеш: приемане на снимачния ден","subtitle":"Модул 07 · Мобилна продукция за платена задача","objective":"Ще затвориш снимачна поръчка с покрит материал, проверен звук, копия, имена и ясно предаване към монтаж.","hook":"Всички прибират техника, но никой не знае кой файл е добрият, какво остава за pickup и дали клиентът има право да използва музиката.","estimated_minutes":50,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще затвориш снимачна поръчка с покрит материал, проверен звук, копия, имена и ясно предаване към монтаж."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Всички прибират техника, но никой не знае кой файл е добрият, какво остава за pickup и дали клиентът има право да използва музиката."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Снимачният ден не е приключил, когато камерата е прибрана. Той приключва, когато всеки кадър от брифа има статус, ключовият материал е одитиран, копието е потвърдено и следващият човек знае какво да прави. Запиши имена и номера на добрите дубъли; отбележи проблем, липса на съгласие или неизпълнено условие.\n\nНе обещавай, че целият материал е добър, ако не си проверил. Подреди копието и предай кратка бележка: цел, формат, имена, отворени въпроси, права и срок. При чувствителен запис уточни кой има достъп и кога ще бъде изтрит."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Преди разглобяване провери кадри, звук и технические дубли, после съгласие и права за хора, музика, локация и марки. Прехвърли картите, сравни имената и отвори тестови клипове. Определи дали има pickup и кой го одобрява. Не форматирай карта, докато копието и отговорникът не са потвърдени."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Свери всеки ред от брифа с клип и статус: готов, повторение, липсва.\n2. Прослушай избраните реплики и провери ключовия кадър на голям екран.\n3. Отбележи номера на добрите дубли, резервите и кадрите за pickup.\n4. Провери права, съгласие и материал, който изисква ограничен достъп.\n5. Копирай, сверѝ броя файлове и отвори клипове от целевото място.\n6. Изпрати монтажисту структура, бриф, срок, версия и оставащи решения."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Клиентът иска интервю и три кадъра на продукта. Интервюто е заснето, но едно продуктово действие липсва. Вместо да изпратиш общ статус „готово“, отбелязваш липсата, предлагаш кратък pickup и предаваш монтажната част със списък на проверените дубли.\n\nКритерий за добър ход: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено."},"after":{"label":"Как го поправяш","text":"Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи приемателна бележка за един учебен снимачен ден: бриф, заснети кадри, избрани дубли, технически проблеми, права, копие, нужни pickup-и, получател и срок.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Прослушай избраните реплики и провери ключовия кадър на голям екран. Провери права, съгласие и материал, който изисква ограничен достъп.\n\nПовтори един и същ тест със същото място и комплект. Промени само една настройка или една част от екипировката; запиши точния модел/версия и резултата. Провери оригиналния файл, не само прегледа в телефона. Така ще различиш проблем в камерата, аксесоара, навика на оператора и самата сцена.\n\nКоригирай с този ход: Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник.\n\nТестът е минал едва когато: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Клиентът иска интервю и три кадъра на продукта. Интервюто е заснето, но едно продуктово действие липсва. Вместо да изпратиш общ статус „готово“, отбелязваш липсата, предлагаш кратък pickup и предаваш монтажната част със списък на проверените дубли.\n\nДоставката ти е: Направи приемателна бележка за един учебен снимачен ден: бриф, заснети кадри, избрани дубли, технически проблеми, права, копие, нужни pickup-и, получател и срок.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи модела и режима на устройството, микрофона/опората, тестовия кадър или звук и резервния ход. Друг оператор трябва да разбере какво може да се повтори и при кои условия.\n\nПриемане: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"За безопасно предаване на медията използвай и правилото за проверени offline копия на CISA: https://www.cisa.gov/stopransomware/ransomware-guide"},"points":0,"required":false},{"position":12,"block_key":"field_note_1","block_type":"rich_text","title":"Чеклист за екипа","content":{"body":"Преди да напусне локацията, всеки член потвърждава една зона: камера и звук, права и съгласия, копиране и предаване."},"points":1,"required":false},{"position":13,"block_key":"quiz_1","block_type":"quiz","title":"Какво значи приключен ден","content":{"question":"Кога снимачният ден е готов за монтаж?","options":[{"id":"a","label":"Когато камерата е прибрана."},{"id":"b","label":"Когато всички са съгласни, че снимаха достатъчно."},{"id":"c","label":"Когато брифът е сверен с кадри, ключовият материал е проверен и копието/бележката са предадени."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Приключването се доказва с материал и предаване, не с усещане.\n\nВариантът „Когато камерата е прибрана.“ не доказва: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Вариантът „Когато всички са съгласни, че снимаха достатъчно.“ оставя нерешено: Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено. Безопасната корекция е: Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_1","block_type":"scenario","title":"Липсва кадър","content":{"prompt":"От брифа липсва близък план, а локацията все още е достъпна. Какво правиш?","options":[{"id":"a","label":"Изпращаш статуса „готово“."},{"id":"b","label":"Казваш на монтажиста да направи цифрово приближение от друг кадър."},{"id":"c","label":"Записваш липсата и снимаш pickup, докато реквизитът и мястото са готови."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Повтори кадър, ако това е по-надеждно от изкуствена поправка.\n\nВариантът „Казваш на монтажиста да направи цифрово приближение от друг кадър.“ не доказва: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Вариантът „Изпращаш статуса „готово“.“ оставя нерешено: Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено. Безопасната корекция е: Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"quiz_2","block_type":"quiz","title":"Монтажистът получава контекст","content":{"question":"Кое трябва да има в краткото предаване?","options":[{"id":"a","label":"Структура, номера на добрите дубли, бриф, ограничения/права, срок и отворени въпроси."},{"id":"b","label":"Само линк към папка."},{"id":"c","label":"Общото „най-добрите кадри са някъде вътре“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Бележката трябва да премахва търсенето и да предупреждава за решения.\n\nВариантът „Само линк към папка.“ не доказва: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Вариантът „Общото „най-добрите кадри са някъде вътре“.“ оставя нерешено: Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено. Безопасната корекция е: Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"scenario_2","block_type":"scenario","title":"Искат да изтрият картата","content":{"prompt":"Клиентът иска картата веднага за друга задача, но копието още не е проверено. Как реагираш?","options":[{"id":"a","label":"Форматираш, защото клиентът го е поискал."},{"id":"b","label":"Обясняваш риска и приключваш проверката или осигуряваш друг носител преди изтриване."},{"id":"c","label":"Копираш само избраните клипове, без да го отбележиш."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Ясно назови риска и направи прехвърлянето проверимо.\n\nВариантът „Форматираш, защото клиентът го е поискал.“ не доказва: Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието. Вариантът „Копираш само избраните клипове, без да го отбележиш.“ оставя нерешено: Екипът казва „материалът е готов“, макар един от кадрите да липсва, а копието да не е проверено. Безопасната корекция е: Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":17,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Провери права, съгласие и материал, който изисква ограничен достъп."},{"id":"s3","text":"Отбележи номера на добрите дубли, резервите и кадрите за pickup."},{"id":"s2","text":"Прослушай избраните реплики и провери ключовия кадър на голям екран."},{"id":"s1","text":"Свери всеки ред от брифа с клип и статус: готов, повторение, липсва."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Свери всеки ред от брифа с клип и статус: готов, повторение, липсва.\n2. Прослушай избраните реплики и провери ключовия кадър на голям екран.\n3. Отбележи номера на добрите дубли, резервите и кадрите за pickup.\n4. Провери права, съгласие и материал, който изисква ограничен достъп."},"scoring":{"mode":"exact_order"}},{"position":18,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще затвориш снимачна поръчка с покрит материал, проверен звук, копия, имена и ясно предаване към монтаж.","Раздели приключилата работа от отворените задачи. Подкрепи статуса с кадри, файлове и отговорник.","Друг монтажист може да намери най-добрите дубъли и да започне работа, без да пита кое е записано или къде е копието."],"nextStep":"Направи приемателна бележка за един учебен снимачен ден: бриф, заснети кадри, избрани дубли, технически проблеми, права, копие, нужни pickup-и, получател и срок."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-01","title":"Пакетно производство: планирай месец без обещания за чудеса","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще превърнеш месечна нужда от видеа в снимачен обхват, който екипът може да произведе и провери.","hook":"Планът обещава 15 клипа за ден, но пропуска подготовка, паузи, повторения, импорт и проверка.","estimated_minutes":44,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще превърнеш месечна нужда от видеа в снимачен обхват, който екипът може да произведе и провери."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Планът обещава 15 клипа за ден, но пропуска подготовка, паузи, повторения, импорт и проверка."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Пакетното снимане събира сходни настройки и намалява повторната подготовка; то не премахва писане, съгласие, редакция или одобрение. Брой клипове се определя от формата, трудността, броя участници, локациите и средния брой дубъли. Вечнозелено съдържание може да се снима предварително, но оферти, срокове, цени и актуални факти имат дата на валидност.\n\nПланирай работата назад от готовите доставки: колко видеа, кои версии, кой одобрява и кога. Остави резерв между сетовете. Ако редакторът и единствен оператор са един човек, предвиди и време за работа след снимките."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Вземи реалните данни от последните няколко проекта: подготовка на един клип, време за смяна на говорещ, повторения и процент кадри, които се връщат за поправка. Използвай медианата, не най-добрия ден. Планирай няколко различни структури, за да не звучат всички клипове еднакво; групирай по локация и осветление, но пази почивките."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи месечните доставки и отбележи кои факти или оферти изтичат.\n2. Групирай по локация, човек, светлина и комплект, не само по тема.\n3. Сметни setup, запис, средни повторения, почивка и техническа проверка.\n4. Резервирай време за монтаж, обратна връзка, корекция и резервен снимачен слот.\n5. Потвърди участници, одобрители, права и всички твърдения преди деня.\n6. Измери на следващия ден какво е заснето, годно и действително предадено."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Малък фитнес публикува три пъти седмично. Вместо да обещае 12 клипа за ден, екипът групира осем вечнозелени упражнения и оставя четири слота за сезонни теми. Реалните данни показват, че снимачният ден поема осем клипа с един треньор, включително паузи и повторения.\n\nКритерий за добър ход: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен."},"after":{"label":"Как го поправяш","text":"Измери целия работен цикъл и определи брой клипове по реални минути и сложност."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи план за осем клипа с поне две различни структури. За всеки отбележи валидност на фактите, локация, участник, време за запис, нужни дубли и кой ще одобри.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Групирай по локация, човек, светлина и комплект, не само по тема. Резервирай време за монтаж, обратна връзка, корекция и резервен снимачен слот.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Измери целия работен цикъл и определи брой клипове по реални минути и сложност.\n\nТестът е минал едва когато: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Малък фитнес публикува три пъти седмично. Вместо да обещае 12 клипа за ден, екипът групира осем вечнозелени упражнения и оставя четири слота за сезонни теми. Реалните данни показват, че снимачният ден поема осем клипа с един треньор, включително паузи и повторения.\n\nДоставката ти е: Направи план за осем клипа с поне две различни структури. За всеки отбележи валидност на фактите, локация, участник, време за запис, нужни дубли и кой ще одобри.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Планирай по реален капацитет","content":{"question":"Кое е надеждна основа за броя клипове в batch деня?","options":[{"id":"a","label":"Най-бързият ден, който екипът някога е имал."},{"id":"b","label":"Дължината на клиповете на публикация."},{"id":"c","label":"Реално време за подготовка, дубъли, смяна на сет, паузи и проверка от сходни проекти."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Капацитетът се измерва по целия цикъл, не само по говоренето пред камера.\n\nВариантът „Дължината на клиповете на публикация.“ не доказва: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Вариантът „Най-бързият ден, който екипът някога е имал.“ оставя нерешено: Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен. Безопасната корекция е: Измери целия работен цикъл и определи брой клипове по реални минути и сложност. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Актуална оферта","content":{"prompt":"Един от клиповете съдържа цена, която може да се промени след седмица. Как го планираш?","options":[{"id":"a","label":"Отбелязваш валидността и заснемаш близо до одобрението/публикацията или планираш повторен дубъл."},{"id":"b","label":"Слагаш го в библиотеката за месеци без дата."},{"id":"c","label":"Премахваш датата, за да не личи промяната."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Партидното производство не превръща твърдение с ограничен срок във вечнозелено.\n\nВариантът „Слагаш го в библиотеката за месеци без дата.“ не доказва: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Вариантът „Премахваш датата, за да не личи промяната.“ оставя нерешено: Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен. Безопасната корекция е: Измери целия работен цикъл и определи брой клипове по реални минути и сложност. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Един снимачен ден ≠ месец монтаж","content":{"question":"Какво остава извън сметката, ако планираш само времето пред камера?","options":[{"id":"a","label":"Нищо, защото видеата вече са записани."},{"id":"b","label":"Подготовка, одобрение, ingest, монтаж, QC, корекции и предаване."},{"id":"c","label":"Само качването на клиповете в социална мрежа."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Доставката е целият процес от бриф до приет файл.\n\nВариантът „Нищо, защото видеата вече са записани.“ не доказва: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Вариантът „Само качването на клиповете в социална мрежа.“ оставя нерешено: Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен. Безопасната корекция е: Измери целия работен цикъл и определи брой клипове по реални минути и сложност. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Графикът закъснява","content":{"prompt":"След третия сет вече сте с час назад. Кой ход е професионален?","options":[{"id":"a","label":"Продължаваш без да предупредиш клиента."},{"id":"b","label":"Преоценяваш обхвата, пазиш критичните клипове и съгласуваш преместване на останалите."},{"id":"c","label":"Изтриваш паузата и QC, за да снимаш всичко."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Промени графика прозрачно; не прикривай риск за качество и безопасност.\n\nВариантът „Изтриваш паузата и QC, за да снимаш всичко.“ не доказва: Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването. Вариантът „Продължаваш без да предупредиш клиента.“ оставя нерешено: Планът брои само минутите пред камерата и третира всеки клип като еднакво сложен. Безопасната корекция е: Измери целия работен цикъл и определи брой клипове по реални минути и сложност. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Групирай по локация, човек, светлина и комплект, не само по тема."},{"id":"s3","text":"Сметни setup, запис, средни повторения, почивка и техническа проверка."},{"id":"s4","text":"Резервирай време за монтаж, обратна връзка, корекция и резервен снимачен слот."},{"id":"s1","text":"Определи месечните доставки и отбележи кои факти или оферти изтичат."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи месечните доставки и отбележи кои факти или оферти изтичат.\n2. Групирай по локация, човек, светлина и комплект, не само по тема.\n3. Сметни setup, запис, средни повторения, почивка и техническа проверка.\n4. Резервирай време за монтаж, обратна връзка, корекция и резервен снимачен слот."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще превърнеш месечна нужда от видеа в снимачен обхват, който екипът може да произведе и провери.","Измери целия работен цикъл и определи брой клипове по реални минути и сложност.","Графикът съдържа setup, почивки, тестове, буфер и отделен монтаж; временните твърдения имат дата или слот близо до публикуването."],"nextStep":"Направи план за осем клипа с поне две различни структури. За всеки отбележи валидност на фактите, локация, участник, време за запис, нужни дубли и кой ще одобри."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-02","title":"Осем сценария предварително: разнообразие с одобрени факти","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще подготвиш сценарии с различни гледни точки, доказани твърдения и ясна следваща стъпка.","hook":"Осмият клип повтаря първия с различен фон; екипът е снимал обем, но не и разнообразно съдържание.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подготвиш сценарии с различни гледни точки, доказани твърдения и ясна следваща стъпка."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Осмият клип повтаря първия с различен фон; екипът е снимал обем, но не и разнообразно съдържание."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Сценарият преди снимачния ден намалява чакането и помага да се запише точният кадър. Започни от нуждата на зрителя, избери едно проверимо твърдение и добави доказателство или демонстрация. Редувай формати: отговор на въпрос, процес, преди/след, грешка, кратък разбор, покана. Не превръщай всички теми в еднакви hook–три точки–CTA.\n\nЗа всеки сценарий пази източника на фактите, одобрителя и срока им. Забранени твърдения не се „омекотяват“ до маркетингово обещание; ако доказателство липсва, сценарият се връща за уточнение. Запиши и какво зрителят трябва да види, за да не остане клипът само говореща глава."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Карточката за всеки видео-сценарий съдържа: аудитория, една цел, доказан факт, сцена/показване, задължителна формулировка, риск от двусмислие и CTA. Маркирай реплики, които изискват отговор от клиент. Остави едно поле за дата или промяна, ако условието не е постоянно."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Събери осем въпроса, възражения или действия от реални клиенти.\n2. Подреди ги по нужда и избери осем различни формата.\n3. За всяко твърдение добави източник, дата и одобрител.\n4. Пиши за говор, после прочети на глас и махни повторенията.\n5. Свържи репликата с кадър, предмет, действие или екранна демонстрация.\n6. Постави сценарии с актуални условия в слот близо до публикуването."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Онлайн магазин за велосипеди има осем клипа: настройка на седалка, проверка на гуми, избор на размер, демонстрация на спирачка и четири често задавани въпроса. Един клип споменава гаранция; текстът се одобрява от отговорника и носи дата на валидност.\n\nКритерий за добър ход: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория."},"after":{"label":"Как го поправяш","text":"Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши четири различни сценария за една услуга: отговор, демонстрация, честа грешка и клиентски процес. Отдели фактите от мнението и отбележи кой ги одобрява.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Подреди ги по нужда и избери осем различни формата. Пиши за говор, после прочети на глас и махни повторенията.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий.\n\nТестът е минал едва когато: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Онлайн магазин за велосипеди има осем клипа: настройка на седалка, проверка на гуми, избор на размер, демонстрация на спирачка и четири често задавани въпроса. Един клип споменава гаранция; текстът се одобрява от отговорника и носи дата на валидност.\n\nДоставката ти е: Напиши четири различни сценария за една услуга: отговор, демонстрация, честа грешка и клиентски процес. Отдели фактите от мнението и отбележи кой ги одобрява.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Факт преди формулировка","content":{"question":"Нямаш източник за обещан резултат. Какво правиш?","options":[{"id":"a","label":"Спираш твърдението и го връщаш за проверка или го заменяш с потвърден факт."},{"id":"b","label":"Добавяш „обикновено“ и го публикуваш."},{"id":"c","label":"Питаш модела да намери убедителна формулировка."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"По-мек тон не създава доказателство.\n\nВариантът „Добавяш „обикновено“ и го публикуваш.“ не доказва: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Вариантът „Питаш модела да намери убедителна формулировка.“ оставя нерешено: Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория. Безопасната корекция е: Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Един и същи hook","content":{"prompt":"Осем сценария звучат като копия. Кое подобрение има най-голям смисъл?","options":[{"id":"a","label":"Сменяш само цветовете на надписите."},{"id":"b","label":"Свързваш темите с различни въпроси и сцени от реални клиенти."},{"id":"c","label":"Добавяш по един силен прилагателен израз към всеки."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Разнообразието идва от въпрос, доказателство и формат, не от синоними.\n\nВариантът „Сменяш само цветовете на надписите.“ не доказва: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Вариантът „Добавяш по един силен прилагателен израз към всеки.“ оставя нерешено: Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория. Безопасната корекция е: Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Карта за снимачния ден","content":{"question":"Кое поле помага да се заснеме сценарият, не само да се прочете?","options":[{"id":"a","label":"Цветът на фона, без връзка с темата."},{"id":"b","label":"Какво действие, предмет или екран зрителят трябва да види."},{"id":"c","label":"Само дължината на текста."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Кадърът трябва да показва причината зрителят да повярва.\n\nВариантът „Само дължината на текста.“ не доказва: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Вариантът „Цветът на фона, без връзка с темата.“ оставя нерешено: Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория. Безопасната корекция е: Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Променлива гаранция","content":{"prompt":"Условие по гаранцията може да се промени. Как подготвяш клипа?","options":[{"id":"a","label":"Проверяваш официалния текст, посочваш одобрител и дата, после планираш актуален слот."},{"id":"b","label":"Използваш текста от миналогодишната кампания."},{"id":"c","label":"Снимаш общо обещание, без срок и одобрение."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Условията и датата са част от достоверността на клипа.\n\nВариантът „Снимаш общо обещание, без срок и одобрение.“ не доказва: Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее. Вариантът „Използваш текста от миналогодишната кампания.“ оставя нерешено: Сценаристът копира едно и също заглавие и призив във всичките осем текста, без да провери факти или аудитория. Безопасната корекция е: Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Подреди ги по нужда и избери осем различни формата."},{"id":"s1","text":"Събери осем въпроса, възражения или действия от реални клиенти."},{"id":"s4","text":"Пиши за говор, после прочети на глас и махни повторенията."},{"id":"s3","text":"За всяко твърдение добави източник, дата и одобрител."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Събери осем въпроса, възражения или действия от реални клиенти.\n2. Подреди ги по нужда и избери осем различни формата.\n3. За всяко твърдение добави източник, дата и одобрител.\n4. Пиши за говор, после прочети на глас и махни повторенията."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще подготвиш сценарии с различни гледни точки, доказани твърдения и ясна следваща стъпка.","Промени ъгъла според реалния въпрос и остави доказателство, собственик и CTA за всеки сценарий.","Всяка карта има едно послание, доказуемо твърдение, кадър, CTA, одобрител и дата, когато твърдението може да остарее."],"nextStep":"Напиши четири различни сценария за една услуга: отговор, демонстрация, честа грешка и клиентски процес. Отдели фактите от мнението и отбележи кой ги одобрява."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-03","title":"Непрекъснатост между дни: светлина, цвят, дрехи и позиция","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще направиш различни записи да изглеждат като една серия, като документираш това, което реално може да се повтори.","hook":"Двата кадъра на едно интервю са от различни дни: цветът на кожата, прозорецът и позицията на предметите се разминават.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш различни записи да изглеждат като една серия, като документираш това, което реално може да се повтори."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Двата кадъра на едно интервю са от различни дни: цветът на кожата, прозорецът и позицията на предметите се разминават."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Непрекъснатостта не означава да заключиш всеки кадър до един и същ preset. Тя означава да запазиш важните зрителски сигнали: ос, поглед, ниво на камерата, посока на светлина, баланс на бялото, дрехи и състояние на продукта. Запиши референтен кадър и бележка при първата смяна на сет.\n\nАко светлината или локацията са се променили, направи нов тест и не компенсирай на сляпо в монтажа. Сравнявай кожа, фон и обект при еднакъв монитор. Отбележи преднамерените разлики като част от историята — например преди/след — вместо случайна промяна.\n\nРаботна проверка: Създай референтен кадър при началото на всяка сесия и запиши осветлението, баланса на бялото, дистанцията и настройките. При смяна на стая не разчитай паметта на оператора или auto режима да повтори вида. Следи и дребните непрекъснатости: посока на погледа, ръка, позиция на продукта, нивото на течност и гънки по дреха. Ако разликата не може да се поправи безопасно в монтажа, заснеми matching insert, докато сетът още е изграден.\n\nДопълнителен ход от практиката: Използвай continuity снимка и бележка за камера, обектив, стойка, дистанция и относителна яркост; снимка без настройки не е достатъчна за повторение. Проверявай и осевата линия, посока на движение и положението на ръцете, за да не обърнеш действието между монтажни дни. Ако локацията е променила лампи или завеси, не фиксирай цвят само на една сцена: снимай сива карта/референция и провери кожата и продукта. Отбележи съзнателните промени, за да не ги „поправи“ монтажистът обратно."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Полезната continuity карта записва дата/час, позиция и височина на камерата, обектив/режим, баланс на бяло, светлинни източници, място на реквизита, дреха и действия. Снимай референтна снимка на сет без лични данни. При повторен ден възпроизведи само важните условия; не преследвай еднакъв вид, ако това вреди на новия кадър."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи кои елементи трябва да изглеждат свързани между кадрите.\n2. Маркирай позиция на камера, стол, продукт и източници на светлина.\n3. Запиши камера настройките и направи референтен кадър с кожа и неутрална повърхност.\n4. При следващ снимачен ден подреди сет по бележката и сравни тестов кадър.\n5. Провери ос, поглед, дреха, реквизит и ключовата светлина.\n6. Запиши и обясни неизбежната разлика; не я скривай с автоматичен preset."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Фризьорски салон снима три стъпки от една прическа в различни часове. Екипът маркира позицията на стола, височината на телефона, ръката на стилиста и светлината. Дневната светлина се промени; следващият тест пази посоката на лицето и използва еднаква ключова лампа.\n\nКритерий за добър ход: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят."},"after":{"label":"Как го поправяш","text":"Документирай и физическия сет, после направи тест кадър при повторното заснемане."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай continuity карта за серия от три клипа. Снимай референция, прибери реквизита и опитай да възстановиш кадъра на следващия ден.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Маркирай позиция на камера, стол, продукт и източници на светлина. При следващ снимачен ден подреди сет по бележката и сравни тестов кадър.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Документирай и физическия сет, после направи тест кадър при повторното заснемане.\n\nТестът е минал едва когато: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Какво запазва continuity картата","content":{"question":"Кое е нужно освен настройките на телефона?","options":[{"id":"a","label":"Само името на приложението."},{"id":"b","label":"Позиции на камера/човек/реквизит, светлина, дреха и референтен кадър."},{"id":"c","label":"Само филтърът за цвят."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Повторяемостта включва сцената и физическите позиции, не само менюто на камерата.\n\nВариантът „Само името на приложението.“ не доказва: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени. Вариантът „Само филтърът за цвят.“ оставя нерешено: Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят. Безопасната корекция е: Документирай и физическия сет, после направи тест кадър при повторното заснемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Светлината се е променила","content":{"prompt":"На следващия ден прозорецът е в пряко слънце. Какво правиш?","options":[{"id":"a","label":"Понижаваш експозицията, без да гледаш кожата."},{"id":"b","label":"Правиш нов тест и запазваш посоката на сцената чрез контролируема светлина или преместване."},{"id":"c","label":"Копираш вчерашните настройки и продължаваш."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Повтори намерението на светлината, не механично всяка стойност.\n\nВариантът „Копираш вчерашните настройки и продължаваш.“ не доказва: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени. Вариантът „Понижаваш експозицията, без да гледаш кожата.“ оставя нерешено: Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят. Безопасната корекция е: Документирай и физическия сет, после направи тест кадър при повторното заснемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Преднамерена разлика","content":{"question":"Кога разлика между кадрите е полезна?","options":[{"id":"a","label":"Когато е умишлена и помага на зрителя да разпознае промяна или действие."},{"id":"b","label":"Когато балансът на бялото се сменя без причина."},{"id":"c","label":"Когато е случайна и се прикрива с филтър."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Непрекъснатостта служи на историята; умишленото преди/след може да е ясно различно.\n\nВариантът „Когато е случайна и се прикрива с филтър.“ не доказва: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени. Вариантът „Когато балансът на бялото се сменя без причина.“ оставя нерешено: Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят. Безопасната корекция е: Документирай и физическия сет, после направи тест кадър при повторното заснемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Преместен продукт","content":{"prompt":"В повторния кадър продуктът е завъртян, а рекламата трябва да показва същия етикет. Какво правиш?","options":[{"id":"a","label":"Оставяш го, защото монтажът може да обърне картината."},{"id":"b","label":"Изрязваш етикета от кадър."},{"id":"c","label":"Възстановяваш ориентацията по референтния кадър и записваш нов тест заедно с ключовото действие."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Сравни референтната позиция и потвърди, че важната маркировка остава видима.\n\nВариантът „Оставяш го, защото монтажът може да обърне картината.“ не доказва: Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени. Вариантът „Изрязваш етикета от кадър.“ оставя нерешено: Екипът пази само настройките на камерата и забравя, че слънцето, дрехите и предметите се променят. Безопасната корекция е: Документирай и физическия сет, после направи тест кадър при повторното заснемане. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"При следващ снимачен ден подреди сет по бележката и сравни тестов кадър."},{"id":"s1","text":"Определи кои елементи трябва да изглеждат свързани между кадрите."},{"id":"s2","text":"Маркирай позиция на камера, стол, продукт и източници на светлина."},{"id":"s3","text":"Запиши камера настройките и направи референтен кадър с кожа и неутрална повърхност."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи кои елементи трябва да изглеждат свързани между кадрите.\n2. Маркирай позиция на камера, стол, продукт и източници на светлина.\n3. Запиши камера настройките и направи референтен кадър с кожа и неутрална повърхност.\n4. При следващ снимачен ден подреди сет по бележката и сравни тестов кадър."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще направиш различни записи да изглеждат като една серия, като документираш това, което реално може да се повтори.","Документирай и физическия сет, после направи тест кадър при повторното заснемане.","Вторият дубъл запазва гледна точка, основна светлина и състояние на предмета; отклоненията са отбелязани и умишлени."],"nextStep":"Създай continuity карта за серия от три клипа. Снимай референция, прибери реквизита и опитай да възстановиш кадъра на следващия ден."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-04","title":"Графикът на снимачния ден: снимай по сет, пази енергията","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще подредиш снимачния ред според смени на локация и техника, без да изтощиш хората и да загубиш кадри.","hook":"Екипът сменя осветление за всеки клип, прескача от стая в стая и губи час в пренареждане.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подредиш снимачния ред според смени на локация и техника, без да изтощиш хората и да загубиш кадри."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Екипът сменя осветление за всеки клип, прескача от стая в стая и губи час в пренареждане."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Групирай сходните задачи по място, човек, светлина и оборудване, но не превръщай актьора или клиента в производствена машина. Снимай най-важните сцени, когато екипът е свеж; остави възстановяване, вода и буфер след блокове с много повторения. Ако дреха или реквизит трябва да се смени, пази реда по последователност.\n\nНай-краткият маршрут невинаги е най-добрият график. Предвиди шум на локацията, достъп, паркиране, естествена светлина, разрешения и срок за връщане на техника. Промяната в графика трябва да обнови списъка с кадри и да бъде видима за продуцента и клиента."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Работи в блокове: пристигане/осмотр, светлинен тест, кратък сет, серия кадри, проверка, почивка, смяна, финален копиращ период. За интервю вземи звука преди да изградиш сложен кадър. Ако човекът е нужен само за две сцени, планирай прозорец, но не оставяй най-трудната реплика за последните минути."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Отбележи локации, хора, реквизит, достъп и часове на естествена светлина.\n2. Сгрупирай кадрите по най-малко смени на сет и ясно обозначи нужната дреха/реквизит.\n3. Започни с критичните кадри, които са трудни за повторение.\n4. Добави паузи и резерв между блоковете; не планирай непрекъснат запис.\n5. Провери заснетите кадри при всяка смяна и премести липсващото, докато е възможно.\n6. Изпрати обновен ред и статус на участниците и монтажиста."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Една организация снима кадри на рецепция, в кабинет и на открито. Вместо шест пътувания, екипът снима всички сцени в кабинета, после рецепцията и накрая външния план преди залез. Ключовото интервю е в първия блок, когато специалистът е свободен.\n\nКритерий за добър ход: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет."},"after":{"label":"Как го поправяш","text":"Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи график за една локация и три сета. Впиши блок за транспорт/пренареждане, почивки, най-критичен кадър, одобрение и финална проверка.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Сгрупирай кадрите по най-малко смени на сет и ясно обозначи нужната дреха/реквизит. Добави паузи и резерв между блоковете; не планирай непрекъснат запис.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип.\n\nТестът е минал едва когато: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Една организация снима кадри на рецепция, в кабинет и на открито. Вместо шест пътувания, екипът снима всички сцени в кабинета, после рецепцията и накрая външния план преди залез. Ключовото интервю е в първия блок, когато специалистът е свободен.\n\nДоставката ти е: Направи график за една локация и три сета. Впиши блок за транспорт/пренареждане, почивки, най-критичен кадър, одобрение и финална проверка.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Подреди по зависимости","content":{"question":"Какво определя най-ефикасния ред на кадрите?","options":[{"id":"a","label":"Редът, в който сценариите са написани."},{"id":"b","label":"Сет, хора, локация, светлина, достъп и критичност за проекта."},{"id":"c","label":"Номерът на клипа в месечния календар."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Организирай заснемането по реалната цена на смяната и риска.\n\nВариантът „Номерът на клипа в месечния календар.“ не доказва: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Вариантът „Редът, в който сценариите са написани.“ оставя нерешено: Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет. Безопасната корекция е: Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Гостът има само 20 минути","content":{"prompt":"Ключовият интервюиран е на разположение кратко. Какво правиш?","options":[{"id":"a","label":"Подготвяш сет предварително, тестваш звук/светлина и снимаш критичната реплика в договорения прозорец."},{"id":"b","label":"Махаш теста, за да започнеш по-рано."},{"id":"c","label":"Оставяш интервюто за последно след всички декоративни кадри."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Подготовката преди пристигане пази времето на човека и качеството на кадъра.\n\nВариантът „Оставяш интервюто за последно след всички декоративни кадри.“ не доказва: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Вариантът „Махаш теста, за да започнеш по-рано.“ оставя нерешено: Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет. Безопасната корекция е: Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Защо има буфер","content":{"question":"Какво покрива буферът между снимачни блокове?","options":[{"id":"a","label":"Допълнителна дължина на клипа."},{"id":"b","label":"Възможност за пропускане на копие и QA."},{"id":"c","label":"Промяна на сет, шум, повторен дубъл и реални прекъсвания."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Буферът е план за вариация, не свободно време за неограничен обхват.\n\nВариантът „Допълнителна дължина на клипа.“ не доказва: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Вариантът „Възможност за пропускане на копие и QA.“ оставя нерешено: Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет. Безопасната корекция е: Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Един сет се забавя","content":{"prompt":"Първият блок закъснява, а слънцето ще залезе. Какъв е приоритетът?","options":[{"id":"a","label":"Премахваш проверката на записаното."},{"id":"b","label":"Продължаваш по стария ред независимо от светлината."},{"id":"c","label":"Снимаш външния кадър, който зависи от светлината, и съгласуваш останалия ред."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Пренареди зависимия кадър и съобщи промяната на екипа.\n\nВариантът „Продължаваш по стария ред независимо от светлината.“ не доказва: Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение. Вариантът „Премахваш проверката на записаното.“ оставя нерешено: Кадрите се подреждат по номер на готовите видеа, макар това да означава многократно разглобяване на един и същ сет. Безопасната корекция е: Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Добави паузи и резерв между блоковете; не планирай непрекъснат запис."},{"id":"s3","text":"Започни с критичните кадри, които са трудни за повторение."},{"id":"s2","text":"Сгрупирай кадрите по най-малко смени на сет и ясно обозначи нужната дреха/реквизит."},{"id":"s1","text":"Отбележи локации, хора, реквизит, достъп и часове на естествена светлина."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Отбележи локации, хора, реквизит, достъп и часове на естествена светлина.\n2. Сгрупирай кадрите по най-малко смени на сет и ясно обозначи нужната дреха/реквизит.\n3. Започни с критичните кадри, които са трудни за повторение.\n4. Добави паузи и резерв между блоковете; не планирай непрекъснат запис."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще подредиш снимачния ред според смени на локация и техника, без да изтощиш хората и да загубиш кадри.","Организирай по локация и настройки; пази отделно кои са задължителните кадри във всеки клип.","Графикът показва къде и кога се сменя сет, кой трябва да е на място, буфера и ред за повторение."],"nextStep":"Направи график за една локация и три сета. Впиши блок за транспорт/пренареждане, почивки, най-критичен кадър, одобрение и финална проверка."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-05","title":"Колко материал поема екипът: измери капацитета, не го гадай","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще изчислиш реален производствен капацитет и ще покажеш къде забавя целият процес.","hook":"Камерата снима бързо, но монтажът, обратната връзка и липсващите файлове правят екипа неспособен да предаде обещания обем.","estimated_minutes":39,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изчислиш реален производствен капацитет и ще покажеш къде забавя целият процес."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Камерата снима бързо, но монтажът, обратната връзка и липсващите файлове правят екипа неспособен да предаде обещания обем."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Капацитетът е брой приети доставки за даден период, не броят заснети дубъли. Измери време по роли: сценарий, подготовка, снимане, ingest, чернова, проверка, корекция и предаване. Добави процент за повторно заснемане и клиентски отговор. Верига спира на тесния участък: ако монтажът отнема два дни, по-бърза камера няма да утрои изхода.\n\nИзползвай данни от няколко седмици и разделяй типове задача. Не смесвай 15-секундни talking head клипове със събитие, анимация или multi-camera интервю. Капацитетът трябва да пази качество и работно време, не да доказва, че екипът може да работи без почивка."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Следи три числа: планирани минути, действителни минути и годни/приети клипове. Добави причина за отклонение: забавено одобрение, технически проблем, ново изискване, повторна корекция. Сметни медианата и разброса по тип работа. Продавай обещание според устойчивия темп, не според най-добрия ден."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Раздели доставките по сложност и канал.\n2. Запиши време по фаза и роля за няколко реални проекта.\n3. Отдели чакането от активната работа, но запиши срок за обратна връзка.\n4. Считай само приети файлове; запиши повторни снимки и поправки.\n5. Намери фазата с най-много забавяне или грешки.\n6. Промени един процесс, измери отново и провери, че качество не е паднало."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Монтажистът довършва 12 клипа месечно, а екипът планира 20. Данните показват, че половината време отива в неясни клиентски бележки и повторно експортиране. Нов лимит на ревизиите и фиксиран бриф повишават изхода повече от покупка на по-бърз компютър.\n\nКритерий за добър ход: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения."},"after":{"label":"Как го поправяш","text":"Мери целия процес до приет файл; промени тесния участък, после отново измери резултата."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Води лог за три работни дни. Запиши активното време, чакането, броя приети клипове, върнатите поправки и причината. Изчисли устойчив седмичен капацитет.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Запиши време по фаза и роля за няколко реални проекта. Считай само приети файлове; запиши повторни снимки и поправки.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Мери целия процес до приет файл; промени тесния участък, после отново измери резултата.\n\nТестът е минал едва когато: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Монтажистът довършва 12 клипа месечно, а екипът планира 20. Данните показват, че половината време отива в неясни клиентски бележки и повторно експортиране. Нов лимит на ревизиите и фиксиран бриф повишават изхода повече от покупка на по-бърз компютър.\n\nДоставката ти е: Води лог за три работни дни. Запиши активното време, чакането, броя приети клипове, върнатите поправки и причината. Изчисли устойчив седмичен капацитет.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Мери крайния резултат","content":{"question":"Кое е най-добро измерване на производителността?","options":[{"id":"a","label":"Приети доставки за период, с време и корекции по фази."},{"id":"b","label":"Брой часове, в които камерата е включена."},{"id":"c","label":"Брой заснети клипове без преглед."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Само приетият продукт затваря веригата.\n\nВариантът „Брой заснети клипове без преглед.“ не доказва: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Вариантът „Брой часове, в които камерата е включена.“ оставя нерешено: Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения. Безопасната корекция е: Мери целия процес до приет файл; промени тесния участък, после отново измери резултата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Монтажът е тесният участък","content":{"prompt":"Снимането изпреварва монтажа. Какво е разумното първо действие?","options":[{"id":"a","label":"Купуваш нов телефон и обещаваш повече клипове."},{"id":"b","label":"Скъсяваш всеки монтаж, без да питаш клиента."},{"id":"c","label":"Измерваш причините в монтажа и корекциите; временно коригираш броя доставки или добавяш капацитет там."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Надгради тесния участък; нова скорост другаде не променя общия поток.\n\nВариантът „Купуваш нов телефон и обещаваш повече клипове.“ не доказва: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Вариантът „Скъсяваш всеки монтаж, без да питаш клиента.“ оставя нерешено: Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения. Безопасната корекция е: Мери целия процес до приет файл; промени тесния участък, после отново измери резултата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Сравнявай сходно със сходно","content":{"question":"Как да изчислиш типично време за монтаж?","options":[{"id":"a","label":"Събери всички проекти, независимо от сложността."},{"id":"b","label":"Използвай най-бързия случай от всички формати."},{"id":"c","label":"Групирай сходни формати и използвай няколко наблюдения с медиана и разброс."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Различните задачи имат различни стъпки и трябва да се измерват отделно.\n\nВариантът „Използвай най-бързия случай от всички формати.“ не доказва: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Вариантът „Събери всички проекти, независимо от сложността.“ оставя нерешено: Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения. Безопасната корекция е: Мери целия процес до приет файл; промени тесния участък, после отново измери резултата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Клиентът чака три седмици","content":{"prompt":"Половината срок се губи в отговор от клиента. Как го отчиташ?","options":[{"id":"a","label":"Записваш чакането, задаваш срок за обратна връзка и коригираш обещаната дата според зависимостта."},{"id":"b","label":"Изключваш чакането от плана и запазваш старата дата."},{"id":"c","label":"Правиш промени без одобрение, за да не чакаш."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Зависимостта трябва да е видима за клиента и да влияе на графика.\n\nВариантът „Изключваш чакането от плана и запазваш старата дата.“ не доказва: Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения. Вариантът „Правиш промени без одобрение, за да не чакаш.“ оставя нерешено: Сметката включва само минути на запис и пренебрегва post, корекции, одобрения и повторения. Безопасната корекция е: Мери целия процес до приет файл; промени тесния участък, после отново измери резултата. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Запиши време по фаза и роля за няколко реални проекта."},{"id":"s3","text":"Отдели чакането от активната работа, но запиши срок за обратна връзка."},{"id":"s4","text":"Считай само приети файлове; запиши повторни снимки и поправки."},{"id":"s1","text":"Раздели доставките по сложност и канал."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Раздели доставките по сложност и канал.\n2. Запиши време по фаза и роля за няколко реални проекта.\n3. Отдели чакането от активната работа, но запиши срок за обратна връзка.\n4. Считай само приети файлове; запиши повторни снимки и поправки."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще изчислиш реален производствен капацитет и ще покажеш къде забавя целият процес.","Мери целия процес до приет файл; промени тесния участък, после отново измери резултата.","Предложен капацитет има данни, разделя типове работа, съдържа резерв и не прикрива чакащи клиентски одобрения."],"nextStep":"Води лог за три работни дни. Запиши активното време, чакането, броя приети клипове, върнатите поправки и причината. Изчисли устойчив седмичен капацитет."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-06","title":"Монтажен поток за серия: шаблонът помага, но не взема решения","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще превърнеш една серия от клипове в повторяем монтажен процес със специфична проверка за всеки епизод.","hook":"Шаблонът ускори сглобяването, но постави грешното име върху продукта и музиката заглушава единствената важна реплика.","estimated_minutes":41,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще превърнеш една серия от клипове в повторяем монтажен процес със специфична проверка за всеки епизод."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Шаблонът ускори сглобяването, но постави грешното име върху продукта и музиката заглушава единствената важна реплика."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Шаблонът трябва да стандартизира повтарящи се настройки, цветове, лога и позиции; той не решава историята, акцента, точността или етиката. Направи базов проект с чиста таймлайн структура, стилове, графики и име на версия. Дублирай проекта за нов епизод, не презаписвай приключен клиентски файл.\n\nЗа всяка версия провери специфични имена, факти, ритъм, субтитри, цветови кадри, нива на говор и CTA. Ако формата или профилът на проекта се сменя, направи нов шаблон, вместо да добавяш изключения, които никой не разбира."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Принимай една смяна в шаблона отговорно: копие, версия, кратка бележка и тест на един клип. Запази изходен вариант без графики. Използвай маркери за одобрение и финални кадри, за да не разчиташ на цвят на папка или памет. Обновявай шаблон между проектите."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Създай чист проект с фреймрейт, цветово управление и аудио структура от брифа.\n2. Подреди bins за видео, аудио, графики, проксита, проекти и експорти.\n3. Добави повторяеми графики, но остави място за индивидуални кадри и надписи.\n4. Направи копие на проекта за епизода и свържи оригиналните медии.\n5. Редактирай по смисъл и провери фактите и ефекта по всеки клип.\n6. Експортирай с име/версия и пусни QC; върни поправките в отделна версия."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Видеосерията на клиника използва еднакъв начален знак и надпис за специалист. В нов епизод се сменя лекарят, услугата и юридическата бележка; монтажистът дублира шаблона, обновява само данните и проверява звук, кадър и точен текст.\n\nКритерий за добър ход: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл."},"after":{"label":"Как го поправяш","text":"Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай шаблон за три кратки клипа. Направи отделни копия, смени имена и CTA, после използвай чеклист, който открива една нарочно поставена стара информация.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Подреди bins за видео, аудио, графики, проксита, проекти и експорти. Направи копие на проекта за епизода и свържи оригиналните медии.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи.\n\nТестът е минал едва когато: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Видеосерията на клиника използва еднакъв начален знак и надпис за специалист. В нов епизод се сменя лекарят, услугата и юридическата бележка; монтажистът дублира шаблона, обновява само данните и проверява звук, кадър и точен текст.\n\nДоставката ти е: Създай шаблон за три кратки клипа. Направи отделни копия, смени имена и CTA, после използвай чеклист, който открива една нарочно поставена стара информация.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Стандартизирай повторяемото","content":{"question":"Какво е добра задача за шаблон?","options":[{"id":"a","label":"Решение за най-добрия дубъл във всеки епизод."},{"id":"b","label":"Автоматично избиране на факти и клиентски твърдения."},{"id":"c","label":"Постоянни технически настройки, шрифтове и позиции, които са одобрени за серията."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Шаблонът пази консистентност, не замества редакторска преценка.\n\nВариантът „Решение за най-добрия дубъл във всеки епизод.“ не доказва: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Вариантът „Автоматично избиране на факти и клиентски твърдения.“ оставя нерешено: Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл. Безопасната корекция е: Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Стар номер върху графика","content":{"prompt":"В новия клип се появява телефонът от предишния клиент. Какво правиш?","options":[{"id":"a","label":"Надяваш се, че текстът е твърде малък за четене."},{"id":"b","label":"Покриваш номера с надпис само в един клип."},{"id":"c","label":"Спираш предаването, коригираш източника и графиката, после преглеждаш всички изходи от серията."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Провери изходния проект и всички версии, не само видимия кадър.\n\nВариантът „Покриваш номера с надпис само в един клип.“ не доказва: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Вариантът „Надяваш се, че текстът е твърде малък за четене.“ оставя нерешено: Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл. Безопасната корекция е: Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Проект или export","content":{"question":"Защо нов епизод започва от копие на шаблона?","options":[{"id":"a","label":"Пази базата и историята на предишните проекти, като изолира новите имена и медии."},{"id":"b","label":"За да използваш чужда медия без да я копираш."},{"id":"c","label":"За да обединиш всички клипове в една времева линия."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Отделният проект ограничава случайни промени и помага на следващ редактор.\n\nВариантът „За да използваш чужда медия без да я копираш.“ не доказва: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Вариантът „За да обединиш всички клипове в една времева линия.“ оставя нерешено: Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл. Безопасната корекция е: Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Клиент сменя цветовете","content":{"prompt":"Клиентът одобрява нова цветова тема за серията. Как я внедряваш?","options":[{"id":"a","label":"Презаписваш базата преди да провериш четливостта."},{"id":"b","label":"Копираш шаблона, документираш версията и тестваш промяната върху един клип преди останалите."},{"id":"c","label":"Променяш само един епизод, без да кажеш на екипа."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери промяната и обнови версията, преди да стане стандарт.\n\nВариантът „Презаписваш базата преди да провериш четливостта.“ не доказва: Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката. Вариантът „Променяш само един епизод, без да кажеш на екипа.“ оставя нерешено: Проектът от минал клиент се презаписва; старият телефонен номер и цветова настройка попадат в новия файл. Безопасната корекция е: Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Подреди bins за видео, аудио, графики, проксита, проекти и експорти."},{"id":"s1","text":"Създай чист проект с фреймрейт, цветово управление и аудио структура от брифа."},{"id":"s4","text":"Направи копие на проекта за епизода и свържи оригиналните медии."},{"id":"s3","text":"Добави повторяеми графики, но остави място за индивидуални кадри и надписи."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Създай чист проект с фреймрейт, цветово управление и аудио структура от брифа.\n2. Подреди bins за видео, аудио, графики, проксита, проекти и експорти.\n3. Добави повторяеми графики, но остави място за индивидуални кадри и надписи.\n4. Направи копие на проекта за епизода и свържи оригиналните медии."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще превърнеш една серия от клипове в повторяем монтажен процес със специфична проверка за всеки епизод.","Дублирай базов проект за всяка поръчка и използвай клиентски QA лист, който проверява конкретни променливи.","Всеки епизод има отделен проект и версия; стар текст/име не остава, а брифът и проверките се намират в папката."],"nextStep":"Създай шаблон за три кратки клипа. Направи отделни копия, смени имена и CTA, после използвай чеклист, който открива една нарочно поставена стара информация."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-07","title":"Публикационен календар: кой одобрява, какво изтича и какво е готово","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще изградиш календар за видео, който отразява реални състояния, срокове, отговорници и зависимост от клиента.","hook":"Клипът е в календара със статус „готов“, но все още чака одобрение и съдържа старо работно време.","estimated_minutes":37,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изградиш календар за видео, който отразява реални състояния, срокове, отговорници и зависимост от клиента."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Клипът е в календара със статус „готов“, но все още чака одобрение и съдържа старо работно време."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Календарът не е списък от дати. Той показва тема, канал, версия, срок, отговорник, одобрител, права и състояние. Използвай ясни състояния като идея, сценарий за проверка, одобрен за снимане, заснет, монтаж, клиентски преглед, одобрен, насрочен и публикуван. Не маркирай одобрен без доказателство или запис на човека, който е одобрил.\n\nАктуални цени, промоции, локации и сезонни правила трябва да имат валидност. Публикационен слот за тях се планира близо до проверката. Подготви резервна тема, ако фактите не могат да бъдат потвърдени навреме; не оставяй календара да притиска екипа към догадки."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"За всяка публикация има финален файл, текст, миниатюра, линк към правата или източника, формат, субтитри, дата/час и процедура за сваляне или корекция. Не допускай два човека да приемат, че другият ще публикува. След публикация провери действителния пост и запиши URL."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Създай колони за активност, собственик, одобрител и статус.\n2. Свържи всяка тема с канал и конкретен формат/версия.\n3. Отбележи твърдения с дата, права, срокове и клиентски dependencies.\n4. Задай срок за одобрение и автоматично видим статус при закъснение.\n5. Преди насрочване свери файл, текст, CTA, формат, права и финална версия.\n6. След публикация отвори действителния пост, запиши адрес и коригирай календара."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Ресторант планира клип за меню, което се сменя в петък. Фактът е проверен в четвъртък сутрин и има отговорник за цени. Ако потвърждението не дойде, резервната evergreen тема за кухнята замества клипа; календарът пази причината.\n\nКритерий за добър ход: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание."},"after":{"label":"Как го поправяш","text":"Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Изгради седмица за две платформи с осем публикации. Включи собственик, одобрител, готов файл, валидност на фактите, резервна публикация и поле за URL след публикуване.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Свържи всяка тема с канал и конкретен формат/версия. Задай срок за одобрение и автоматично видим статус при закъснение.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл.\n\nТестът е минал едва когато: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Ресторант планира клип за меню, което се сменя в петък. Фактът е проверен в четвъртък сутрин и има отговорник за цени. Ако потвърждението не дойде, резервната evergreen тема за кухнята замества клипа; календарът пази причината.\n\nДоставката ти е: Изгради седмица за две платформи с осем публикации. Включи собственик, одобрител, готов файл, валидност на фактите, резервна публикация и поле за URL след публикуване.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Какво значи готово","content":{"question":"Кога календарът може да постави клип в статус „одобрен“?","options":[{"id":"a","label":"Клипът изглежда добре на телефона на оператора."},{"id":"b","label":"Монтажистът е изпратил първи export."},{"id":"c","label":"Има записан одобрител и конкретната версия, която е приета."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Одобрението се отнася за конкретна версия, не за обща идея.\n\nВариантът „Монтажистът е изпратил първи export.“ не доказва: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Вариантът „Клипът изглежда добре на телефона на оператора.“ оставя нерешено: Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание. Безопасната корекция е: Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Изтичаща оферта","content":{"prompt":"Клип с промоция е планиран за след две седмици, а срокът на офертата е неизвестен. Какво правиш?","options":[{"id":"a","label":"Проверяваш срока и отговорника, иначе заменяш слота с проверено съдържание."},{"id":"b","label":"Публикуваш и добавяш малък disclaimer."},{"id":"c","label":"Оставяш цену без дата."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Календарът трябва да спре изтекъл или непотвърден факт.\n\nВариантът „Публикуваш и добавяш малък disclaimer.“ не доказва: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Вариантът „Оставяш цену без дата.“ оставя нерешено: Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание. Безопасната корекция е: Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Затвори публикационния цикъл","content":{"question":"Какво записваш след публикация?","options":[{"id":"a","label":"Само отметка, че календарът е попълнен."},{"id":"b","label":"Действителния URL, време и финалната версия, за да може екипът да провери резултата."},{"id":"c","label":"Новата тема за следващия месец."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Проверката след publish потвърждава, че правилният файл стигна до правилния канал.\n\nВариантът „Само отметка, че календарът е попълнен.“ не доказва: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Вариантът „Новата тема за следващия месец.“ оставя нерешено: Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание. Безопасната корекция е: Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Двама мислят, че другият публикува","content":{"prompt":"Клипът е одобрен, но в деня на публикация няма собственик. Какво променяш?","options":[{"id":"a","label":"Маркираш публикацията като направена предварително."},{"id":"b","label":"Назначаваш един отговорник за публикуване и резервен, после проверяваш реалния пост."},{"id":"c","label":"Оставяш задачата в общата група без име."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Един собственик на следващото действие премахва двусмислието.\n\nВариантът „Оставяш задачата в общата група без име.“ не доказва: Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването. Вариантът „Маркираш публикацията като направена предварително.“ оставя нерешено: Календарът съдържа само дата и тема, затова никой не вижда изчакващи одобрения или изтекло съдържание. Безопасната корекция е: Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Задай срок за одобрение и автоматично видим статус при закъснение."},{"id":"s1","text":"Създай колони за активност, собственик, одобрител и статус."},{"id":"s2","text":"Свържи всяка тема с канал и конкретен формат/версия."},{"id":"s3","text":"Отбележи твърдения с дата, права, срокове и клиентски dependencies."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Създай колони за активност, собственик, одобрител и статус.\n2. Свържи всяка тема с канал и конкретен формат/версия.\n3. Отбележи твърдения с дата, права, срокове и клиентски dependencies.\n4. Задай срок за одобрение и автоматично видим статус при закъснение."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще изградиш календар за видео, който отразява реални състояния, срокове, отговорници и зависимост от клиента.","Управлявай състояния, собственик, версия и валидност; насрочвай само одобрен файл.","Няма планирано съдържание без одобрител, потвърден файл и ясна отговорност за публикуването."],"nextStep":"Изгради седмица за две платформи с осем публикации. Включи собственик, одобрител, готов файл, валидност на фактите, резервна публикация и поле за URL след публикуване."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-08","title":"Име на файл, което колегата може да разбере","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще направиш правила за име и версия, които помагат на екипа да намери оригинал, проект и правилен export.","hook":"В папката има final.mp4, final_new.mp4, final2.mp4 и final_final2.mp4; никой не знае коя е одобрената версия.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш правила за име и версия, които помагат на екипа да намери оригинал, проект и правилен export."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"В папката има final.mp4, final_new.mp4, final2.mp4 и final_final2.mp4; никой не знае коя е одобрената версия."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Името трябва да отговаря на практичните въпроси: клиент/проект, дата или кампания, формат/език, версия и състояние. Избери разделител и правило за версия, което е лесно за сортиране и не разчита на умалителни като „ново“ или „последно“. Името на проекта и папките трябва да съвпада с работната система, за да не се разкача медията.\n\nНе използвай лични данни в публични линкове, които не са нужни за работа. За оригиналните имена запази карта или manifest, ако клиентът/камерата изисква непроменени файлове. Вземи съгласие на екипа и създай примерни имена преди да преименуваш партида.\n\nПолеви наръчник: Договори реда на полетата с екипа преди да преименуваш десетки файлове. Полезната схема може да включва проект, дата, камера/карта, сцена, дубъл и версия; остави само полета, които някой реално търси. Пример: `Klinika_20260928_A_C03_T02` със запазено разширение. Серийните номера трябва да са уникални и подредими; не презаписвай дубъл с нова версия и не променяй името на camera original без план за relink. Запази таблица „оригинално име → ново име“ и тествай десет файла с дълги имена, сходни сцени и различни камери. Монтажистът трябва да различи дубъла без да отваря всеки файл, а relink да работи и на друга станция.\n\nРаботна проверка: Промяната на имената се прави върху копие или с инструмент, който пази съответствие старо/ново и отчита конфликтите преди запис. Сравни броя файлове, размерите и checksum за критичния материал; не приемай „готово“ от прозореца на rename. Отвори проекта на отделна работна станция и тествай relink, после остави непроменените оригинали до приключване на проверката. Ако схема за име се смени, версионирай инструкциите и извести целия екип в една точка.\n\nДопълнителен ход от практиката: Установи дали системата за ingest, облачната папка и монтажният софтуер приемат еднакви символи и максимална дължина на името. Избягвай наклонени черти, двусмислени дати и status-и като FINAL_FINAL; постави версиите в отделно поле или папка. Остави неизменен camera reel/clip ID в метаданните, когато името се обновява. Преди масова промяна направи журнал, dry run и план за откат; после провери, че proxy pairing и sidecar metadata също са запазени и именувани по договорената схема.\n\nПрактически разбор: Полезен pattern може да е Client_Project_Date_Channel_Language_Version_Status.ext; адаптирай полетата към екипа и каналите. Номерирай версии последователно, записвай финалност отделно и не преименувай файл след като е свързан към монтажен проект без relink тест."},"points":2,"required":true},{"position":3,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Изброй въпросите, на които файлът трябва да отговори без отваряне.\n2. Избери постоянни полета, ред, разделител и правила за празно поле.\n3. Определи версия, одобрение и формат; забрани имена като final-final.\n4. Създай именувани примери за raw, project, proxy и export.\n5. Приложи правилото първо към копия и провери сортиране и relink.\n6. Обучи екипа; запиши owner на схемата и процедурата за промяна."},"points":2,"required":true},{"position":4,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Три монтажисти предават вертикални реклами на клиент. Новото правило включва клиент, кампания, дата, формат, език, версия и status; оригиналите запазват номера на камерата, а CSV manifest връзва оригинал с монтажния asset.\n\nХод, който се проваля: Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове.\n\nКорекция: Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна.\n\nКритерий за добър ход: Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката."},"points":2,"required":true},{"position":5,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Измисли 12 файла: raw, аудио, проект, proxy и два изхода на два езика. Приложи схема и помоли колега да намери одобрената версия без обяснение.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":6,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":7,"block_key":"quiz_1","block_type":"quiz","title":"Име за екип","content":{"question":"Кое име най-полезно различава финалните файлове?","options":[{"id":"a","label":"Съгласувани полета за клиент, проект, формат, език, версия и статус."},{"id":"b","label":"final-new-last.mp4."},{"id":"c","label":"Кратко име, което разбира само авторът."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Стандартизираното име прави версиите филтруеми и разбираеми.\n\nВариантът „final-new-last.mp4.“ не доказва: Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката. Вариантът „Кратко име, което разбира само авторът.“ оставя нерешено: Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове. Безопасната корекция е: Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":8,"block_key":"scenario_1","block_type":"scenario","title":"Проектът offline","content":{"prompt":"След преименуване на raw файловете монтажът не намира медиата. Какво правиш?","options":[{"id":"a","label":"Изтриваш offline items и започваш отначало."},{"id":"b","label":"Възстановяваш пътя или relink-ваш по manifest върху копие, после проверяваш клиповете."},{"id":"c","label":"Преименуваш и проекта до същото заглавие."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Нужна е връзка между старите имена и новите пътища; поправи контролирано.\n\nВариантът „Изтриваш offline items и започваш отначало.“ не доказва: Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката. Вариантът „Преименуваш и проекта до същото заглавие.“ оставя нерешено: Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове. Безопасната корекция е: Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"quiz_2","block_type":"quiz","title":"Пази оригиналния контекст","content":{"question":"Какво правиш с имената на камерните файлове?","options":[{"id":"a","label":"Премахваш номерата, за да са имената кратки."},{"id":"b","label":"Запазваш ги или водиш проверим manifest, който свързва оригинал с работното име."},{"id":"c","label":"Преименуваш директно картата по памет."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Оригиналният ID помага при повторно копиране и проверка на източника.\n\nВариантът „Преименуваш директно картата по памет.“ не доказва: Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката. Вариантът „Премахваш номерата, за да са имената кратки.“ оставя нерешено: Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове. Безопасната корекция е: Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_2","block_type":"scenario","title":"Две финални версии","content":{"prompt":"Клиентът одобри вариант на английски, но има и български export. Как различаваш?","options":[{"id":"a","label":"Включваш език, формат, версия и статус в името според общото правило."},{"id":"b","label":"Записваш върху единия файл."},{"id":"c","label":"Пишеш final_en и final_bg без да посочиш проект и версия."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Езикът и статусът са различни измерения; пази ги заедно с версия и проект.\n\nВариантът „Пишеш final_en и final_bg без да посочиш проект и версия.“ не доказва: Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката. Вариантът „Записваш върху единия файл.“ оставя нерешено: Преименуваш клипове на камерата след монтаж и пътищата в проекта сочат към несъществуващи файлове. Безопасната корекция е: Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Създай именувани примери за raw, project, proxy и export."},{"id":"s3","text":"Определи версия, одобрение и формат; забрани имена като final-final."},{"id":"s2","text":"Избери постоянни полета, ред, разделител и правила за празно поле."},{"id":"s1","text":"Изброй въпросите, на които файлът трябва да отговори без отваряне."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Изброй въпросите, на които файлът трябва да отговори без отваряне.\n2. Избери постоянни полета, ред, разделител и правила за празно поле.\n3. Определи версия, одобрение и формат; забрани имена като final-final.\n4. Създай именувани примери за raw, project, proxy и export."},"scoring":{"mode":"exact_order"}},{"position":12,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще направиш правила за име и версия, които помагат на екипа да намери оригинал, проект и правилен export.","Преименувай на ingest или използвай manifest; пробвай relink на копие преди серийна промяна.","Друг човек намира клиент, проект, формат, език и одобрена версия само от името и папката."],"nextStep":"Измисли 12 файла: raw, аудио, проект, proxy и два изхода на два езика. Приложи схема и помоли колега да намери одобрената версия без обяснение."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-09","title":"Папки, които водят монтажиста от брифа до export","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще изградиш структура на проект, в която колега намира източници, проект, версии и готов файл без въпроси.","hook":"Суровият материал, експорти, проксита и договор са в една папка; при предаване липсват медии и неясно е кой файл е master.","estimated_minutes":32,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изградиш структура на проект, в която колега намира източници, проект, версии и готов файл без въпроси."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Суровият материал, експорти, проксита и договор са в една папка; при предаване липсват медии и неясно е кой файл е master."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Структурата следва работния поток, не вкуса на автора. Раздели бриф/администрация, оригинална медия, звук, графики, проектни файлове, проксита, exports, handoff и архив. Пази оригиналите отделно от производните файлове и не поставяй ключови документи само на работния плот.\n\nИзползвай една и съща схема за всички проекти, но не добавяй папки, които никой не ползва. Номерирай етапите, ако редът има значение. Определи къде ще се намират файловете на всеки работен компютър и как се relink-ват; папка с красиво име не помага, ако пътищата се променят без manifest."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Примерна основа: 00_Brief, 01_Admin_Rights, 02_Media/Video, 02_Media/Audio, 03_Graphics, 04_Project, 05_Proxies, 06_Exports, 07_Delivery, 08_Archive. Съгласувай с монтажния софтуер и екипната система. Носи readme с версия, aspect ratio, frame rate, цветово управление и контакт за въпроси."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Събери изисквания от монтажиста и отговорника за архива.\n2. Създай чиста структура и readme в тестов проект.\n3. Копирай медията в отделна папка, запази оригиналните имена и manifest.\n4. Постави проект, проксита и exports в отделните зони.\n5. Отвори проекта от пътя, който получателят ще използва; провери relink.\n6. Предай структурата и кратка карта на съдържанието; забрани празни копия като стандарт."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Външен монтажист получава проект от агенция. Readme посочва кадри в секунда, ориентация и името на одобрената версия; папките отделят оригинали, аудио, проксита и exports. Монтажистът отваря проекта без търсене на медия.\n\nКритерий за добър ход: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Папките се именуват с вътрешни шеги и всички версии се слагат на едно място."},"after":{"label":"Как го поправяш","text":"Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи празна структура за интервю, реклама и серия. Попълни readme и помоли човек, който не е създал папките, да намери одобрения export и суровите клипове.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Папките се именуват с вътрешни шеги и всички версии се слагат на едно място.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Създай чиста структура и readme в тестов проект. Постави проект, проксита и exports в отделните зони.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега.\n\nТестът е минал едва когато: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Външен монтажист получава проект от агенция. Readme посочва кадри в секунда, ориентация и името на одобрената версия; папките отделят оригинали, аудио, проксита и exports. Монтажистът отваря проекта без търсене на медия.\n\nДоставката ти е: Направи празна структура за интервю, реклама и серия. Попълни readme и помоли човек, който не е създал папките, да намери одобрения export и суровите клипове.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Отдели източника","content":{"question":"Къде се пазят оригиналните клипове?","options":[{"id":"a","label":"В папката на всеки монтажен вариант."},{"id":"b","label":"В отделна, ясно назована зона, отделена от проксита и exports."},{"id":"c","label":"До final.mp4 без указание за източник."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Ясното разделяне намалява презапис и улеснява relink.\n\nВариантът „В папката на всеки монтажен вариант.“ не доказва: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Вариантът „До final.mp4 без указание за източник.“ оставя нерешено: Папките се именуват с вътрешни шеги и всички версии се слагат на едно място. Безопасната корекция е: Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Монтажистът не намира медия","content":{"prompt":"Проектът отваря с missing files при получателя. Какъв е първият ход?","options":[{"id":"a","label":"Преименуваш случайно папките, докато се свържат."},{"id":"b","label":"Сравняваш пътя и manifest, после relink-ваш към оригиналната медия от проверена структура."},{"id":"c","label":"Заменяш всички клипове с експортиран preview."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Възстанови връзката по информацията за източника; не заменяй оригинали с preview.\n\nВариантът „Заменяш всички клипове с експортиран preview.“ не доказва: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Вариантът „Преименуваш случайно папките, докато се свържат.“ оставя нерешено: Папките се именуват с вътрешни шеги и всички версии се слагат на едно място. Безопасната корекция е: Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Използваем readme","content":{"question":"Кое поле помага на външен редактор?","options":[{"id":"a","label":"Къде са оригиналите, коя версия е одобрена и какви са техническите настройки."},{"id":"b","label":"Общото „всичко е вътре“."},{"id":"c","label":"Името на човека, който е измислил папките."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Readme-то трябва да намалява реално търсене и неяснота.\n\nВариантът „Името на човека, който е измислил папките.“ не доказва: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Вариантът „Общото „всичко е вътре“.“ оставя нерешено: Папките се именуват с вътрешни шеги и всички версии се слагат на едно място. Безопасната корекция е: Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Излишни папки","content":{"prompt":"Структурата има 30 празни подпапки и екипът ги игнорира. Какво правиш?","options":[{"id":"a","label":"Добавяш още имена на категории."},{"id":"b","label":"Запазваш всичко, защото е по-детайлно."},{"id":"c","label":"Премахваш неизползваните категории и оставяш тези, които следват действителните handoff-и."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Схемата трябва да се използва, иначе хората създават паралелни системи.\n\nВариантът „Добавяш още имена на категории.“ не доказва: Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките. Вариантът „Запазваш всичко, защото е по-детайлно.“ оставя нерешено: Папките се именуват с вътрешни шеги и всички версии се слагат на едно място. Безопасната корекция е: Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Създай чиста структура и readme в тестов проект."},{"id":"s3","text":"Копирай медията в отделна папка, запази оригиналните имена и manifest."},{"id":"s4","text":"Постави проект, проксита и exports в отделните зони."},{"id":"s1","text":"Събери изисквания от монтажиста и отговорника за архива."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Събери изисквания от монтажиста и отговорника за архива.\n2. Създай чиста структура и readme в тестов проект.\n3. Копирай медията в отделна папка, запази оригиналните имена и manifest.\n4. Постави проект, проксита и exports в отделните зони."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще изградиш структура на проект, в която колега намира източници, проект, версии и готов файл без въпроси.","Въведи структура, която показва предназначение, оригинал/производно и ред на работа; пробвай я с нов колега.","Друг колега намира бриф, медия, проект, proxy и одобрен export само по readme и имената на папките."],"nextStep":"Направи празна структура за интервю, реклама и серия. Попълни readme и помоли човек, който не е създал папките, да намери одобрения export и суровите клипове."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-10","title":"Три копия, два носителя, едно извън мястото","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще приложиш правило за резервиране, провериш копието и покажеш, че материалът може да бъде възстановен.","hook":"Един SSD е паднал на пода; файлът и единственото копие от вчерашното интервю са изчезнали заедно.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще приложиш правило за резервиране, провериш копието и покажеш, че материалът може да бъде възстановен."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Един SSD е паднал на пода; файлът и единственото копие от вчерашното интервю са изчезнали заедно."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"3-2-1 обобщава разделяне на риска: три копия общо, два типа носител и едно отделно физическо място. За защита от ransomware или грешно изтриване се нуждаеш и от offline/immutable копие и история, която не се синхронизира със същата грешка. RAID или синхронизация сами по себе си не са резервно копие.\n\nКопието има смисъл, ако го провериш и можеш да го възстановиш. Задай срок, собственик и достъп. За клиентска медия уточни кога трябва да бъде изтрита; не задържай излишни лични кадри без основание."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Планирай трите copies с реалните места: working SSD, втори отделен диск/NAS и off-site копие. Определи кои данни се включват, колко често се обновяват, какво е versioned, кой проверява лог и кога се прави restore drill. За интернет копие сметни скорост и срок за upload/download; не обещавай възстановяване за минути, ако терабайти прехвърлят цяла нощ."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Нарисувай къде са production, backup copies и off-site местоположението.\n2. Провери дали двата носителя са независими и достъпите им са отделени.\n3. Настрой периодичност, version history, encryption и отговорник.\n4. След копиране провери лог или checksum и отвори избран файл.\n5. Проведи restore drill в празна тестова папка и измери времето.\n6. Запиши срок за съхранение и ред за сигурно изтриване."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Студио пази проект на работен SSD и синхронизира папка в облак. Екипът добавя офлайн диск в друга локация и версия на облачните файлове. Веднъж месечно възстановява случаен клип в тестова папка.\n\nКритерий за добър ход: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие."},"after":{"label":"Как го поправяш","text":"Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Нарисувай поток за един проект, назначи owner и направи тест restore на видео, проектен файл и един административен документ.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Провери дали двата носителя са независими и достъпите им са отделени. След копиране провери лог или checksum и отвори избран файл.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя.\n\nТестът е минал едва когато: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Студио пази проект на работен SSD и синхронизира папка в облак. Екипът добавя офлайн диск в друга локация и версия на облачните файлове. Веднъж месечно възстановява случаен клип в тестова папка.\n\nДоставката ти е: Нарисувай поток за един проект, назначи owner и направи тест restore на видео, проектен файл и един административен документ.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"CISA насърчава offline backups, ограничения на достъпа и регулярна проверка на възстановяването: https://www.cisa.gov/stopransomware/ransomware-guide"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Разлика между sync и backup","content":{"question":"Защо синхронизацията не е достатъчно копие?","options":[{"id":"a","label":"Тя не може да работи с облачна услуга."},{"id":"b","label":"Тя може да разнесе изтриване, повреда или криптиране към синхронизираните места."},{"id":"c","label":"Тя прехвърля само видео."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Backup копието трябва да запазва възстановимо състояние, а не само текущото.\n\nВариантът „Тя прехвърля само видео.“ не доказва: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Вариантът „Тя не може да работи с облачна услуга.“ оставя нерешено: Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие. Безопасната корекция е: Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Грешно изтрита папка","content":{"prompt":"Папката е изтрита и sync-ът я премахна навсякъде. Какво следва?","options":[{"id":"a","label":"Използваш независима версия/offline копие и възстановяваш в тестово място преди замяна."},{"id":"b","label":"Пускаш sync отново, за да възстанови данните."},{"id":"c","label":"Правиш ново копие на празната папка."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Намали риск от презапис на последното копие и възстановявай първо в отделна зона.\n\nВариантът „Правиш ново копие на празната папка.“ не доказва: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Вариантът „Пускаш sync отново, за да възстанови данните.“ оставя нерешено: Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие. Безопасната корекция е: Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Резервът трябва да се възстановява","content":{"question":"Какво прави restore drill?","options":[{"id":"a","label":"Потвърждава, че дискът свети."},{"id":"b","label":"Показва, че файловете имат познато име."},{"id":"c","label":"Доказва, че човекът може да намери и възстанови файл от копието в измерено време."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Съществуването на копие не доказва, че е четимо или достъпно.\n\nВариантът „Потвърждава, че дискът свети.“ не доказва: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Вариантът „Показва, че файловете имат познато име.“ оставя нерешено: Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие. Безопасната корекция е: Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Копие извън офиса","content":{"prompt":"Ограничена мрежа ще качва файловете цяла нощ. Какво планираш?","options":[{"id":"a","label":"Компресираш оригиналите и изтриваш изхода."},{"id":"b","label":"Обявяваш го за архив веднага след старта на качването."},{"id":"c","label":"График за upload, проверка на резултат и реалистично обещание кога off-site копието е готово."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Времето за пренос е част от плана за възстановяване.\n\nВариантът „Обявяваш го за архив веднага след старта на качването.“ не доказва: Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани. Вариантът „Компресираш оригиналите и изтриваш изхода.“ оставя нерешено: Работната папка е огледална към друг диск, така че случайно изтриване се копира и върху единственото копие. Безопасната корекция е: Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Провери дали двата носителя са независими и достъпите им са отделени."},{"id":"s1","text":"Нарисувай къде са production, backup copies и off-site местоположението."},{"id":"s4","text":"След копиране провери лог или checksum и отвори избран файл."},{"id":"s3","text":"Настрой периодичност, version history, encryption и отговорник."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Нарисувай къде са production, backup copies и off-site местоположението.\n2. Провери дали двата носителя са независими и достъпите им са отделени.\n3. Настрой периодичност, version history, encryption и отговорник.\n4. След копиране провери лог или checksum и отвори избран файл."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще приложиш правило за резервиране, провериш копието и покажеш, че материалът може да бъде възстановен.","Добави отделено/versioned копие и проверявай, че възстановяването работи извън production пътя.","Има три копия според риска на проекта, копията са отделени, restore е измерен, а срокът/отговорникът са документирани."],"nextStep":"Нарисувай поток за един проект, назначи owner и направи тест restore на видео, проектен файл и един административен документ."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-11","title":"SSD, NAS или облак: избери според натоварването","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще избереш място за монтаж, обмен и архив по реална скорост, капацитет, достъп и възстановяване.","hook":"Купен е бърз диск според етикета, но голям проект се прехвърля бавно, защото кабелът и компютърът са по-тесният участък.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш място за монтаж, обмен и архив по реална скорост, капацитет, достъп и възстановяване."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Купен е бърз диск според етикета, но голям проект се прехвърля бавно, защото кабелът и компютърът са по-тесният участък."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"SSD е удобен за мобилен монтаж и бърз ingest; NAS позволява споделен достъп и капацитет, но скоростта зависи от мрежата, броя дискове и натоварването; облакът помага за отдалечен обмен и външно копие, но изисква пропускателна способност, права и сметка за трафик. Нито една среда не е по-бърза или по-безопасна сама по себе си.\n\nИзмери действителния трансфер с медията и проекта, не само теоретичната скорост на интерфейс. Помисли за едновременно четене/писане, шум, нагряване, път, достъп, обновяване и възстановяване. Вземи предвид дали монтажният софтуер поддържа споделена работа така, както екипът планира."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Тествай прехвърляне на реална папка и измери устойчивия темп за няколко минути, след което отвори проект и scrub-ни таймлайна. За NAS измери от всяка станция; за облак провери права за споделяне, версии, изтегляне и граници на достъп. Кабел, порт, мрежов switch и диск са един общ път."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи дали системата ще служи за активен монтаж, екипна медия, обмен или архив.\n2. Провери codec, размери и колко души ще четат/пишат едновременно.\n3. Тествай истински файлове през окончателния кабел/порт/мрежа.\n4. Симулирай прекъсване, липса на интернет и пълен диск.\n5. Провери права, version history, отделено backup копие и restore.\n6. Избери система и документирай какво се случва при отказ."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Двама редактори работят по една серия. NAS е общото място за оригиналите, локален SSD носи активния монтаж и облакът дава клиентски review. Екипът предварително тества media path, заключване на проект и скорост от двете станции.\n\nКритерий за добър ход: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп."},"after":{"label":"Как го поправяш","text":"Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Измери едно и също копиране на локален SSD, мрежово място и облак. Запиши време, стабилност, отваряне на проекта, права и път за възстановяване.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Провери codec, размери и колко души ще четат/пишат едновременно. Симулирай прекъсване, липса на интернет и пълен диск.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume.\n\nТестът е минал едва когато: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Двама редактори работят по една серия. NAS е общото място за оригиналите, локален SSD носи активния монтаж и облакът дава клиентски review. Екипът предварително тества media path, заключване на проект и скорост от двете станции.\n\nДоставката ти е: Измери едно и също копиране на локален SSD, мрежово място и облак. Запиши време, стабилност, отваряне на проекта, права и път за възстановяване.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Измери реалната система","content":{"question":"Кое показва дали дискът стига за монтаж?","options":[{"id":"a","label":"Тест с истинските файлове, окончателния порт и проекта на работната станция."},{"id":"b","label":"Кратко копиране на един малък файл."},{"id":"c","label":"Само стойността върху кутията."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Най-слабата връзка в кабел/порт/мрежа/носител ограничава потока.\n\nВариантът „Само стойността върху кутията.“ не доказва: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Вариантът „Кратко копиране на един малък файл.“ оставя нерешено: Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп. Безопасната корекция е: Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Екипът чака preview","content":{"prompt":"NAS е бавен само когато двама редактори монтират. Какво проверяваш?","options":[{"id":"a","label":"Купуваш по-голям капацитет, без измерване."},{"id":"b","label":"Прехвърляш целия архив в облак веднага."},{"id":"c","label":"Едновременната мрежа, дисковата натовареност и реалния workflow от всяка станция."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Капацитетът и скоростта са различни; измери тесния участък при паралелна работа.\n\nВариантът „Купуваш по-голям капацитет, без измерване.“ не доказва: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Вариантът „Прехвърляш целия архив в облак веднага.“ оставя нерешено: Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп. Безопасната корекция е: Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Облакът като част от системата","content":{"question":"Какво трябва да влезе в сметката за cloud transfer?","options":[{"id":"a","label":"Само дали клиентът може да отвори линк."},{"id":"b","label":"Само месечната цена на абонамента."},{"id":"c","label":"Upload/download време, права, версии, наличност и възстановяване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Пътят до медията и достъпът трябва да са предвидими.\n\nВариантът „Само месечната цена на абонамента.“ не доказва: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Вариантът „Само дали клиентът може да отвори линк.“ оставя нерешено: Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп. Безопасната корекция е: Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Няма интернет на локацията","content":{"prompt":"Екипът трябва да предаде копие от място без връзка. Какво подготвяш?","options":[{"id":"a","label":"Проверени локални копия на отделни носители и синхронизация към облак по-късно."},{"id":"b","label":"Единствена папка в облака, която не е изтеглена."},{"id":"c","label":"Свързваш телефон hotspot по време на целия трансфер без тест."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Подготви офлайн маршрут и не превръщай връзката в единична точка на отказ.\n\nВариантът „Единствена папка в облака, която не е изтеглена.“ не доказва: Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване. Вариантът „Свързваш телефон hotspot по време на целия трансфер без тест.“ оставя нерешено: Екипът избира по рекламно число на диска и не проверява кабела, мрежата, работния софтуер или едновременния достъп. Безопасната корекция е: Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Симулирай прекъсване, липса на интернет и пълен диск."},{"id":"s1","text":"Определи дали системата ще служи за активен монтаж, екипна медия, обмен или архив."},{"id":"s2","text":"Провери codec, размери и колко души ще четат/пишат едновременно."},{"id":"s3","text":"Тествай истински файлове през окончателния кабел/порт/мрежа."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи дали системата ще служи за активен монтаж, екипна медия, обмен или архив.\n2. Провери codec, размери и колко души ще четат/пишат едновременно.\n3. Тествай истински файлове през окончателния кабел/порт/мрежа.\n4. Симулирай прекъсване, липса на интернет и пълен диск."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще избереш място за монтаж, обмен и архив по реална скорост, капацитет, достъп и възстановяване.","Сравни измервания с реални файлове и различни роли; пази backup отделно от media working volume.","Решението посочва роля, реална измерена скорост, брой едновременни потребители, достъп и резерв при прекъсване."],"nextStep":"Измери едно и също копиране на локален SSD, мрежово място и облак. Запиши време, стабилност, отваряне на проекта, права и път за възстановяване."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-12","title":"Архив, който може да се възстанови: срок, носител и тест","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще затвориш проект след доставка така, че бъдещ колега да може да намери, отвори и възстанови нужните файлове.","hook":"Клиентът иска поправка след осем месеца; дискът пази видео, но липсват шрифтове, проектни връзки и версия на графиките.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще затвориш проект след доставка така, че бъдещ колега да може да намери, отвори и възстанови нужните файлове."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Клиентът иска поправка след осем месеца; дискът пази видео, но липсват шрифтове, проектни връзки и версия на графиките."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Архивът не е купчина стари exports. Той съдържа точно договореното: финален файл, проект, нужни медии или proxy, readme, лиценз/права и версия. Не всяка поръчка изисква да пазиш всеки дубъл завинаги. Съгласувай срока, кой има достъп, формата и начина за изтриване.\n\nИзбери носител и местоположение с оглед на срок, поддръжка и възможност да се прочете отново. Пази критичните файлове в отворени или широко поддържани формати, когато договорът го позволява. Периодично възстановявай sample проект, защото стар софтуер, липсващ шрифт или повреда прави архивната папка неполезна."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Архивният manifest изброява версия на проекта, plugin/font dependencies, настройки на таймлайн и export, контролна сума, местоположение, дата на проверка и срок за изтриване. Тествай един sample clip и един project file от студен архив. Ако проектът е зависим от платен plugin, включи бележка и предвиди неутрален финален export."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Свери договора: какво се пази, срок, права и задължение за изтриване.\n2. Събери финален файл, проект, нужни media и dependencies в архивния пакет.\n3. Направи manifest с версия, технически настройки, пътища, checksums и дата.\n4. Провери целостта на пакета и копията, после премахни ненужни render/cache.\n5. Проведи restore test на отделно устройство или чиста тестова папка.\n6. Назначи календарна проверка и сигурно изтриване в края на срока."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Фрилансър архивира рекламен клип с проект, използвани оригинали, шрифт с лиценз и readme. След шест месеца друг монтажист отваря проекта на чиста машина, relink-ва клиповете и вижда кой export е приет.\n\nКритерий за добър ход: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок."},"after":{"label":"Как го поправяш","text":"Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Архивирай малък монтажен проект. Дай копието на колега без допълнителни инструкции и наблюдавай дали може да намери зависимостите и да възпроизведе финала.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Събери финален файл, проект, нужни media и dependencies в архивния пакет. Провери целостта на пакета и копията, после премахни ненужни render/cache.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок.\n\nТестът е минал едва когато: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Фрилансър архивира рекламен клип с проект, използвани оригинали, шрифт с лиценз и readme. След шест месеца друг монтажист отваря проекта на чиста машина, relink-ва клиповете и вижда кой export е приет.\n\nДоставката ти е: Архивирай малък монтажен проект. Дай копието на колега без допълнителни инструкции и наблюдавай дали може да намери зависимостите и да възпроизведе финала.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Архивирай за бъдеща работа","content":{"question":"Кое прави архива повторно използваем?","options":[{"id":"a","label":"Само export с име final."},{"id":"b","label":"Всички временни cache файлове без обяснение."},{"id":"c","label":"Проектът, необходимите медии/зависимости, readme, одобрен export и проверка за възстановяване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Архивът трябва да помогне за проверка и ремонт, а не само да заема място.\n\nВариантът „Само export с име final.“ не доказва: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Вариантът „Всички временни cache файлове без обяснение.“ оставя нерешено: В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок. Безопасната корекция е: Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Липсващ шрифт","content":{"prompt":"След месеци проектът няма шрифта от титъра. Какво трябваше да съдържа пакетът?","options":[{"id":"a","label":"Копие от всички cache папки."},{"id":"b","label":"Само screenshot на титъра."},{"id":"c","label":"Лицензирания dependency или уточнение за него, плюс финален export и алтернатива според правата."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Записвай зависимостите и лиценза, не само пикселите в timeline.\n\nВариантът „Само screenshot на титъра.“ не доказва: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Вариантът „Копие от всички cache папки.“ оставя нерешено: В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок. Безопасната корекция е: Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Определи срок","content":{"question":"Кой определя дали да се пазят всички сурови дубли?","options":[{"id":"a","label":"Договорът, правата, нуждата от повторни версии и срокът за задържане."},{"id":"b","label":"Свободното място на редактора."},{"id":"c","label":"Автоматичната настройка на камерата."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Съхранението е работно и договорно решение; не пази чувствителен материал без срок.\n\nВариантът „Свободното място на редактора.“ не доказва: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Вариантът „Автоматичната настройка на камерата.“ оставя нерешено: В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок. Безопасната корекция е: Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Архивът не се отваря","content":{"prompt":"Restore test показва, че носителят е четим, но проектът липсва медия. Какво правиш?","options":[{"id":"a","label":"Маркираш архива като успешен, защото MP4 се отваря."},{"id":"b","label":"Поправяш manifest и пакетираш необходимите източници, след което повтаряш тест на чисто място."},{"id":"c","label":"Изтриваш проекта и пазиш само cache."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери конкретно обещания пакет, не само наличието на един export.\n\nВариантът „Маркираш архива като успешен, защото MP4 се отваря.“ не доказва: Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място. Вариантът „Изтриваш проекта и пазиш само cache.“ оставя нерешено: В архива остава само MP4 или, обратно, целият scratch/cache без readme и без срок. Безопасната корекция е: Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Провери целостта на пакета и копията, после премахни ненужни render/cache."},{"id":"s3","text":"Направи manifest с версия, технически настройки, пътища, checksums и дата."},{"id":"s2","text":"Събери финален файл, проект, нужни media и dependencies в архивния пакет."},{"id":"s1","text":"Свери договора: какво се пази, срок, права и задължение за изтриване."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Свери договора: какво се пази, срок, права и задължение за изтриване.\n2. Събери финален файл, проект, нужни media и dependencies в архивния пакет.\n3. Направи manifest с версия, технически настройки, пътища, checksums и дата.\n4. Провери целостта на пакета и копията, после премахни ненужни render/cache."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще затвориш проект след доставка така, че бъдещ колега да може да намери, отвори и възстанови нужните файлове.","Пази минималния възстановим пакет, тествай го и изтрий ненужното по договорения срок.","Пакетът има readme, одобрен export, нужни зависимости, проверени копия и срок/отговорник; тестът се повтаря на чисто място."],"nextStep":"Архивирай малък монтажен проект. Дай копието на колега без допълнителни инструкции и наблюдавай дали може да намери зависимостите и да възпроизведе финала."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-13","title":"Старите проекти в хаоса: инвентаризирай, после мести","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще подредиш съществуващ архив, без да изтриеш оригинал или да счупиш отворен проект.","hook":"Дискът е почти пълен; в папката Final има три едноименни проекта, а някой предлага да изтрие дубликатите на око.","estimated_minutes":39,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подредиш съществуващ архив, без да изтриеш оригинал или да счупиш отворен проект."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Дискът е почти пълен; в папката Final има три едноименни проекта, а някой предлага да изтрие дубликатите на око."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Първо правиш инвентар, после преместване. Спри проекти, които са отворени, и отдели от тях оригиналите. Запиши размер, дата, име, клиент и къде се използва; еднакво име не доказва еднакви съдържание и версия. За дубликати сравнявай checksum или използвай инструмент с ясно представяне на конфликт.\n\nПреди да триеш или сливаш, направи backup на архива и тествай restore. Класифицирай папки като активен проект, приключен, unknown, дублиран или ограничен от права. Подозрителни или несъответстващи файлове отиват в карантина с ограничен достъп, не в кошчето."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Премествай по проект, а не целия диск наведнъж. Обнови project path/manifest, relink-ни копие и помоли собственик да потвърди. Остави log с предишно и ново място. Не отваряй непознати изпълними файлове от архив и не качвай клиентски данни в публичен анализатор."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Създай read-only snapshot или резервно копие преди реорганизация.\n2. Изведи inventory по име, размер, дата, проект и отговорник.\n3. Отбележи активни, приключени, неизвестни, чувствителни и съвпадащи файлове.\n4. Провери потенциални дубликати чрез checksum/съдържание, не само по име.\n5. Премести малък batch в целевата структура и провери project relink.\n6. Запиши промяната, собственика и повторния restore test преди освобождаване на място."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Предаване на външен монтажист открива две папки с почти еднакво име. Инвентарът показва, че едната съдържа последен кадър от клиентско одобрение. Екипът я преименува с версия, update-ва проекта и пази checksum отчета.\n\nКритерий за добър ход: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките."},"after":{"label":"Как го поправяш","text":"Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Вземи учебна папка с дублирани и липсващи файлове. Направи inventory, посочи кои са сигурни дубликати и премести само един проект, после отвори проекта от новото място.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Изведи inventory по име, размер, дата, проект и отговорник. Провери потенциални дубликати чрез checksum/съдържание, не само по име.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение.\n\nТестът е минал едва когато: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Предаване на външен монтажист открива две папки с почти еднакво име. Инвентарът показва, че едната съдържа последен кадър от клиентско одобрение. Екипът я преименува с версия, update-ва проекта и пази checksum отчета.\n\nДоставката ти е: Вземи учебна папка с дублирани и липсващи файлове. Направи inventory, посочи кои са сигурни дубликати и премести само един проект, после отвори проекта от новото място.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Преди да местиш","content":{"question":"Кое е първото действие при хаотичен архив?","options":[{"id":"a","label":"Изтрий файлове с еднакво име."},{"id":"b","label":"Преименувай всички папки по дата."},{"id":"c","label":"Направи проверимо snapshot/backup и инвентаризирай съдържанието."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Необратимо действие идва след инвентар и възстановимо копие.\n\nВариантът „Преименувай всички папки по дата.“ не доказва: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Вариантът „Изтрий файлове с еднакво име.“ оставя нерешено: Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките. Безопасната корекция е: Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Еднакви имена","content":{"prompt":"Два файла имат едно име, но различен размер. Какво правиш?","options":[{"id":"a","label":"Сравняваш content/checksum и произход, после запазваш правилната версия с отчет."},{"id":"b","label":"Оставяш по-новия по дата и изтриваш другия."},{"id":"c","label":"Качваш и двата в публичен cloud detector."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Име и дата не доказват съдържание; пази клиентските файлове в разрешена среда.\n\nВариантът „Оставяш по-новия по дата и изтриваш другия.“ не доказва: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Вариантът „Качваш и двата в публичен cloud detector.“ оставя нерешено: Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките. Безопасната корекция е: Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери проекта след преместване","content":{"question":"Какво доказва, че project path е запазен?","options":[{"id":"a","label":"Папката се появи в новата директория."},{"id":"b","label":"Отваряш копие от новото място и сверяваш медията, таймлайн и export."},{"id":"c","label":"Името на файла се промени успешно."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Преместването е готово само когато проектът и източниците се намират.\n\nВариантът „Папката се появи в новата директория.“ не доказва: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Вариантът „Името на файла се промени успешно.“ оставя нерешено: Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките. Безопасната корекция е: Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Неизвестен собственик","content":{"prompt":"Намерена е папка с клиентски кадри и няма отговорник. Какво правиш?","options":[{"id":"a","label":"Изтриваш я, защото никой не я е поискал."},{"id":"b","label":"Маркираш я като unknown, ограничаваш достъпа и търсиш собственик преди местене или изтриване."},{"id":"c","label":"Преместваш я към общия архив без лог."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Неопределеният собственик означава пауза и проследяване, не свободно разпореждане.\n\nВариантът „Преместваш я към общия архив без лог.“ не доказва: Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore. Вариантът „Изтриваш я, защото никой не я е поискал.“ оставя нерешено: Групово преименуване и изтриване се правят само по дата/име, без snapshot и проверка на връзките. Безопасната корекция е: Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Изведи inventory по име, размер, дата, проект и отговорник."},{"id":"s3","text":"Отбележи активни, приключени, неизвестни, чувствителни и съвпадащи файлове."},{"id":"s4","text":"Провери потенциални дубликати чрез checksum/съдържание, не само по име."},{"id":"s1","text":"Създай read-only snapshot или резервно копие преди реорганизация."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Създай read-only snapshot или резервно копие преди реорганизация.\n2. Изведи inventory по име, размер, дата, проект и отговорник.\n3. Отбележи активни, приключени, неизвестни, чувствителни и съвпадащи файлове.\n4. Провери потенциални дубликати чрез checksum/съдържание, не само по име."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще подредиш съществуващ архив, без да изтриеш оригинал или да счупиш отворен проект.","Класифицирай и валидирай малки партиди; пази предишния път и backup до потвърждение.","Има инвентар, запазен стар път, одобрен нов път и няма изтрит файл без потвърждение и работещ restore."],"nextStep":"Вземи учебна папка с дублирани и липсващи файлове. Направи inventory, посочи кои са сигурни дубликати и премести само един проект, после отвори проекта от новото място."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-14","title":"Екипен достъп: сподели медията, не заключи проекта","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще организираш споделен проект така, че хората да знаят кой редактира, как се стига до media и кой одобрява.","hook":"Двама редактори презаписват един проект; друг колега отваря облачно копие, чиито пътища не работят на неговия компютър.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще организираш споделен проект така, че хората да знаят кой редактира, как се стига до media и кой одобрява."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Двама редактори презаписват един проект; друг колега отваря облачно копие, чиито пътища не работят на неговия компютър."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Екипната работа изисква правила за собственост, версия и пътища. Дай достъп само на хората, които го ползват; отдели клиентски review линк от вътрешната папка с оригиналите. Не редактирай един shared project файл едновременно, освен ако софтуерът има поддържан multi-user/lock workflow и екипът го е тествал.\n\nОпредели кое е единственият master, кой го заключва, как се предават промени и къде са медийните активи. Права се отнемат при край на договора. Не изпращай public link към сурови клиентски кадри като удобен handoff."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Adobe Productions организира работата с няколко проекта и общи активи; други системи имат различни ограничения. Провери текущото поведение в избрания софтуер: locking, конфликт, офлайн достъп, версии и relink. Направи проба с два тестови акаунта; не приемай, че облачният sync разрешава конфликт автоматично."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Назначи собственик на master проекта, редактор за всяка част и одобрител.\n2. Избери споделено място за media и тестирай пътя на всяка станция.\n3. Дай минимален достъп; направи отделен линк с read-only review за клиента.\n4. Установи lock/checkout/версиониране според програмата.\n5. Синхронизирай файл, отвори го на втори акаунт и реши test conflict.\n6. При handoff отнеми излишни права и запиши кой носи следващата задача."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Видео поръчка се дели между монтажист и колорист. Монтажистът предава picture lock с версия и manifest; колористът връща отделен проект и exports, без да записва върху master. Клиентът вижда само review линка с ограничен срок.\n\nКритерий за добър ход: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка."},"after":{"label":"Как го поправяш","text":"Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай тестов проект с два акаунта или две локални копия. Симулирай паралелна промяна, офлайн редакция и конфликт; напиши как се връща към master.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Избери споделено място за media и тестирай пътя на всяка станция. Установи lock/checkout/версиониране според програмата.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали.\n\nТестът е минал едва когато: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Видео поръчка се дели между монтажист и колорист. Монтажистът предава picture lock с версия и manifest; колористът връща отделен проект и exports, без да записва върху master. Клиентът вижда само review линка с ограничен срок.\n\nДоставката ти е: Създай тестов проект с два акаунта или две локални копия. Симулирай паралелна промяна, офлайн редакция и конфликт; напиши как се връща към master.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe обяснява предназначението на Productions за управление на много проекти и споделени активи: https://helpx.adobe.com/premiere/desktop/collaborate-with-others/collaborate-using-productions/about-productions.html"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Един master","content":{"question":"Как се избягва конфликт при споделен проектен файл?","options":[{"id":"a","label":"Определяш собственик и lock/checkout правило или използваш тествана multi-user функция."},{"id":"b","label":"Всички записват едновременно; sync ще избере правилния."},{"id":"c","label":"Наричаш всеки проект final-copy."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Облачната папка сама по себе си не решава конфликт между редактори.\n\nВариантът „Всички записват едновременно; sync ще избере правилния.“ не доказва: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Вариантът „Наричаш всеки проект final-copy.“ оставя нерешено: Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка. Безопасната корекция е: Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Клиентът вижда originals","content":{"prompt":"Review линкът отваря цялата папка с оригинали. Как реагираш?","options":[{"id":"a","label":"Оставяш го, ако линкът е труден за отгатване."},{"id":"b","label":"Спираш споделянето и създаваш отделен ограничен review линк към конкретния export."},{"id":"c","label":"Изпращаш паролата в същото съобщение."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Сподели само нужния файл и отнеми излишния достъп.\n\nВариантът „Оставяш го, ако линкът е труден за отгатване.“ не доказва: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Вариантът „Изпращаш паролата в същото съобщение.“ оставя нерешено: Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка. Безопасната корекция е: Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Пътят към медията","content":{"question":"Какво трябва да тестваш преди екипната работа?","options":[{"id":"a","label":"Само размерът на общото хранилище."},{"id":"b","label":"Проектът се отваря от всяка станция, media path е работещ и има правило за конфликт/версии."},{"id":"c","label":"Само дали всички са поканени в услугата."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Достъпът и наличното място не доказват, че редакторът може да намери медията.\n\nВариантът „Само дали всички са поканени в услугата.“ не доказва: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Вариантът „Само размерът на общото хранилище.“ оставя нерешено: Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка. Безопасната корекция е: Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Редактор напуска проекта","content":{"prompt":"Външен монтажист приключва работа. Кой екипен ход е нужен?","options":[{"id":"a","label":"Отнемаш излишния достъп и прехвърляш собствеността/следващото действие по записан handoff."},{"id":"b","label":"Изтриваш проекта, за да затвориш задачата."},{"id":"c","label":"Оставяш акаунта за всеки случай."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Затварянето включва достъп, отговорност и запазване на нужния материал.\n\nВариантът „Оставяш акаунта за всеки случай.“ не доказва: Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт. Вариантът „Изтриваш проекта, за да затвориш задачата.“ оставя нерешено: Всеки има редакторски достъп до едно и също project file, а review линкът отваря цялата папка. Безопасната корекция е: Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Избери споделено място за media и тестирай пътя на всяка станция."},{"id":"s1","text":"Назначи собственик на master проекта, редактор за всяка част и одобрител."},{"id":"s4","text":"Установи lock/checkout/версиониране според програмата."},{"id":"s3","text":"Дай минимален достъп; направи отделен линк с read-only review за клиента."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Назначи собственик на master проекта, редактор за всяка част и одобрител.\n2. Избери споделено място за media и тестирай пътя на всяка станция.\n3. Дай минимален достъп; направи отделен линк с read-only review за клиента.\n4. Установи lock/checkout/версиониране според програмата."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще организираш споделен проект така, че хората да знаят кой редактира, как се стига до media и кой одобрява.","Определи master owner, работен handoff и отдели достъп за клиентски преглед от вътрешните оригинали.","Екипът знае кой редактира master, къде са медията, кой има review достъп и как се решава конфликт."],"nextStep":"Създай тестов проект с два акаунта или две локални копия. Симулирай паралелна промяна, офлайн редакция и конфликт; напиши как се връща към master."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-15","title":"Проведи batch ден: изпълни, отбелязвай, коригирай","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще водиш снимачната партида по график и ще засечеш рано отклоненията, вместо да ги откриеш след деня.","hook":"Първите клипове са заснети, но никой не записва дублите и едва след час екипът разбира, че микрофонът не е включен.","estimated_minutes":45,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще водиш снимачната партида по график и ще засечеш рано отклоненията, вместо да ги откриеш след деня."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Първите клипове са заснети, но никой не записва дублите и едва след час екипът разбира, че микрофонът не е включен."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Batch денят е оперативен процес: go/no-go check, ясно табло, собственик за всеки сет, статус на дубълите и контрол при смяна. Проверявай първия кадър на всяка нова конфигурация, преди да снимаш цяла серия. Между блоковете свери списъка, не разчитай на памет.\n\nАко екипът изостава, спри и обнови обхвата. Не режи почивка, тест или копие без съгласуване. Запиши отклонение и причината; следващият batch план трябва да използва реалните данни, не желаното темпо.\n\nДопълнителен ход от практиката: По време на batch деня следи плана спрямо реалния старт, пренареждането и липсващите дубъли. При отклонение запиши какво се мести, кой е уведомен и кои доставки са под риск; не мълчи, докато графикът се срути. Постави checkpoints за храна, вода, карта и backup; умореният оператор по-често пропуска фокус и именуване. В края на всеки блок съгласувай заснетите кадри със shot list и маркирай остатъка като заснето, отказано или за повторение."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Go/no-go включва човек и права готови, карта/място, батареи, звук, светлина, бриф и безопасна локация. Един човек следи slate/shot log. На всяка смяна прегледай дубъл, статус, имя файла, оригинален текст и напредък. Назначи комуникационен канал при забавяне."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Направи кратък go/no-go чеклист и провери всеки сет преди първи дубъл.\n2. Назначи оператор, звук, лог и отговорник за одобрение.\n3. Започни с тест, прослушай и огледай файла; заключи правилната конфигурация.\n4. След всеки блок обнови shot log, дубъл, проблем и оставащо време.\n5. При отклонение преоцени критичните доставки и съгласувай промяна.\n6. В края провери материал, копия, статуса и действителния капацитет."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Екип снима 10 демонстрационни видеа за кухня. Shot log показва, че клип 4 има един добър дубъл, а клип 5 чака повторение. При смяна към втората камера тестът открива неправилен кадър в секунда, преди серията да е заснета.\n\nКритерий за добър ход: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Таблото показва само „снимано“, без дубъл, QC или отворена задача."},"after":{"label":"Как го поправяш","text":"Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Проведи симулация на batch ден с шест клипа. Вмъкни един отказ на микрофон и едно закъснение; обнови графика и shot log.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Таблото показва само „снимано“, без дубъл, QC или отворена задача.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Назначи оператор, звук, лог и отговорник за одобрение. След всеки блок обнови shot log, дубъл, проблем и оставащо време.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход.\n\nТестът е минал едва когато: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Екип снима 10 демонстрационни видеа за кухня. Shot log показва, че клип 4 има един добър дубъл, а клип 5 чака повторение. При смяна към втората камера тестът открива неправилен кадър в секунда, преди серията да е заснета.\n\nДоставката ти е: Проведи симулация на batch ден с шест клипа. Вмъкни един отказ на микрофон и едно закъснение; обнови графика и shot log.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Първо test кадър","content":{"question":"Кога тестваш нов сет или камера режим?","options":[{"id":"a","label":"След като приключи последният клип."},{"id":"b","label":"Преди да заснемеш цялата партида в тази конфигурация."},{"id":"c","label":"Само ако клиентът поиска да чуе звук."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Първият тест може да хване грешка, преди тя да се размножи в серията.\n\nВариантът „След като приключи последният клип.“ не доказва: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Вариантът „Само ако клиентът поиска да чуе звук.“ оставя нерешено: Таблото показва само „снимано“, без дубъл, QC или отворена задача. Безопасната корекция е: Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Микрофонът е изключен","content":{"prompt":"Shot log показва, че първите два клипа са без външен микрофон. Какво правиш?","options":[{"id":"a","label":"Изтриваш първите клипове, за да не се виждат."},{"id":"b","label":"Спираш серията, проверяваш дали има резервен звук и повтаряш клиповете, докато сетът е готов."},{"id":"c","label":"Продължаваш и ще надпишеш всичко после."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери покритието и информирай екипа; не прикривай дефект.\n\nВариантът „Продължаваш и ще надпишеш всичко после.“ не доказва: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Вариантът „Изтриваш първите клипове, за да не се виждат.“ оставя нерешено: Таблото показва само „снимано“, без дубъл, QC или отворена задача. Безопасната корекция е: Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Статус, който помага","content":{"question":"Кое е най-полезно в shot log?","options":[{"id":"a","label":"Дубъл, техническа проверка, проблем, оставащо действие и отговорник."},{"id":"b","label":"Само тема от сценария."},{"id":"c","label":"Само отметка „снимано“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Статусът трябва да казва какво следва и кой го поема.\n\nВариантът „Само отметка „снимано“.“ не доказва: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Вариантът „Само тема от сценария.“ оставя нерешено: Таблото показва само „снимано“, без дубъл, QC или отворена задача. Безопасната корекция е: Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Изоставане от графика","content":{"prompt":"Екипът е с час назад преди последните три клипа. Какво правиш?","options":[{"id":"a","label":"Махаш тестовете и копирането, за да запазиш план."},{"id":"b","label":"Ускоряваш говорещия и не казваш на клиента."},{"id":"c","label":"Преоценяваш критичните доставки, обявяваш промяна и пазиш QA/почивките."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Коригирай плана видимо; не прехвърляй скрит риск към монтажиста.\n\nВариантът „Махаш тестовете и копирането, за да запазиш план.“ не доказва: Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип. Вариантът „Ускоряваш говорещия и не казваш на клиента.“ оставя нерешено: Таблото показва само „снимано“, без дубъл, QC или отворена задача. Безопасната корекция е: Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"След всеки блок обнови shot log, дубъл, проблем и оставащо време."},{"id":"s1","text":"Направи кратък go/no-go чеклист и провери всеки сет преди първи дубъл."},{"id":"s2","text":"Назначи оператор, звук, лог и отговорник за одобрение."},{"id":"s3","text":"Започни с тест, прослушай и огледай файла; заключи правилната конфигурация."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Направи кратък go/no-go чеклист и провери всеки сет преди първи дубъл.\n2. Назначи оператор, звук, лог и отговорник за одобрение.\n3. Започни с тест, прослушай и огледай файла; заключи правилната конфигурация.\n4. След всеки блок обнови shot log, дубъл, проблем и оставащо време."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще водиш снимачната партида по график и ще засечеш рано отклоненията, вместо да ги откриеш след деня.","Раздели статуси: планирано, тест, заснето, проверено, pickup, копирано; записвай собственик и следващ ход.","Проблемът е открит преди да засегне серията; приетите клипове, pickup-и и копията са видими за целия екип."],"nextStep":"Проведи симулация на batch ден с шест клипа. Вмъкни един отказ на микрофон и едно закъснение; обнови графика и shot log."},"points":1,"required":true}]},{"module_id":"s02-m08","lesson_id":"pv08-16","title":"SOP за екипа: един процес, който нов колега може да повтори","subtitle":"Модул 08 · Пакетно производство и безопасна работа с медия","objective":"Ще опишеш производствения процес така, че следващ колега да го изпълни и да знае кога да спре и да поиска решение.","hook":"Системата работи само докато авторът е на работа; при отпуск никой не знае кой одобрява, копира или сменя статуса.","estimated_minutes":44,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще опишеш производствения процес така, че следващ колега да го изпълни и да знае кога да спре и да поиска решение."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Системата работи само докато авторът е на работа; при отпуск никой не знае кой одобрява, копира или сменя статуса."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Стандартна процедура не е роман. Тя показва тригера, owner, входове, стъпки, критерий за готовност, stop condition и къде се записва доказателство. Добави един пример за нормален случай и един за отказ. Ако процедурата не може да се изпълни без автора, има скрито знание, което трябва да се изнесе в карту/образец.\n\nВерсията SOP има собственик и дата. Обновявай я след реален проблем, нов инструмент или изменение в клиентския процес. Не разчитай на screenshots от стар интерфейс като единствен източник; впиши какво се проверява дори ако менюто се премести."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Пиши с действен глагол и видим резултат: „отвори проверения export и виж дали…“, а не „увери се, че е хубав“. За поверителни задачи посочи къде не се качва материал. Дай нов колега да изпълни процедурата без устно подсказване; всеки въпрос е сигнал за редакция."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи процес и момент, в който той започва и приключва.\n2. Назначи owner и заместник; изброй необходими входове.\n3. Опиши стъпките с проверки и резултат след всяка важна операция.\n4. Добави stop condition при грешен файл, права, звук, липсващ approval или backup.\n5. Посочи лог, шаблон и източник на актуални правила.\n6. Дай на нов човек да повтори процеса; редактирай по реалните затруднения."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Нов редактор получава задача за клип. SOP показва къде са брифът, одобреният сценарий, proxy и master; дава правила за име и проверка на export. Редакторът спира, когато открие неподкрепено твърдение, и знае на кого да го върне.\n\nКритерий за добър ход: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition."},"after":{"label":"Как го поправяш","text":"Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши кратка SOP за ingest, монтажен handoff или архив. Дай я на колега, който не е участвал в създаването, и отбележи всяко място, където му се налага да пита.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Назначи owner и заместник; изброй необходими входове. Добави stop condition при грешен файл, права, звук, липсващ approval или backup.\n\nПовтори процеса с един обичаен материал и един граничен случай: закъснял файл, сменен оператор или недостъпен носител. Запиши кой подхваща работата, къде намира последната версия и как разбира, че нищо не е презаписано. Ако процесът работи само когато авторът е на място, той още не е екипен процес.\n\nКоригирай с този ход: Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа.\n\nТестът е минал едва когато: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Нов редактор получава задача за клип. SOP показва къде са брифът, одобреният сценарий, proxy и master; дава правила за име и проверка на export. Редакторът спира, когато открие неподкрепено твърдение, и знае на кого да го върне.\n\nДоставката ти е: Напиши кратка SOP за ingest, монтажен handoff или архив. Дай я на колега, който не е участвал в създаването, и отбележи всяко място, където му се налага да пита.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи името и местоположението на файла, собственика на следващото действие, версията, контролния запис и начина за възстановяване. Колега, който не е участвал, трябва да намери нужното без личен чат с автора.\n\nПриемане: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"field_note_1","block_type":"rich_text","title":"Преглед на процедурата","content":{"body":"На месечен преглед провери дали имената, инструментите, ролите и правата още са актуални. Отбележи версия и собственик."},"points":1,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Състав на SOP","content":{"question":"Кое прави кратката процедура приложима?","options":[{"id":"a","label":"Само списък с менюта на една версия на софтуера."},{"id":"b","label":"Тригер, owner, входове, стъпки, критерий, stop condition и място за доказателство."},{"id":"c","label":"Дълго описание на идеалния случай."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Процедурата трябва да помага и при отклонение, не само при идеални условия.\n\nВариантът „Дълго описание на идеалния случай.“ не доказва: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Вариантът „Само списък с менюта на една версия на софтуера.“ оставя нерешено: Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition. Безопасната корекция е: Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Неподкрепено твърдение","content":{"prompt":"SOP казва да публикуваш, но продуктова характеристика няма източник. Как действаш?","options":[{"id":"a","label":"Спираш публикацията и връщаш твърдението към owner за потвърждение."},{"id":"b","label":"Питаш генеративен инструмент да потвърди твърдението."},{"id":"c","label":"Публикуваш, защото процесът те кара да продължиш."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Stop condition има предимство пред автоматичното продължаване; източникът трябва да се провери.\n\nВариантът „Публикуваш, защото процесът те кара да продължиш.“ не доказва: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Вариантът „Питаш генеративен инструмент да потвърди твърдението.“ оставя нерешено: Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition. Безопасната корекция е: Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Тествай SOP с нов човек","content":{"question":"Как разбираш, че инструкцията е достатъчна?","options":[{"id":"a","label":"Авторът я чете и намира за ясна."},{"id":"b","label":"Има много страници и screenshot-и."},{"id":"c","label":"Човек извън автора я изпълнява без устни подсказки и улавя примерния отказ."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Изпълнението от друг човек е реална проверка за скрито знание.\n\nВариантът „Авторът я чете и намира за ясна.“ не доказва: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Вариантът „Има много страници и screenshot-и.“ оставя нерешено: Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition. Безопасната корекция е: Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Софтуерът смени менюто","content":{"prompt":"Интерфейсът е обновен, а SOP има стар screenshot. Какво правиш?","options":[{"id":"a","label":"Добавяш още стари screenshot-и."},{"id":"b","label":"Оставяш я — опитният колега ще се оправи."},{"id":"c","label":"Обновяваш инструкцията по целта и проверяваш стъпките в текущата версия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Поддържай резултата и критериите актуални, не само картинката от менюто.\n\nВариантът „Оставяш я — опитният колега ще се оправи.“ не доказва: Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде. Вариантът „Добавяш още стари screenshot-и.“ оставя нерешено: Процедурата казва само „експортирай финала и качи в папката“, без технически критерии, собственик или stop condition. Безопасната корекция е: Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Добави stop condition при грешен файл, права, звук, липсващ approval или backup."},{"id":"s3","text":"Опиши стъпките с проверки и резултат след всяка важна операция."},{"id":"s2","text":"Назначи owner и заместник; изброй необходими входове."},{"id":"s1","text":"Определи процес и момент, в който той започва и приключва."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи процес и момент, в който той започва и приключва.\n2. Назначи owner и заместник; изброй необходими входове.\n3. Опиши стъпките с проверки и резултат след всяка важна операция.\n4. Добави stop condition при грешен файл, права, звук, липсващ approval или backup."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще опишеш производствения процес така, че следващ колега да го изпълни и да знае кога да спре и да поиска решение.","Запиши вход, отговорник, действие, проверка, отказ и handoff; валидирай с човек извън екипа.","Нов колега може сам да изпълни нормалния процес, да открие нарочен проблем и да знае на кого да го предаде."],"nextStep":"Напиши кратка SOP за ingest, монтажен handoff или архив. Дай я на колега, който не е участвал в създаването, и отбележи всяко място, където му се налага да пита."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-01","title":"От брифа до предаване: работен ред за монтаж","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще подготвиш монтаж, който друг човек може да отвори, прегледа, поправи и предаде по брифа.","hook":"Клипът изглежда завършен, но таймлайнът е от грешен формат, оригиналите липсват и няма записана версия за клиента.","estimated_minutes":48,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подготвиш монтаж, който друг човек може да отвори, прегледа, поправи и предаде по брифа."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Клипът изглежда завършен, но таймлайнът е от грешен формат, оригиналите липсват и няма записана версия за клиента."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Монтажът започва с бриф, медия и технически изисквания — не с ефекти. Провери ориентация, кадрова честота, дължина, канал, субтитри, аудио, права и име на export. Организирай оригиналите, audio, graphics, project, proxies и output така, че всяка версия да е проследима.\n\nРедактирай на етапи: избор на кадри, rough cut по смисъл, финален ритъм, звук, цвят, графики, QA и предаване. Не коригирай цвят или шум до picture lock без причина, защото ще повториш работа. Експортът не е финал, докато не го отвориш и прегледаш целия файл."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Преди импорт провери дали копието е пълно и дали файловете следват схемата. Направи project settings според брифа и източника; ако се налага преобразуване на честота, тествай движението. Сглоби кратък rough cut, после гледай с аудио, без аудио и на целевото устройство. Запиши решение и версия при всеки handoff."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Потвърди бриф, канал, версия, технически изход, права и одобрител.\n2. Провери папки, име, цялост на медията, frame rate и нужда от proxy.\n3. Създай проект с ясни bins и sequence; пази оригиналите неизменени.\n4. Избери usable takes и сглоби rough cut по целта на клипа.\n5. Финализирай ритъм, звук, корекция, текст и графики в отделни pass-ове.\n6. Експортирай по спецификация, отвори файла, изгледай го и запиши handoff."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Фирма изпраща 40 клипа и иска 30-секундно видео за сайт плюс вертикална версия. Монтажистът първо потвърждава кадри в секунда и формати, после прави rough cut и проверява дали има кадри за двата aspect ratio. Не кропва автоматично целия проект, преди да види лицата и текстовете.\n\nКритерий за добър ход: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа."},"after":{"label":"Как го поправяш","text":"Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи 20-секунден монтаж от 6–10 клипа. Запиши бриф, избор на дубъли, rough/final версии, настройки на sequence и бележка за предаване.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Провери папки, име, цялост на медията, frame rate и нужда от proxy. Избери usable takes и сглоби rough cut по целта на клипа.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш.\n\nТестът е минал едва когато: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Фирма изпраща 40 клипа и иска 30-секундно видео за сайт плюс вертикална версия. Монтажистът първо потвърждава кадри в секунда и формати, после прави rough cut и проверява дали има кадри за двата aspect ratio. Не кропва автоматично целия проект, преди да види лицата и текстовете.\n\nДоставката ти е: Направи 20-секунден монтаж от 6–10 клипа. Запиши бриф, избор на дубъли, rough/final версии, настройки на sequence и бележка за предаване.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"YouTube публикува актуални препоръки за кодиране и кадрова честота; ползвай спецификацията на канала от брифа: https://support.google.com/youtube/answer/1722171"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Преди ефектите","content":{"question":"Кое трябва да изясниш преди да започнеш таймлайна?","options":[{"id":"a","label":"Бриф, източници, формат, кадрова честота, права и кой одобрява версията."},{"id":"b","label":"Само името на песента."},{"id":"c","label":"Пакет преходи и LUT."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Техническите и съдържателните ограничения определят правилния проект.\n\nВариантът „Пакет преходи и LUT.“ не доказва: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Вариантът „Само името на песента.“ оставя нерешено: Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа. Безопасната корекция е: Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Липсва ключова реплика","content":{"prompt":"След музикален монтаж виждаш, че основният отговор липсва. Какво правиш?","options":[{"id":"a","label":"Добавяш още ефекти, за да прикриеш липсата."},{"id":"b","label":"Предаваш клипа без основното послание."},{"id":"c","label":"Връщаш се към брифа и rough cut-а, намираш usable дубъл и пренареждаш историята."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Посланието трябва да работи преди украса.\n\nВариантът „Добавяш още ефекти, за да прикриеш липсата.“ не доказва: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Вариантът „Предаваш клипа без основното послание.“ оставя нерешено: Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа. Безопасната корекция е: Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Версия за предаване","content":{"question":"Кое означава финален export?","options":[{"id":"a","label":"Файлът носи думата final в името."},{"id":"b","label":"Прогресът на export стигна 100%."},{"id":"c","label":"Файлът е по спецификация, отваря се, цял е прегледан и е обозначен с правилна версия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Провери резултата, не само приключването на рендер.\n\nВариантът „Прогресът на export стигна 100%.“ не доказва: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Вариантът „Файлът носи думата final в името.“ оставя нерешено: Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа. Безопасната корекция е: Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Две съотношения","content":{"prompt":"Клиентът иска 16:9 и 9:16, а важен текст е до ръба. Как постъпваш?","options":[{"id":"a","label":"Правиш отделно прекомпозиране и проверяваш текста и лицата във всеки формат."},{"id":"b","label":"Изрязваш автоматично центъра и експортираш двете версии."},{"id":"c","label":"Разтягаш 9:16 до широк формат."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Композицията се проверява в целевия кадър; не деформирай изображението.\n\nВариантът „Изрязваш автоматично центъра и експортираш двете версии.“ не доказва: Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена. Вариантът „Разтягаш 9:16 до широк формат.“ оставя нерешено: Редакторът започва с музикален монтаж и ефекти, а след това открива, че ключовата реплика и форматът са различни от брифа. Безопасната корекция е: Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Провери папки, име, цялост на медията, frame rate и нужда от proxy."},{"id":"s3","text":"Създай проект с ясни bins и sequence; пази оригиналите неизменени."},{"id":"s4","text":"Избери usable takes и сглоби rough cut по целта на клипа."},{"id":"s1","text":"Потвърди бриф, канал, версия, технически изход, права и одобрител."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Потвърди бриф, канал, версия, технически изход, права и одобрител.\n2. Провери папки, име, цялост на медията, frame rate и нужда от proxy.\n3. Създай проект с ясни bins и sequence; пази оригиналите неизменени.\n4. Избери usable takes и сглоби rough cut по целта на клипа."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще подготвиш монтаж, който друг човек може да отвори, прегледа, поправи и предаде по брифа.","Потвърди спецификация, покритие и структура; изгради смислов монтаж, преди да полираш.","Проектът отваря оригиналите, отговаря на формата, export-ът се гледа целия, а нов монтажист разбира коя версия е одобрена."],"nextStep":"Направи 20-секунден монтаж от 6–10 клипа. Запиши бриф, избор на дубъли, rough/final версии, настройки на sequence и бележка за предаване."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-02","title":"Ритъмът на сцената: режи по смисъл, не по таймер","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще редактираш кратък клип така, че всяка пауза, реакция и смяна на кадър да служат на смисъла.","hook":"Монтажът сменя кадър на всеки две секунди, но зрителят не разбира действието и не усеща нито акцент, нито пауза.","estimated_minutes":39,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще редактираш кратък клип така, че всяка пауза, реакция и смяна на кадър да служат на смисъла."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Монтажът сменя кадър на всеки две секунди, но зрителят не разбира действието и не усеща нито акцент, нито пауза."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Ритъмът идва от намерението, съдържанието и реакцията, а не от универсална дължина на кадъра. Режи, когато зрителят е получил нужната информация или когато следващ кадър разкрива нещо ново. Пауза може да показва съмнение, усилие или завършено действие; премахването ѝ може да смени характера на човека.\n\nИзползвай разнообразие в план, гледна точка и действие само когато се чете. Ако сменяш кадъра без промяна в информацията, монтажът изглежда нервен. Гледай първо без музика; после добави музика и провери дали тя не диктува по-бърз ритъм от посланието.\n\nРаботна проверка: Гледай сцената без музика и отбележи къде се сменя намерението: въпрос, отговор, реакция, действие или пауза. После гледай само аудиото, за да чуеш дали дъхът и краят на фразата остават естествени. Сравни две версии на ключовия срез и провери дали зрителят разбира кой говори и защо следващият кадър идва точно тогава. Таймерът дава сигнал за преглед; решението се взема по смисъла на сцената.\n\nДопълнителен ход от практиката: Провери монтажния ритъм с три гледания: само картина, само звук и цялата версия с публика. Отбележи моментите, когато зрителят трябва да разбере детайл, да почувства пауза или да види реакция. Къси кадри не гарантират енергия, а дълъг кадър не е автоматично бавен. Премести среза по едно-две действия и виж дали фразата остава цяла. Ако промяната изисква контекст, покажи двете версии на редактор/клиент с конкретен въпрос, а не „харесва ли ти“."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Маркирай моменти за избор: начало на мисъл, доказателство, реакция, преход и CTA. Остави достатъчно handle около движението. Използвай реакционен кадър, когато той носи смисъл, не за да прикрие лоша реплика. Къси монтажи не изискват всеки кадър да е кратък — при продуктова демонстрация зрителят трябва да види действието."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи едно основно действие или идея на клипа.\n2. Гледай суровия материал и маркирай начало, завършек, пауза и реакция.\n3. Сглоби версия без музика и провери дали историята се разбира.\n4. Махай само повторения и празно време, което не носи намерение.\n5. Добави разнообразен кадър при смислова промяна, не по фиксиран интервал.\n6. Гледай със и без музика и сравни дали музиката не изкривява темпото."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Майстор показва как сменя велосипедна гума. Срезове се поставят между инструмент, движение и резултат; ключовото затягане остава достатъчно дълго да се види. Музиката се добавя тихо и не ускорява кадър преди действието да приключи.\n\nКритерий за добър ход: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът."},"after":{"label":"Как го поправяш","text":"Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи две 20-секундни версии от едни и същи клипове. Едната режи през две секунди, другата по смислови моменти; сравни разбираемостта и усещането.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Гледай суровия материал и маркирай начало, завършек, пауза и реакция. Махай само повторения и празно време, което не носи намерение.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация.\n\nТестът е минал едва когато: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Режи по намерение","content":{"question":"Кога е добра точка за срез?","options":[{"id":"a","label":"След точно две секунди във всеки кадър."},{"id":"b","label":"Всеки път когато музиката има удар."},{"id":"c","label":"Когато зрителят е получил информацията или следващият кадър променя разбирането."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Ритъмът следва информацията и действието, а не само музикалния grid.\n\nВариантът „След точно две секунди във всеки кадър.“ не доказва: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина. Вариантът „Всеки път когато музиката има удар.“ оставя нерешено: Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът. Безопасната корекция е: Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Демонстрацията е нечетлива","content":{"prompt":"Срезът маха стъпката, в която инструментът захваща детайла. Какво правиш?","options":[{"id":"a","label":"Добавяш текст „готово“ върху неясния момент."},{"id":"b","label":"Ускоряваш още повече за динамика."},{"id":"c","label":"Връщаш нужното време или добавяш близък кадър, за да се види причинно действие."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Монтажът трябва да позволи на зрителя да разбере физическото действие.\n\nВариантът „Ускоряваш още повече за динамика.“ не доказва: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина. Вариантът „Добавяш текст „готово“ върху неясния момент.“ оставя нерешено: Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът. Безопасната корекция е: Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Пази смислова пауза","content":{"question":"Кога кратка пауза трябва да остане?","options":[{"id":"a","label":"Когато показва реакция, дишане, колебание или завършване на мисълта."},{"id":"b","label":"Никога; паузите са празно време."},{"id":"c","label":"Само ако има музикален акцент."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Пауза може да носи характер или смисъл.\n\nВариантът „Никога; паузите са празно време.“ не доказва: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина. Вариантът „Само ако има музикален акцент.“ оставя нерешено: Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът. Безопасната корекция е: Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Музиката натиска","content":{"prompt":"Музиката кара клипа да изглежда прибързан, а демонстрацията не се разбира. Какво правиш?","options":[{"id":"a","label":"Ускоряваш кадрите, за да съвпаднат с бийта."},{"id":"b","label":"Преизграждаш ритъма по действието и избираш музика, която го подкрепя."},{"id":"c","label":"Оставяш визуалното объркване, защото песента е популярна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Първо ясна история; музиката следва, не заменя редакторското решение.\n\nВариантът „Ускоряваш кадрите, за да съвпаднат с бийта.“ не доказва: Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина. Вариантът „Оставяш визуалното объркване, защото песента е популярна.“ оставя нерешено: Всички паузи се изтриват и кадърът се сменя на равен интервал, без да се гледа смисълът. Безопасната корекция е: Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Гледай суровия материал и маркирай начало, завършек, пауза и реакция."},{"id":"s1","text":"Определи едно основно действие или идея на клипа."},{"id":"s4","text":"Махай само повторения и празно време, което не носи намерение."},{"id":"s3","text":"Сглоби версия без музика и провери дали историята се разбира."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи едно основно действие или идея на клипа.\n2. Гледай суровия материал и маркирай начало, завършек, пауза и реакция.\n3. Сглоби версия без музика и провери дали историята се разбира.\n4. Махай само повторения и празно време, което не носи намерение."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще редактираш кратък клип така, че всяка пауза, реакция и смяна на кадър да служат на смисъла.","Изрежи по свършена мисъл или видимо действие; провери дали новият кадър носи допълнителна информация.","Зрителят може да опише действието след едно гледане; нито пауза, нито важна стъпка е премахната без причина."],"nextStep":"Направи две 20-секундни версии от едни и същи клипове. Едната режи през две секунди, другата по смислови моменти; сравни разбираемостта и усещането."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-04","title":"Текст и субтитри, които не закриват картината","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще поставиш точни, четими надписи и субтитри в кадър, който е проверен на целевото устройство.","hook":"Надписът е граматически верен, но закрива продукта; автоматичният транскрипт е сбъркал името на клиента.","estimated_minutes":41,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще поставиш точни, четими надписи и субтитри в кадър, който е проверен на целевото устройство."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Надписът е граматически верен, но закрива продукта; автоматичният транскрипт е сбъркал името на клиента."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Текстът в кадър изпълнява конкретна задача: идентифицира човек, показва ключово число, подкрепя достъпността или дава CTA. Не повтаря всяка изговорена дума с огромен шрифт. Субтитрите трябва да са верни на речта и да се появяват навреме. Автоматичната транскрипция ускорява черновата, но имена, цифри, отрицания, пунктуация и жаргон се проверяват спрямо аудиото.\n\nПази важния текст в рамките на канала и тествай го в реален preview; интерфейсът може да закрива долната или страничната зона. Контрастът, размерът и редовете трябва да се четат на малък екран. Избери burn-in, sidecar или embedded captions според brief и възможността зрителят да ги включва."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Направи текстов слой след финалното кадриране, не преди да смениш aspect ratio. Провери дължина на ред, време за прочит, имената, езика и дали субтитрите не дублират графика. За важен CTA остави кадър, в който продукт/лице не се закрива. Пусни файл на малък телефон със звук и без звук."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи дали текстът е титър, субтитър, число или CTA.\n2. Генерирай чернова от аудио и сверявай редовете с оригиналния глас.\n3. Подреди йерархия, размер, контраст и позиция за всеки формат.\n4. Провери safe zones и елементи на платформата в целевия preview.\n5. Експортирай правилния вид caption track според изискването.\n6. Прегледай целия файл и провери имена, тайминг и скрито лице/продукт."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Видео с диетолог има 9:16 версия и субтитри на български. Автотранскриптът сбърква грамажа. Монтажистът сверява числото с одобрения източник, премества текста над зоната на интерфейса и проверява целия клип на телефон.\n\nКритерий за добър ход: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива."},"after":{"label":"Как го поправяш","text":"Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Добави субтитри към 20 секунди говор. Внеси нарочно грешка в име или число, после я открий чрез сверка с аудио. Провери burn-in и отделен caption track, ако програмата ги поддържа.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Генерирай чернова от аудио и сверявай редовете с оригиналния глас. Провери safe zones и елементи на платформата в целевия preview.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран.\n\nТестът е минал едва когато: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Видео с диетолог има 9:16 версия и субтитри на български. Автотранскриптът сбърква грамажа. Монтажистът сверява числото с одобрения източник, премества текста над зоната на интерфейса и проверява целия клип на телефон.\n\nДоставката ти е: Добави субтитри към 20 секунди говор. Внеси нарочно грешка в име или число, после я открий чрез сверка с аудио. Провери burn-in и отделен caption track, ако програмата ги поддържа.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe показва генериране на транскрипт и safe margins; провери актуалните ръководства: https://helpx.adobe.com/premiere/desktop/add-text-images/insert-captions/auto-transcribe-video-using-speech-to-text.html ; https://helpx.adobe.com/premiere/desktop/get-started/source-and-program-monitor-adjustments/view-safe-zones-in-the-monitors.html"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Провери транскрипта","content":{"question":"Кои думи са особено важни за ръчна проверка?","options":[{"id":"a","label":"Думи, които автоматиката е подчертала в зелено."},{"id":"b","label":"Само първият ред на клипа."},{"id":"c","label":"Имена, числа, отрицания и термини, сверени спрямо аудиото и одобрените факти."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Малка грешка в число или отрицание може да обърне смисъла.\n\nВариантът „Само първият ред на клипа.“ не доказва: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Вариантът „Думи, които автоматиката е подчертала в зелено.“ оставя нерешено: Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива. Безопасната корекция е: Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Текстът закрива продукта","content":{"prompt":"При preview на телефон субтитър покрива опаковката. Какво правиш?","options":[{"id":"a","label":"Преместваш/прекомпозираш субтитъра в безопасно място и проверяваш всички формати."},{"id":"b","label":"Свиваш текста, докато стане нечетим."},{"id":"c","label":"Оставяш го, защото на монтажния монитор се вижда."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Оцени позицията на реалния екран и интерфейса на канала.\n\nВариантът „Свиваш текста, докато стане нечетим.“ не доказва: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Вариантът „Оставяш го, защото на монтажния монитор се вижда.“ оставя нерешено: Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива. Безопасната корекция е: Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Избери вид captions","content":{"question":"Кога burn-in е подходящ?","options":[{"id":"a","label":"Винаги, независимо дали зрителят трябва да ги включва."},{"id":"b","label":"Когато брифът и каналът искат надписи винаги видими и стилът е проверен за кадъра."},{"id":"c","label":"Когато текстът още не е редактиран."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Избери формат по изискване; вариантът не отменя точността.\n\nВариантът „Винаги, независимо дали зрителят трябва да ги включва.“ не доказва: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Вариантът „Когато текстът още не е редактиран.“ оставя нерешено: Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива. Безопасната корекция е: Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Грешен грамаж","content":{"prompt":"В автоматичния субтитър има грешен грамаж. Как продължаваш?","options":[{"id":"a","label":"Махаш единицата, за да не се вижда грешката."},{"id":"b","label":"Сверяваш аудиото и одобрения източник, поправяш текста и преглеждаш останалите числа."},{"id":"c","label":"Оставяш го, ако изглежда реалистично."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Не гадай факти; проверявай числа преди предаване.\n\nВариантът „Оставяш го, ако изглежда реалистично.“ не доказва: Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат. Вариантът „Махаш единицата, за да не се вижда грешката.“ оставя нерешено: Автоматичният текст се експортира без корекция и се поставя ниско в кадъра, където платформеният UI го покрива. Безопасната корекция е: Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Провери safe zones и елементи на платформата в целевия preview."},{"id":"s1","text":"Определи дали текстът е титър, субтитър, число или CTA."},{"id":"s2","text":"Генерирай чернова от аудио и сверявай редовете с оригиналния глас."},{"id":"s3","text":"Подреди йерархия, размер, контраст и позиция за всеки формат."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи дали текстът е титър, субтитър, число или CTA.\n2. Генерирай чернова от аудио и сверявай редовете с оригиналния глас.\n3. Подреди йерархия, размер, контраст и позиция за всеки формат.\n4. Провери safe zones и елементи на платформата в целевия preview."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще поставиш точни, четими надписи и субтитри в кадър, който е проверен на целевото устройство.","Свери всяка реплика, провери safe zones на конкретния канал и изгледай export на истинския екран.","Всички думи и числа са потвърдени, надписът се чете на телефон и важен кадър остава видим във всеки формат."],"nextStep":"Добави субтитри към 20 секунди говор. Внеси нарочно грешка в име или число, после я открий чрез сверка с аудио. Провери burn-in и отделен caption track, ако програмата ги поддържа."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-05","title":"Корекция на цвета преди творческата визия","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще изравниш експозиция и баланс на бялото, ще съпоставиш кадри и ще приложиш look без да рушиш детайла.","hook":"LUT е нанесен върху всички клипове; кожата става оранжева, светлите части са изгорели, а различните камери вече не си приличат.","estimated_minutes":47,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изравниш експозиция и баланс на бялото, ще съпоставиш кадри и ще приложиш look без да рушиш детайла."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"LUT е нанесен върху всички клипове; кожата става оранжева, светлите части са изгорели, а различните камери вече не си приличат."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Работи в ред: идентифицирай профила и color management, нормализирай източника, коригирай експозиция и баланс, съпостави кадри, после добави творческа визия. Log не е самостоятелен look — той изисква правилно преобразуване към пространството за изход. Не нанасяй един LUT без проверка върху различни обективи, лица и светлини.\n\nИзползвай scopes като помощ, но гледай и самото изображение на калибриран/надежден дисплей. Запази детайл в кожи, светли участъци и сенки. Смесената светлина може да изисква локална корекция или повторно осветяване; не всяка цветна разлика може да се поправи без артефакт."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Първо провери source profile и timeline/output transform. Направи баланс на неутрална повърхност, после провери кожа и свързани кадри. Сравнявай frames едно до друго, не само по памет. Ако един кадър е свръхекспониран, изолирай го; не променяй целия timeline. Запиши node/layer имена, за да може колега да разбере корекцията."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Свери профил/гамут и целевия изход от camera note и брифа.\n2. Настрой управлението на цвета и преобразуването за source.\n3. Коригирай баланс на бялото и експозиция по scopes и образ.\n4. Съпостави кадри, кожа и ключови цветове в сцената.\n5. Добави creative look след correction; ограничи го, ако губи детайл.\n6. Провери целия монтаж на надежден екран и сравни кадри при playback."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Интервю е снимано с телефон в Log и кадри от втора камера в стандартен профил. Монтажистът първо установява source профила, отделно преобразува Log, изравнява бялото и съпоставя лица. Едва след това добавя по-нисък контрастен look, който не унищожава детайлите.\n\nКритерий за добър ход: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон."},"after":{"label":"Как го поправяш","text":"Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Коригирай два кадъра от една сцена и един с различна светлина. Направи преди/след сравнение, пази кожа и детайл в светлото, после добави умерен look.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Настрой управлението на цвета и преобразуването за source. Съпостави кадри, кожа и ключови цветове в сцената.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей.\n\nТестът е минал едва когато: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Интервю е снимано с телефон в Log и кадри от втора камера в стандартен профил. Монтажистът първо установява source профила, отделно преобразува Log, изравнява бялото и съпоставя лица. Едва след това добавя по-нисък контрастен look, който не унищожава детайлите.\n\nДоставката ти е: Коригирай два кадъра от една сцена и един с различна светлина. Направи преди/след сравнение, пази кожа и детайл в светлото, после добави умерен look.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Официалният DaVinci Resolve разделя Color страницата и инструментите за корекция от creative look; свери актуалната документация: https://www.blackmagicdesign.com/products/davinciresolve/color"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Ред на цветова работа","content":{"question":"Кога прилагаш творческия look?","options":[{"id":"a","label":"След като профилът, трансформацията, експозицията и балансът са проверени."},{"id":"b","label":"Преди да провериш дали източникът е Log."},{"id":"c","label":"Едновременно върху всички проекти по подразбиране."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Корекцията възстановява нормална база; look е отделен творчески избор.\n\nВариантът „Преди да провериш дали източникът е Log.“ не доказва: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Вариантът „Едновременно върху всички проекти по подразбиране.“ оставя нерешено: Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон. Безопасната корекция е: Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Оранжева кожа","content":{"prompt":"След LUT кожата е оранжева и детайлът в прозореца изчезва. Какво правиш?","options":[{"id":"a","label":"Добавяш още топлина, за да изравниш фона."},{"id":"b","label":"Проверяваш profile/transform и намаляваш или махаш LUT преди ръчна корекция."},{"id":"c","label":"Повишаваш наситеността на всички клипове."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери веригата и защити детайл; наслагването на ефекти не лекува грешно преобразуване.\n\nВариантът „Добавяш още топлина, за да изравниш фона.“ не доказва: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Вариантът „Повишаваш наситеността на всички клипове.“ оставя нерешено: Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон. Безопасната корекция е: Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Съпостави кадрите","content":{"question":"Как проверяваш две свързани сцени?","options":[{"id":"a","label":"Сверяваш само thumbnail от таймлайна."},{"id":"b","label":"Гледаш ги една до друга и сравняваш кожа, експозиция, неутрални повърхности и основни цветове."},{"id":"c","label":"Настройваш еднакви числови стойности на двата клипа."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Еднакви стойности не гарантират еднаква светлина или профил.\n\nВариантът „Настройваш еднакви числови стойности на двата клипа.“ не доказва: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Вариантът „Сверяваш само thumbnail от таймлайна.“ оставя нерешено: Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон. Безопасната корекция е: Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Смесена светлина","content":{"prompt":"Едната половина на лицето е от прозорец, другата от зелена лампа. Какъв е добрият ход?","options":[{"id":"a","label":"Коригираш сцената/маскираш локално, ако е възможно, и пазиш естествен тон на кожата."},{"id":"b","label":"Слагаш LUT с по-син нюанс върху всички сцени."},{"id":"c","label":"Прилагаш един white balance към целия кадър и усилваш сатурацията."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Смесеното осветление може да изисква локална работа; един глобален контрол може да влоши едната страна.\n\nВариантът „Прилагаш един white balance към целия кадър и усилваш сатурацията.“ не доказва: Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор. Вариантът „Слагаш LUT с по-син нюанс върху всички сцени.“ оставя нерешено: Един LUT се поставя без управление на цвета, а корекцията се прави по превюто на ярък телефон. Безопасната корекция е: Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Съпостави кадри, кожа и ключови цветове в сцената."},{"id":"s3","text":"Коригирай баланс на бялото и експозиция по scopes и образ."},{"id":"s2","text":"Настрой управлението на цвета и преобразуването за source."},{"id":"s1","text":"Свери профил/гамут и целевия изход от camera note и брифа."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Свери профил/гамут и целевия изход от camera note и брифа.\n2. Настрой управлението на цвета и преобразуването за source.\n3. Коригирай баланс на бялото и експозиция по scopes и образ.\n4. Съпостави кадри, кожа и ключови цветове в сцената."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще изравниш експозиция и баланс на бялото, ще съпоставиш кадри и ще приложиш look без да рушиш детайла.","Потвърди source profile и output transform, коригирай кадрите поотделно и провери на надежден дисплей.","Кадрите от една сцена се съпоставят; няма изгорели важни участъци; source profile и look са записани за следващия редактор."],"nextStep":"Коригирай два кадъра от една сцена и един с различна светлина. Направи преди/след сравнение, пази кожа и детайл в светлото, после добави умерен look."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-06","title":"Звук в монтажа: чист говор и измерен финал","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще подредиш диалога, room tone, музика и ефекти така, че посланието да остава разбираемо и да покрива delivery brief.","hook":"На монтажния монитор музиката е приятна, но на телефон заглушава тихия отговор и една рязка дума изскача силно.","estimated_minutes":44,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подредиш диалога, room tone, музика и ефекти така, че посланието да остава разбираемо и да покрива delivery brief."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"На монтажния монитор музиката е приятна, но на телефон заглушава тихия отговор и една рязка дума изскача силно."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Подреди звука по значимост: разбираем диалог, естествена среда, музика и ефекти. Поправи монтажни прекъсвания с room tone и чисти fades; ползвай EQ и компресия внимателно, след като отстраниш причина за шум. Гледай отделните канали и общия микс, защото два нормални клипа могат да се сумират твърде силно.\n\nНяма една универсална сила за всички платформи и договори. Използвай target от брифа и подходящ loudness meter, особено за podcast/broadcast deliverables. За социален клип слушай през слушалки, студийни монитори и обикновен телефон; провери mono compatibility. Не усилвай шум между репликите само за да запълниш тишината."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Изравни диалог между дублите, направи fades при cut, пази естествената динамика и автоматизирай музиката около ключови думи. Провери пикове и Integrated loudness според конкретния стандарт. Ако няма target, поискай; не измисляй число и не приемай, че normalize автоматично дава готов микс."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Потвърди delivery target и кой файл/канал трябва да бъде чути.\n2. Изолирай и подреди диалога; поправи очевидни прекъсвания и шумови пикове.\n3. Добави room tone, после музика/ефекти на по-ниско ниво.\n4. Автоматизирай нивото, за да остане говорът разбираем без постоянен максимум.\n5. Измери loudness/peaks спрямо brief; провери клипинг и тишина.\n6. Слушай целия export на телефон и слушалки; запиши измерване и версия."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Обяснителен клип има един тих дубъл и един силен. Монтажистът изравнява репликите, оставя room tone под cut-а и сваля музиката по време на важния термин. Loudness meter се настройва по зададената спецификация на клиента, а не по универсален интернет съвет.\n\nКритерий за добър ход: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота."},"after":{"label":"Как го поправяш","text":"Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Смеси 20 секунди диалог с room tone и музика. Провери три устройства, маркирай шип/клипинг и измери target loudness според brief или избран тестов формат.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Изолирай и подреди диалога; поправи очевидни прекъсвания и шумови пикове. Автоматизирай нивото, за да остане говорът разбираем без постоянен максимум.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства.\n\nТестът е минал едва когато: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Обяснителен клип има един тих дубъл и един силен. Монтажистът изравнява репликите, оставя room tone под cut-а и сваля музиката по време на важния термин. Loudness meter се настройва по зададената спецификация на клиента, а не по универсален интернет съвет.\n\nДоставката ти е: Смеси 20 секунди диалог с room tone и музика. Провери три устройства, маркирай шип/клипинг и измери target loudness според brief или избран тестов формат.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe Loudness Meter поддържа измерване и различни стандарти за различни доставки; избери target от брифа: https://helpx.adobe.com/premiere/desktop/add-audio-effects/apply-audio-effects/about-loudness-meter.html"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Пази разбираемия диалог","content":{"question":"В какъв ред е разумно да строиш микса?","options":[{"id":"a","label":"Музика до желания максимум, после диалог."},{"id":"b","label":"Диалог и монтажни поправки, среда, после музика и ефекти."},{"id":"c","label":"Ефекти и limiter преди да прослушаш суровата реч."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Диалогът носи основното послание; изгради другите слоеве около него.\n\nВариантът „Музика до желания максимум, после диалог.“ не доказва: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Вариантът „Ефекти и limiter преди да прослушаш суровата реч.“ оставя нерешено: Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота. Безопасната корекция е: Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Музиката заглушава думата","content":{"prompt":"Ключова дума изчезва при музикален удар. Какво правиш?","options":[{"id":"a","label":"Слагаш още компресия, без да слушаш."},{"id":"b","label":"Автоматизираш/сваляш музиката и проверяваш речта на телефон."},{"id":"c","label":"Повишаваш общия master output."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Подреди слоевете и провери четимостта на изговореното.\n\nВариантът „Повишаваш общия master output.“ не доказва: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Вариантът „Слагаш още компресия, без да слушаш.“ оставя нерешено: Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота. Безопасната корекция е: Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Избери target","content":{"question":"Какъв loudness target задаваш?","options":[{"id":"a","label":"Посочения от канала или клиента; ако липсва, изясняваш го или документираш тестова цел."},{"id":"b","label":"Колкото по-силно, толкова по-професионално."},{"id":"c","label":"Едно число за всеки тип видео."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Спецификациите се различават; измерителят проверява target, не го избира вместо теб.\n\nВариантът „Едно число за всеки тип видео.“ не доказва: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Вариантът „Колкото по-силно, толкова по-професионално.“ оставя нерешено: Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота. Безопасната корекция е: Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Щракване на среза","content":{"prompt":"На пауза между изреченията се чува щракване. Как го поправяш?","options":[{"id":"a","label":"Усилваш noise reduction върху целия клип."},{"id":"b","label":"Добавяш силен ефект точно върху щракването."},{"id":"c","label":"Проверяваш cut точката, добавяш room tone и кратък fade без да режеш смисъла."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Първо почисти монтажната точка; избягвай обработка, която поврежда целия глас.\n\nВариантът „Усилваш noise reduction върху целия клип.“ не доказва: Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано. Вариантът „Добавяш силен ефект точно върху щракването.“ оставя нерешено: Музиката се нормализира силно, лимитерът се натиска и речта губи динамика и яснота. Безопасната корекция е: Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Изолирай и подреди диалога; поправи очевидни прекъсвания и шумови пикове."},{"id":"s3","text":"Добави room tone, после музика/ефекти на по-ниско ниво."},{"id":"s4","text":"Автоматизирай нивото, за да остане говорът разбираем без постоянен максимум."},{"id":"s1","text":"Потвърди delivery target и кой файл/канал трябва да бъде чути."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Потвърди delivery target и кой файл/канал трябва да бъде чути.\n2. Изолирай и подреди диалога; поправи очевидни прекъсвания и шумови пикове.\n3. Добави room tone, после музика/ефекти на по-ниско ниво.\n4. Автоматизирай нивото, за да остане говорът разбираем без постоянен максимум."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще подредиш диалога, room tone, музика и ефекти така, че посланието да остава разбираемо и да покрива delivery brief.","Изгради баланса от диалог навън, измери финала по зададен стандарт и провери на реални устройства.","Речта се разбира на телефон, няма клипинг или рязък cut, а финалното измерване отговаря на спецификацията и е записано."],"nextStep":"Смеси 20 секунди диалог с room tone и музика. Провери три устройства, маркирай шип/клипинг и измери target loudness според brief или избран тестов формат."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-07","title":"Adjustment layers: общ ефект с контрол над изключенията","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще приложиш обща корекция върху серия кадри и ще изолираш кадрите, които изискват отделно решение.","hook":"Една промяна в adjustment layer поправя повечето клипове, но съсипва нощния кадър и кожата в близкия план.","estimated_minutes":37,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще приложиш обща корекция върху серия кадри и ще изолираш кадрите, които изискват отделно решение."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Една промяна в adjustment layer поправя повечето клипове, но съсипва нощния кадър и кожата в близкия план."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Adjustment layer дава обща промяна върху кадри под него — например лек look, винетка, графика или общо кадриране. Той е бърз и неразрушителен само ако обхватът му е видим и изключенията са планирани. Някои корекции принадлежат към клипа, други към целия sequence; не слагай всичко на един слой.\n\nИменувай слоевете по функция, настройвай диапазона и маркирай изключения. Провери крайния кадър в началото, средата и края на покрития sequence. Ако клипът влиза под слой по невнимание, проблемът се появява чак в export.\n\nРаботна проверка: Организирай слоя и ефекта така, че друг монтажист да разбере приоритета им. Провери подредбата на color correction, graphic, blur и crop; различна последователност може да промени резултата. Именувай layers по функция, запиши кои клипове са изключени и запази изходен кадър без ефект за сравнение. Дублирай секцията преди глобална промяна; не прави една корекция върху цялата серия без проверка на тъмна, светла и смесена сцена.\n\nДопълнителен ход от практиката: На малка серия изключи слоя за отделни клипове, после го върни и провери изключенията един по един. Обърни внимание на adjustment layer над nested sequence, alpha/transparency, blend mode и transition: обхватът му може да е по-голям от видимия clip. Запиши стойности и планиран диапазон, направи screenshot на node/effect order и прегледай краищата на всеки clip. При различни камери приложи корекцията само след matching pass, иначе един глобален ефект ще уеднакви грешките."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Раздели базова корекция на source clip от обща стилизация. Използвай отделен слой за текстура или look и още един, ако нужна графика трябва да стои над всички изображения. Запиши кое ниво влияе на кой кадър. За sequence с различни локации направи отделни group или локални adjustments."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи дали корекцията е за източник, група кадри или целия timeline.\n2. Създай слой с точно име и постави го над желаните клипове.\n3. Ограничи дължината/диапазона и провери кадрите под него.\n4. Изключи или направи отделен вариант за кадър, който не понася ефекта.\n5. Пусни sequence от начало до край, гледайки първи/средни/последни кадри.\n6. Запиши слоя и зависимостите в project handoff."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Серия интервюта има обща леко топла визия. Един кадър е нощен и вече топъл. Общият layer прилага стил на всички, затова монтажистът изключва нощния insert и коригира локално, без да променя базата на останалата серия.\n\nКритерий за добър ход: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име."},"after":{"label":"Как го поправяш","text":"Раздели функция, контролирай диапазон и провери кадрите в реалния playback."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи общ слой за три кадъра, нарочно включи четвърти кадър с различна светлина, после изолирай изключението и запиши layer map.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Създай слой с точно име и постави го над желаните клипове. Изключи или направи отделен вариант за кадър, който не понася ефекта.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Раздели функция, контролирай диапазон и провери кадрите в реалния playback.\n\nТестът е минал едва когато: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Постави корекция на правилното ниво","content":{"question":"Кога adjustment layer е удобен?","options":[{"id":"a","label":"Когато ефектът трябва да остане без име и граници."},{"id":"b","label":"Когато една контролирана промяна трябва да важи за ясно ограничена група кадри."},{"id":"c","label":"Когато всеки кадър има различна цветова грешка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Общ слой е ефективен само ако влиянието и изключенията са видими.\n\nВариантът „Когато всеки кадър има различна цветова грешка.“ не доказва: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж. Вариантът „Когато ефектът трябва да остане без име и граници.“ оставя нерешено: Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име. Безопасната корекция е: Раздели функция, контролирай диапазон и провери кадрите в реалния playback. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Нощният кадър се променя","content":{"prompt":"Общият look прави нощния кадър прекалено топъл. Какво правиш?","options":[{"id":"a","label":"Изключваш или локално коригираш този кадър и проверяваш sequence-а отново."},{"id":"b","label":"Оставяш го, защото adjustment layer е общ."},{"id":"c","label":"Намаляваш look-а за целия филм, без да гледаш останалите кадри."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Изключението може да се отдели; провери дали общата промяна още работи за останалата сцена.\n\nВариантът „Намаляваш look-а за целия филм, без да гледаш останалите кадри.“ не доказва: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж. Вариантът „Оставяш го, защото adjustment layer е общ.“ оставя нерешено: Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име. Безопасната корекция е: Раздели функция, контролирай диапазон и провери кадрите в реалния playback. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Дай слой име","content":{"question":"Защо името на adjustment layer е важно?","options":[{"id":"a","label":"За да спечелиш точки в timeline."},{"id":"b","label":"За да замени notes и проверка."},{"id":"c","label":"Показва функцията и помага на колега да разбере обхват и зависимост."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Надписът е част от четимостта на проекта; документацията пак е нужна за сложни зависимости.\n\nВариантът „За да спечелиш точки в timeline.“ не доказва: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж. Вариантът „За да замени notes и проверка.“ оставя нерешено: Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име. Безопасната корекция е: Раздели функция, контролирай диапазон и провери кадрите в реалния playback. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Ефектът свършва по средата","content":{"prompt":"Export-ът показва, че ефектът спира на неочакван кадър. Какво проверяваш?","options":[{"id":"a","label":"Променяш резолюцията на проекта."},{"id":"b","label":"Само настройката на последния клип."},{"id":"c","label":"Дължината и позицията на слоя и playback целия sequence."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Грешен диапазон е проблем на timeline организацията; проследи слоя от начало до край.\n\nВариантът „Само настройката на последния клип.“ не доказва: Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж. Вариантът „Променяш резолюцията на проекта.“ оставя нерешено: Общият слой се простира извън sequence или съдържа едновременно цветове, текст и корекции без ясно име. Безопасната корекция е: Раздели функция, контролирай диапазон и провери кадрите в реалния playback. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Създай слой с точно име и постави го над желаните клипове."},{"id":"s1","text":"Определи дали корекцията е за източник, група кадри или целия timeline."},{"id":"s4","text":"Изключи или направи отделен вариант за кадър, който не понася ефекта."},{"id":"s3","text":"Ограничи дължината/диапазона и провери кадрите под него."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи дали корекцията е за източник, група кадри или целия timeline.\n2. Създай слой с точно име и постави го над желаните клипове.\n3. Ограничи дължината/диапазона и провери кадрите под него.\n4. Изключи или направи отделен вариант за кадър, който не понася ефекта."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще приложиш обща корекция върху серия кадри и ще изолираш кадрите, които изискват отделно решение.","Раздели функция, контролирай диапазон и провери кадрите в реалния playback.","Друг редактор разбира кое се влияе от всеки слой; всички изключения са отбелязани и проверени в целия монтаж."],"nextStep":"Направи общ слой за три кадъра, нарочно включи четвърти кадър с различна светлина, после изолирай изключението и запиши layer map."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-08","title":"Proxy без изгубен оригинал: монтаж и възстановяване","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще създадеш proxy за плавен монтаж и ще провериш, че финалът връща връзка към camera original.","hook":"Монтажът тече плавно, но export-ът се прави от proxy с по-ниска rezолюция, а оригиналните клипове са offline.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще създадеш proxy за плавен монтаж и ще провериш, че финалът връща връзка към camera original."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Монтажът тече плавно, но export-ът се прави от proxy с по-ниска rezолюция, а оригиналните клипове са offline."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Proxy е по-леко копие за монтаж; той не заменя camera original и не е архив. Генерирай го по пресет, който съответства на кадрите в timeline, свържи го с източника и обозначи proxy/original пътища. Провери proxy toggle на тестов клип, името, aspect ratio, звук и playback. Финалният export трябва да използва оригиналите според проекта, освен ако brief изрично и аргументирано не казва друго.\n\nСъхранявай proxy отделно от оригинала и пази manifest. Ако проектът се отвори на друга станция, тествай relink към оригинал и направи test export на детайл. Грешен proxy може да има различен кадър или timecode и да доведе до грешни монтажни точки."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Избери codec/resolution според монтажния компютър, не само размера. Генерирай proxy с уникална папка/суфикс, после потвърди съответствие на duration, frame rate, ориентация и audio channels. Не преименувай оригинали след attach без relink. Преди master: изключи proxies или избери full-res playback, провери representative frame и status на media."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Запази и провери оригиналите, структурата и техните имена.\n2. Създай proxy preset и папка, отделена от camera media.\n3. Генерирай sample и сравни frame, timecode, ориентация и звук.\n4. Attach-ни proxy към оригинала и провери включване/изключване в timeline.\n5. Тествай проекта и пътя до оригинала на работната станция, която ще експортира.\n6. Направи кратък full-resolution export, отвори го и провери детайл преди master."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Камерата снима дълги 4K клипове; лаптопът накъсва при scrub. Монтажистът създава proxy, свързва ги по оригиналния media ID и работи локално. Преди export той изключва proxy режима, relink-ва full-res медия и гледа пробен кадър на коса и текст.\n\nКритерий за добър ход: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция."},"after":{"label":"Как го поправяш","text":"Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"На тестов проект направи proxy за три клипа, изключи го, премести оригиналите в друга папка и relink-ни проекта. Експортирай кратка проба от оригиналите.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Създай proxy preset и папка, отделена от camera media. Attach-ни proxy към оригинала и провери включване/изключване в timeline.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master.\n\nТестът е минал едва когато: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Камерата снима дълги 4K клипове; лаптопът накъсва при scrub. Монтажистът създава proxy, свързва ги по оригиналния media ID и работи локално. Преди export той изключва proxy режима, relink-ва full-res медия и гледа пробен кадър на коса и текст.\n\nДоставката ти е: На тестов проект направи proxy за три клипа, изключи го, премести оригиналите в друга папка и relink-ни проекта. Експортирай кратка проба от оригиналите.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe описва създаване и прикачване на proxy media в Premiere: https://helpx.adobe.com/premiere/desktop/organize-media/ingest-proxy-workflow/create-proxies.html"},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Proxy или original","content":{"question":"Каква е ролята на proxy файла?","options":[{"id":"a","label":"Да улесни playback и монтаж, докато запазва връзка към camera original."},{"id":"b","label":"Да замени оригинала във финален master независимо от brief."},{"id":"c","label":"Да стане единствената архивна копия."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Proxy ускорява editing, original остава source of truth.\n\nВариантът „Да стане единствената архивна копия.“ не доказва: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Вариантът „Да замени оригинала във финален master независимо от brief.“ оставя нерешено: Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция. Безопасната корекция е: Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Offline оригинали","content":{"prompt":"Проектът отваря с proxy online, но camera originals offline. Какво правиш преди master?","options":[{"id":"a","label":"Предаваш proxy export, без да кажеш."},{"id":"b","label":"Преименуваш proxies като оригинали."},{"id":"c","label":"Възстановяваш правилния media path и тестваш full-res preview и export."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Потвърди full-resolution източника преди master delivery.\n\nВариантът „Предаваш proxy export, без да кажеш.“ не доказва: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Вариантът „Преименуваш proxies като оригинали.“ оставя нерешено: Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция. Безопасната корекция е: Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери proxy attach","content":{"question":"Кое сравняваш при sample proxy?","options":[{"id":"a","label":"Само името на папката."},{"id":"b","label":"Само големината на файла."},{"id":"c","label":"Изображение, времетраене/timecode, ориентация и звук спрямо оригинала."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Грешен timecode или кадър може да размести монтажните точки.\n\nВариантът „Само големината на файла.“ не доказва: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Вариантът „Само името на папката.“ оставя нерешено: Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция. Безопасната корекция е: Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Нисък детайл при export","content":{"prompt":"Кратката проба показва мека картина и дребен текст. Какво проверяваш?","options":[{"id":"a","label":"Дали проектът рендерира от оригиналите и дали output използва изискваната резолюция."},{"id":"b","label":"Повишаваш sharpness до максимум."},{"id":"c","label":"Одобряваш, защото timeline е плавен."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Playback performance и финалният source resolution са различни критерии.\n\nВариантът „Повишаваш sharpness до максимум.“ не доказва: Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал. Вариантът „Одобряваш, защото timeline е плавен.“ оставя нерешено: Proxy папката заменя камерата в проекта и последният export не е проверен на пълна резолюция. Безопасната корекция е: Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Attach-ни proxy към оригинала и провери включване/изключване в timeline."},{"id":"s1","text":"Запази и провери оригиналите, структурата и техните имена."},{"id":"s2","text":"Създай proxy preset и папка, отделена от camera media."},{"id":"s3","text":"Генерирай sample и сравни frame, timecode, ориентация и звук."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Запази и провери оригиналите, структурата и техните имена.\n2. Създай proxy preset и папка, отделена от camera media.\n3. Генерирай sample и сравни frame, timecode, ориентация и звук.\n4. Attach-ни proxy към оригинала и провери включване/изключване в timeline."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще създадеш proxy за плавен монтаж и ще провериш, че финалът връща връзка към camera original.","Дръж proxy като отделно свързано производно; изисквай full-resolution test преди одобрен master.","Можеш да превключваш proxy/original, проектът възстановява връзка, а финалната проба показва детайл от оригиналния материал."],"nextStep":"На тестов проект направи proxy за три клипа, изключи го, премести оригиналите в друга папка и relink-ни проекта. Експортирай кратка проба от оригиналите."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-09","title":"J-cut и L-cut: звукът подготвя или продължава кадъра","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще използваш разделен монтаж на звук и картина, за да свържеш сцени естествено и да запазиш точен смисъл.","hook":"Новият кадър се появява чак след като репликата започне, но срезът разкрива говорещия твърде рано и убива реакцията.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще използваш разделен монтаж на звук и картина, за да свържеш сцени естествено и да запазиш точен смисъл."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Новият кадър се появява чак след като репликата започне, но срезът разкрива говорещия твърде рано и убива реакцията."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"При J-cut звукът на следващия кадър започва преди картината му; при L-cut звукът от текущата сцена продължава под следващ кадър. И двата хода могат да подготвят място, запазят реакция и прикрият твърд визуален срез. Те не поправят липсваща дума, различен факт или шумен аудио дубъл.\n\nОстави чист handle преди/след репликата, провери lip sync и пази причината кой говори. В интервю кадърът на слушателя може да е полезен, но не трябва да внушава реакция, която не се е случила. Пусни монтажа със затворени очи и без картина, после гледай с картина, за да чуеш/видиш прехода отделно.\n\nПолеви наръчник: Отдели аудиото от картината и премести само единия край: при J-cut звукът на следващия план започва по-рано; при L-cut предишният звук остава под новото изображение. Остави чист handle преди съгласната и след думата; не режи вдишване, ударна съгласна или естествена пауза. Когато репликата принадлежи на конкретен човек, не приписвай думите на друг. Сравни синхронен срез, кратък J/L ход и чист cutaway. Слушай със слушалки, после гледай без звук: историята трябва да остане ясна, а преходът да не подвежда за реда на събитията. Ако няма покриващ кадър или чиста реплика, намери нов дубъл; не лепи несвързани срички по waveform-а.\n\nРаботна проверка: Измери прехода на ухо и по waveform, но не използвай waveform вместо слушане. Остави room tone под паузата, ако тишината рязко се сменя, и провери, че преходът не събира различни дни така, че да променя значението. При двама говорители запази ясната смяна на репликата и синхрон на устните, когато лицето остава в кадър. Изгледай целия обмен в контекст — единичен срез може да звучи чисто, но да обърка кой задава въпроса.\n\nДопълнителен ход от практиката: Работи по фраза, не по целия waveform наведнъж: избери in/out, остави пред- и следзвуков запас и провери ритъма в пълната сцена. Fade трябва да скрие преход, не да отсече дума. Не премествай естествена реакция под звук от друг момент така, че да приписваш чуждо мнение. Ако тонът на стаята се сменя, подложи подходящ room tone и прослушай на малки говорители и слушалки. Запази отделна audio track версия, за да може друг монтажист да провери sync-а.\n\nПрактически разбор: Раздели clip audio/video или използвай linked source със съзнателно разместени ръбове. Направи къс audio fade при ambience; не режи срички. При смяна на говорещ отбележи кой има репликата и кога започва. J/L-cut е монтажен инструмент и може да е неподходящ за точно продуктово демо, където синхронът е доказателство."},"points":2,"required":true},{"position":3,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Маркирай реплика или звук, който може да свърже две сцени.\n2. Провери чисти handles и кой говори в двата кадъра.\n3. Избери J-cut за предварително чуван следващ звук или L-cut за продължаващ звук.\n4. Премести аудио ръба без да отрязваш сричка и добави нужния fade.\n5. Провери sync и реакция с картина, после прослушай без картина.\n6. Върни точния cut, ако преходът променя контекст или подвежда."},"points":2,"required":true},{"position":4,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Клиентът пита специалист дали услугата е подходяща. L-cut оставя последната част от отговора върху кадър с действие в кабинета. Следващата сцена започва с ambience от мястото преди да се види говорещият, за да се смени пространството естествено.\n\nХод, който се проваля: Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement.\n\nКорекция: Провери кой изрича думите, какво показва картината и дали преходът променя смисъл.\n\nКритерий за добър ход: Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало."},"points":2,"required":true},{"position":5,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи две версии на преход между интервю и b-roll: една с J-cut и една с L-cut. Остави различен handle и провери sync, факт и реакция.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":6,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":7,"block_key":"quiz_1","block_type":"quiz","title":"Назови двата cut-а","content":{"question":"Кое е J-cut?","options":[{"id":"a","label":"Текущият звук продължава след смяната на картината."},{"id":"b","label":"Звукът и картината се съкращават на едно място."},{"id":"c","label":"Следващата сцена започва да се чува преди да се покаже."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"J-cut въвежда аудио от следващата сцена по-рано.\n\nВариантът „Текущият звук продължава след смяната на картината.“ не доказва: Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало. Вариантът „Звукът и картината се съкращават на едно място.“ оставя нерешено: Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement. Безопасната корекция е: Провери кой изрича думите, какво показва картината и дали преходът променя смисъл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":8,"block_key":"scenario_1","block_type":"scenario","title":"Репликата продължава върху b-roll","content":{"prompt":"Звукът от интервюто продължава под кадър на ръце в работа. Какъв е монтажът?","options":[{"id":"a","label":"Match cut, защото има нов детайл."},{"id":"b","label":"J-cut, защото всяко преместване на звук е J-cut."},{"id":"c","label":"L-cut, защото звукът от текущата сцена продължава при следваща картина."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"При L-cut картината се сменя, а предишният звук остава.\n\nВариантът „J-cut, защото всяко преместване на звук е J-cut.“ не доказва: Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало. Вариантът „Match cut, защото има нов детайл.“ оставя нерешено: Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement. Безопасната корекция е: Провери кой изрича думите, какво показва картината и дали преходът променя смисъл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"quiz_2","block_type":"quiz","title":"Остави handle","content":{"question":"Защо звукът трябва да има чист handle?","options":[{"id":"a","label":"За да започне/завърши без сричка, click или рязко прекъсване."},{"id":"b","label":"За да удължи произволно клипа."},{"id":"c","label":"За да скрие всеки проблем в речта."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Handle позволява естествен преход; той не поправя грешно съдържание.\n\nВариантът „За да удължи произволно клипа.“ не доказва: Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало. Вариантът „За да скрие всеки проблем в речта.“ оставя нерешено: Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement. Безопасната корекция е: Провери кой изрича думите, какво показва картината и дали преходът променя смисъл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_2","block_type":"scenario","title":"Подвеждаща реакция","content":{"prompt":"Под репликата на клиента си сложил лице на друг човек, който не е чул казаното. Какво правиш?","options":[{"id":"a","label":"Оставяш го, защото монтажът е по-емоционален."},{"id":"b","label":"Връщаш кадър на действителния говорещ или използваш нейтрален b-roll, който не приписва реакция."},{"id":"c","label":"Добавяш субтитър с името на говорещия."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Преходът не трябва да приписва думи или реакция на погрешния човек.\n\nВариантът „Оставяш го, защото монтажът е по-емоционален.“ не доказва: Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало. Вариантът „Добавяш субтитър с името на говорещия.“ оставя нерешено: Репликата се мести над кадър на човек, който не я е казал, създавайки невярна реакция или endorsement. Безопасната корекция е: Провери кой изрича думите, какво показва картината и дали преходът променя смисъл. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Премести аудио ръба без да отрязваш сричка и добави нужния fade."},{"id":"s3","text":"Избери J-cut за предварително чуван следващ звук или L-cut за продължаващ звук."},{"id":"s2","text":"Провери чисти handles и кой говори в двата кадъра."},{"id":"s1","text":"Маркирай реплика или звук, който може да свърже две сцени."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Маркирай реплика или звук, който може да свърже две сцени.\n2. Провери чисти handles и кой говори в двата кадъра.\n3. Избери J-cut за предварително чуван следващ звук или L-cut за продължаващ звук.\n4. Премести аудио ръба без да отрязваш сричка и добави нужния fade."},"scoring":{"mode":"exact_order"}},{"position":12,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще използваш разделен монтаж на звук и картина, за да свържеш сцени естествено и да запазиш точен смисъл.","Провери кой изрича думите, какво показва картината и дали преходът променя смисъл.","Преходът е плавен, сричките и ambience не се късат, а зрителят не се подвежда кой е говорил или какво е станало."],"nextStep":"Направи две версии на преход между интервю и b-roll: една с J-cut и една с L-cut. Остави различен handle и провери sync, факт и реакция."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-10","title":"Speed ramp: промени темпото, без да скриеш проблема","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще контролираш ускорение и забавяне така, че да подчертаят действие, без видими дупки, артефакти или загубен смисъл.","hook":"Преходът е зрелищен на timeline, но ръката прескача позиции и зрителят не разбира дали процесът е показан в ред.","estimated_minutes":39,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще контролираш ускорение и забавяне така, че да подчертаят действие, без видими дупки, артефакти или загубен смисъл."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Преходът е зрелищен на timeline, но ръката прескача позиции и зрителят не разбира дали процесът е показан в ред."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Speed ramp е промяна на скоростта във времето, не универсална украса. Използвай го, когато темпото изразява действие, компресира повторение или води поглед към акцент. Slow motion иска достатъчно заснети кадри и чисто движение; повторение на същия кадър не възстановява липсващ детайл. Optical flow може да създаде артефакти около ръце, коса, вода и текст.\n\nПланирай начална и крайна скорост, посока на движение и звук. Избягвай ramp върху инструкция, където зрителят трябва да види точния ход. Провери кадрите в движение, не само на стоп кадър; ако експортираният клип изглежда неестествен, върни простото темпо.\n\nПолеви наръчник: Провери връзката между source frame rate, timeline и delivery frame rate. Забавянето използва само записаните кадри; optical flow изчислява междинни изображения и може да деформира пръсти, решетка, течност, коса и движещ се текст. Постави начална, средна и крайна скорост около действието; огледай контакт с предмета, формата и sync на звука. Сравни кратък render с версия при естествена скорост. Не прави ramp върху точна инструкция или действие, чиято поредност има значение. Ако source няма нужните кадри, уговори нов дубъл или остави умерено темпо. Интерполацията не възстановява липсваща информация.\n\nРаботна проверка: Запиши скорост като число и посока: 50% прави отсечката два пъти по-дълга, а 200% я прави наполовина. Това променя тайминг и място за звук, надпис и следващ срез; не променя автоматично кадровата честота на финалния файл. Ако ramp мести важен момент, обнови музикалния hit и субтитъра, после прегледай цялата последователност. Запази нормалната версия като сравнение, за да докажеш, че ефектът помага на действието, а не само удължава кадъра.\n\nДопълнителен ход от практиката: Ключовите кадри задават характер на ускорението: линейна крива звучи механично, а прекалено остра крива може да дръпне вниманието от продукта. Провери кадрите около speed point покадрово и прослушай нативния звук; pitch-shifted звук може да стане смешен или нечетим. Ако оригиналното действие съдържа доказателствен детайл, запази го при нормална скорост в друг план. Запиши точния source и стойностите на retime, за да може клиента да поиска промяна без да се гадае.\n\nПрактически разбор: Постави speed points около действието, направи плавна интерполация и сравни с оригиналната скорост. Провери оптични артефакти и blur, особено при бърз обект. Музиката или звукът може да се отдели или промени; запази естествен звук, ако той обяснява действие. Използвай source frame rate, който позволява желаното забавяне, и провери cadence при target export."},"points":2,"required":true},{"position":3,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи коя част трябва да се почувства бърза или бавна и защо.\n2. Провери source frame rate и дали има достатъчно кадри за slow motion.\n3. Постави speed points преди/след ключовото действие.\n4. Избери плавен ramp и провери начална, средна и крайна скорост.\n5. Огледай ръце, контури, вода, текст и sync за артефакти.\n6. Експортирай кратък тест и сравни с версия без ramp."},"points":2,"required":true},{"position":4,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Реклама показва капка вода върху продукт. Кратко забавяне подчертава удара, после клипът връща нормална скорост за използване. Екипът избира дубъл с достатъчно кадри и маха optical-flow версията, която деформира ръба на капката.\n\nХод, който се проваля: Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста.\n\nКорекция: Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview.\n\nКритерий за добър ход: Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено."},"points":2,"required":true},{"position":5,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Използвай кратък клип с видимо движение. Направи прост срез, умерен ramp и силен ramp; сравни естественост, четимост и артефакти на ръбове.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":6,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":7,"block_key":"quiz_1","block_type":"quiz","title":"Избери кадри за slow motion","content":{"question":"Какво проверяваш преди забавяне?","options":[{"id":"a","label":"Дали има свободна памет на компютъра."},{"id":"b","label":"Само дали ефектът изглежда впечатляващ в preview."},{"id":"c","label":"Source frame rate, движение и дали сцената остава четима при target cadence."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Източникът трябва да съдържа достатъчно времева информация за планираното забавяне.\n\nВариантът „Само дали ефектът изглежда впечатляващ в preview.“ не доказва: Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено. Вариантът „Дали има свободна памет на компютъра.“ оставя нерешено: Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста. Безопасната корекция е: Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":8,"block_key":"scenario_1","block_type":"scenario","title":"Артефакт по ръба","content":{"prompt":"Optical flow огъва пръстите в близък кадър. Какво правиш?","options":[{"id":"a","label":"Ползваш по-проста интерполация, друг дубъл или нормална скорост и проверяваш export."},{"id":"b","label":"Вдигаш размазването, за да скриеш warping."},{"id":"c","label":"Оставяш, защото на малък екран може да не личи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Артефактът е доказателство, че конкретният кадър не понася интерполацията.\n\nВариантът „Вдигаш размазването, за да скриеш warping.“ не доказва: Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено. Вариантът „Оставяш, защото на малък екран може да не личи.“ оставя нерешено: Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста. Безопасната корекция е: Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"quiz_2","block_type":"quiz","title":"Не ускорявай инструкцията","content":{"question":"Кога speed ramp не е подходящ?","options":[{"id":"a","label":"Винаги при продуктова реклама."},{"id":"b","label":"Когато зрителят трябва да разбере точно поредността или детайлите на сложното действие."},{"id":"c","label":"Само когато няма музика."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Яснотата на действието е по-важна от ефектното темпо.\n\nВариантът „Винаги при продуктова реклама.“ не доказва: Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено. Вариантът „Само когато няма музика.“ оставя нерешено: Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста. Безопасната корекция е: Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_2","block_type":"scenario","title":"Нямаш кадри за забавяне","content":{"prompt":"Видеото е записано при стандартна честота, но клиентът иска силно slow motion. Какво правиш?","options":[{"id":"a","label":"Увеличаваш резолюцията на export."},{"id":"b","label":"Показваш теста и предлагаш друг дубъл/кадров режим или умерено темпо, което не прави дупки."},{"id":"c","label":"Повтаряш всеки кадър и го предаваш като естествен slow motion."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Не обещавай детайл, който източникът не е записал.\n\nВариантът „Повтаряш всеки кадър и го предаваш като естествен slow motion.“ не доказва: Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено. Вариантът „Увеличаваш резолюцията на export.“ оставя нерешено: Slow motion се създава от клип с малко кадри, а интерполацията разтяга ръцете и текста. Безопасната корекция е: Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Провери source frame rate и дали има достатъчно кадри за slow motion."},{"id":"s3","text":"Постави speed points преди/след ключовото действие."},{"id":"s4","text":"Избери плавен ramp и провери начална, средна и крайна скорост."},{"id":"s1","text":"Определи коя част трябва да се почувства бърза или бавна и защо."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи коя част трябва да се почувства бърза или бавна и защо.\n2. Провери source frame rate и дали има достатъчно кадри за slow motion.\n3. Постави speed points преди/след ключовото действие.\n4. Избери плавен ramp и провери начална, средна и крайна скорост."},"scoring":{"mode":"exact_order"}},{"position":12,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще контролираш ускорение и забавяне така, че да подчертаят действие, без видими дупки, артефакти или загубен смисъл.","Избери source с подходяща кадрова честота или не забавяй; провери артефакти в export, не само preview.","Промяната на скоростта има причина, действие се разбира, няма видими дупки или warping и аудиото е обмислено."],"nextStep":"Използвай кратък клип с видимо движение. Направи прост срез, умерен ramp и силен ramp; сравни естественост, четимост и артефакти на ръбове."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-11","title":"Punch-in и маски: приближи внимание, не пикселите","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще изолираш детайл или ще прикриеш монтажен скок, без да губиш резолюция, фокус или естествено движение.","hook":"Punch-in върху говорещия прикрива скок, но изображението омеква и рамката реже брадичката при всяка реплика.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изолираш детайл или ще прикриеш монтажен скок, без да губиш резолюция, фокус или естествено движение."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Punch-in върху говорещия прикрива скок, но изображението омеква и рамката реже брадичката при всяка реплика."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Punch-in е увеличение на кадъра или промяна на компоновката; маската изолира зона или създава преход. Използвай ги, когато искат вниманието да се премести към предмет, поглед или малък jump cut. Първо провери резолюция и размер на source: цифровото увеличение не създава нов детайл и може да покаже шум.\n\nСледи позицията на очите, headroom и ръбове при движение. Маската се проследява кадър по кадър; feather и ръбът трябва да съвпадат с фона, без ореол. Не замаскирай липсваща реплика или недостоверен кадър. Пусни loop в реален размер, не само увеличен preview.\n\nПолеви наръчник: Преди punch-in сметни пикселния запас между source и target: провери резолюция, aspect ratio, стабилизационния crop и safe area. Огледай текст, очи, коса и продукт на крайния размер; proxy preview не доказва рязкост. За маска избери проследима точка и провери ръба върху светъл и тъмен фон. Feather твърде широк прави ореол, твърде тесен изрязва контура. Ако ръката закрива tracking point, коригирай ключовите кадри на малки интервали или избери cutaway. При лице, документ или номер провери дали покритието остава пълно по време на движение.\n\nРаботна проверка: Провери маската и за приватност и съгласие: замъгляване на адрес или лице трябва да покрива всеки кадър, включително появата и излизането от зоната. Проследи motion blur и пропуснати кадри около cut; някои ефекти изместват ръба за един frame. Ако не можеш да докажеш пълно покритие, смени кадъра или изрежи участъка. Запиши кой е проверил замаскирания export и на кой размер на екрана.\n\nДопълнителен ход от практиката: Провери ръба frame by frame при края на shot, motion blur и преход към следващ кадър; tracking може да е точен в средата и да излезе от зона за няколко кадъра. При privacy маска покрий и отражение в стъкло, огледало или екран, ако лицето/данните се виждат там. Ако маската въздейства върху логото или важен обект, избери друг crop вместо да оставиш странно петно. Предай и изходния кадър за одобрение, като проверяващият гледа именно зоната, която е трябвало да се скрие."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"При 4K source към 1080 output има известен crop запас, но зависи от реалната резолюция, ориентация, стабилизация и target. Тествай на финалния размер и при движение. За jump cut можеш да смени план, вмъкнеш b-roll или запазиш естествено напрежение; маска не е задължителна."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Определи какво трябва да се види по-добре и къде е скокът.\n2. Провери source resolution и target crop.\n3. Настрой scale/position така, че лице, ръце и текст да останат в кадър.\n4. За маска проследи движение, feather, ръб и скриване на фона.\n5. Провери целия участък на финален размер и при движение.\n6. Сравни с по-прост вариант: срез, b-roll или запазен кадър."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Интервю има jump cut между две изречения. Вместо да увеличи кадъра толкова, че да загуби детайл, монтажистът прави леко punch-in и вмъква кратък cutaway на ръцете. Маската се ползва само за графика, не за скриване на грешна реплика.\n\nКритерий за добър ход: Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице."},"after":{"label":"Как го поправяш","text":"Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи две версии на jump cut: лек punch-in и cutaway. Ако добавиш маска, проследи движеща се ръка и провери ръбовете на целия клип.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Провери source преди punch-in","content":{"question":"Какво ограничава цифровото приближаване?","options":[{"id":"a","label":"Резолюцията, фокусът, шумът, движението и размерът на крайния export."},{"id":"b","label":"Само дължината на клипа."},{"id":"c","label":"Само цветът на фона."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Crop-ът увеличава наличните пиксели; той не създава нов детайл.\n\nВариантът „Само дължината на клипа.“ не доказва: Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда. Вариантът „Само цветът на фона.“ оставя нерешено: Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице. Безопасната корекция е: Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Маската оставя ореол","content":{"prompt":"При движение има светъл ореол по маската. Какво правиш?","options":[{"id":"a","label":"Увеличаваш контраста и оставяш маската."},{"id":"b","label":"Проверяваш tracking, feather и контраст на ръба или избираш по-прост кадър/срез."},{"id":"c","label":"Разширяваш маската до цял кадър без проверка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Ореолът показва несъвпадение; коригирай ръба или откажи ефекта.\n\nВариантът „Увеличаваш контраста и оставяш маската.“ не доказва: Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда. Вариантът „Разширяваш маската до цял кадър без проверка.“ оставя нерешено: Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице. Безопасната корекция е: Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Алтернатива на punch-in","content":{"question":"Кой друг монтажен ход може да скрие jump cut?","options":[{"id":"a","label":"Слагаш маска върху цялото лице."},{"id":"b","label":"Cutaway, промяна на ракурса или чиста пауза, ако запазва смисъла."},{"id":"c","label":"Увеличаваш картината над възможностите на source."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"По-прост срез може да бъде по-качествен и честен от тежка корекция.\n\nВариантът „Увеличаваш картината над възможностите на source.“ не доказва: Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда. Вариантът „Слагаш маска върху цялото лице.“ оставя нерешено: Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице. Безопасната корекция е: Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Кадърът става мек","content":{"prompt":"На 1080 export лицето е меко след силен crop. Какво правиш?","options":[{"id":"a","label":"Намаляваш приближаването или избираш друг кадър с по-добър source detail."},{"id":"b","label":"Оставяш, защото timeline preview изглежда рязък."},{"id":"c","label":"Добавяш sharpening до максимум."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Оцени финалния файл на целевия размер, не preview.\n\nВариантът „Добавяш sharpening до максимум.“ не доказва: Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда. Вариантът „Оставяш, защото timeline preview изглежда рязък.“ оставя нерешено: Ефектът се увеличава докато скокът изчезне, без да се провери изходната резолюция, фокус и лице. Безопасната корекция е: Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s2","text":"Провери source resolution и target crop."},{"id":"s1","text":"Определи какво трябва да се види по-добре и къде е скокът."},{"id":"s4","text":"За маска проследи движение, feather, ръб и скриване на фона."},{"id":"s3","text":"Настрой scale/position така, че лице, ръце и текст да останат в кадър."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Определи какво трябва да се види по-добре и къде е скокът.\n2. Провери source resolution и target crop.\n3. Настрой scale/position така, че лице, ръце и текст да останат в кадър.\n4. За маска проследи движение, feather, ръб и скриване на фона."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще изолираш детайл или ще прикриеш монтажен скок, без да губиш резолюция, фокус или естествено движение.","Използвай минималния crop, който решава задачата; ако няма запас, избери друга монтажна свръзка.","Лицето/детайлът остава четим, няма видими маскиращи ръбове или ореол, а монтажната промяна не подвежда."],"nextStep":"Направи две версии на jump cut: лек punch-in и cutaway. Ако добавиш маска, проследи движеща се ръка и провери ръбовете на целия клип."},"points":1,"required":true}]},{"module_id":"s02-m09","lesson_id":"pv09-12","title":"Motion blur и финална проверка: ефектът трябва да стигне до приемане","subtitle":"Модул 09 · Монтаж, корекция и предаване на готов файл","objective":"Ще използваш motion blur само когато помага на прехода и ще предадеш възпроизводим проект и проверен master.","hook":"Готовият клип има blur преходи навсякъде, текстът се размазва, а финалният файл има стара версия на субтитрите.","estimated_minutes":48,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще използваш motion blur само когато помага на прехода и ще предадеш възпроизводим проект и проверен master."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Готовият клип има blur преходи навсякъде, текстът се размазва, а финалният файл има стара версия на субтитрите."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Решението зад кадъра","content":{"body":"Motion blur може да свърже бързо движение или прикрие твърд преход, когато посоката и скоростта съвпадат със сцената. Излишният blur замазва продукт, текст и лице; не добавяй го като preset по подразбиране. Провери, че преходът започва/свършва в смислено действие и не заменя липсващ кадър.\n\nФиналният handoff включва одобрен файл, проект, нужни медии/proxies, текстови captions, настройки, права, version note и следваща стъпка. Export се гледа целия; провери първи и последен кадър, черни/празни frames, sync, надписи, цветове, aspect ratio, рендер артефакти и точно име. Предай само одобрения вариант, не работна чернова."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво проверяваш на терен","content":{"body":"Направи кратък тест на прехода и прегледай на реалния bitrate/размер. Blur може да предизвика smear, ghosting и размазано четене. При финална инспекция не прескачай на случаен кадър: изгледай непрекъснато целия видео/аудио файл и след това провери техническите метаданни. Съхрани export settings или preset name в readme."},"points":2,"required":true},{"position":4,"block_key":"work_order","block_type":"rich_text","title":"Работен ред","content":{"body":"Подреди задачата така:\n\n1. Избери преход само ако посоката/действието го оправдават.\n2. Провери малка секция с blur и сравни с обикновен срез.\n3. Рендерирай на целевите export settings и огледай артефакти/текст.\n4. Гледай целия master от първи до последен кадър със звук.\n5. Провери frame, format, sync, captions, име, версия и права.\n6. Пакетирай project и readme; предай одобрения export с конкретен статус."},"points":2,"required":true},{"position":5,"block_key":"worked_case","block_type":"example","title":"Решен случай от работа","content":{"body":"Клип за услуга има движение на камерата към врата. Един кратък blur преход следва посоката и не закрива текст; останалите сцени ползват чисти cuts. Финалният файл е проверен на телефон, а монтажистът изпраща project, captions и readme с одобрена версия.\n\nКритерий за добър ход: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Слабият ход и поправката","content":{"before":{"label":"Как се губи контрол","text":"Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане."},"after":{"label":"Как го поправяш","text":"Остави ефект само там, където помага, после провери целия export и свързаните файлове."}},"points":2,"required":true},{"position":7,"block_key":"field_task","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Довърши клип от собствените си материали с един justified blur преход. Експортирай, гледай целия файл, поправи един открит проблем и направи handoff пакет за колега.\n\nЗапази резултата като кратък работен пример, не само като готов клип. Към него приложи брифа и ограниченията, използваните настройки/версия, една проба, конкретна проверка, поправката и крайния резултат. За доказателство използвай кадър преди/след, тестов export, manifest, restore log или измерено време според задачата. В портфолио ползвай собствен или разрешен материал; не качвай клиентски суров материал и лични данни без изрично право. Отбележи кое е чернова, кое е проверено и кое е одобрено."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Преди да предадеш","content":{"body":"Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките.\n\nСамопровери файла/проекта от началото до края, после помоли друг човек да повтори критичната проверка по запазените бележки. Ако другият човек не може да намери входа, версията или резултата, предаването още не е готово. Ясно отбележи неизвестното и въпроса, който трябва да реши клиентът; не запълвай липсващ факт по догадка."},"points":1,"required":true},{"position":9,"block_key":"decision_clinic","block_type":"rich_text","title":"Когато първият опит не мине","content":{"body":"Проблемът, който трябва да разпознаеш: Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане.\n\nНе сменяй няколко неща наведнъж. Запази текущия резултат, назови видимия симптом и провери изходните условия. После изпълни тези два контролни хода: Провери малка секция с blur и сравни с обикновен срез. Гледай целия master от първи до последен кадър със звук.\n\nПровери целия ход от source до target export: проекта, версиите на медията, preview, рендерирания файл и целевия екран. Тествай един участък с говор/движение и началото и края на файла. Настройка, която изглежда вярна в timeline, не е доказателство за готов master.\n\nКоригирай с този ход: Остави ефект само там, където помага, после провери целия export и свързаните файлове.\n\nТестът е минал едва когато: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Ако пак не мине, спри предаването и опиши какво липсва, вместо да маскираш симптома с ефект, обещание или ръчна поправка без запис."},"points":1,"required":true},{"position":10,"block_key":"portfolio_handoff","block_type":"rich_text","title":"Предай го като работа за клиент","content":{"body":"Сглоби малък пример по този бриф: Клип за услуга има движение на камерата към врата. Един кратък blur преход следва посоката и не закрива текст; останалите сцени ползват чисти cuts. Финалният файл е проверен на телефон, а монтажистът изпраща project, captions и readme с одобрена версия.\n\nДоставката ти е: Довърши клип от собствените си материали с един justified blur преход. Експортирай, гледай целия файл, поправи един открит проблем и направи handoff пакет за колега.\n\nВ бележката към нея напиши: цел; вход и ограничения; решение и причина; проверка; проблем и поправка; резултат; статус; следващ собственик и действие. Покажи версията на проекта, източниците или proxy статуса, export настройките, проверения master и списъка с известни ограничения. Получателят трябва да може да отвори файла и да разбере дали е за преглед или е одобрен.\n\nПриемане: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Не представяй тестовия материал като платена клиентска кампания и не заявявай резултат, който не си измерил. Това досие трябва да даде на работодател или клиент основание да повери следваща, по-голяма задача."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Първоизточник за проверка","content":{"body":"Adobe обяснява отделен export на burn-in, sidecar и embedded caption tracks; избери по доставката: https://helpx.adobe.com/premiere/desktop/render-and-export/export-files/export-caption-tracks.html"},"points":0,"required":false},{"position":12,"block_key":"field_note_1","block_type":"rich_text","title":"Крайният пакет","content":{"body":"Предай master, editable project, необходими assets/captions, version note и readme. Не включвай чужди assets, които лицензът не позволява да се предадат."},"points":1,"required":false},{"position":13,"block_key":"quiz_1","block_type":"quiz","title":"Използвай blur с причина","content":{"question":"Кога motion blur помага?","options":[{"id":"a","label":"На всеки монтажен срез."},{"id":"b","label":"Когато движението и посоката съвпадат със сцената, а детайлът остава четим."},{"id":"c","label":"Когато липсва ключов кадър."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Ефектът трябва да свърже движение, не да прикрие редакторски пропуск.\n\nВариантът „На всеки монтажен срез.“ не доказва: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Вариантът „Когато липсва ключов кадър.“ оставя нерешено: Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане. Безопасната корекция е: Остави ефект само там, където помага, после провери целия export и свързаните файлове. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_1","block_type":"scenario","title":"Текстът се размазва","content":{"prompt":"При тест преходът замазва CTA и лого. Какво правиш?","options":[{"id":"a","label":"Оставяш текста, защото се вижда на стоп кадър."},{"id":"b","label":"Намаляваш или премахваш blur и проверяваш четимостта на export."},{"id":"c","label":"Увеличаваш blur, за да стане преходът по-плавен."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Оцени движение и четимост по време на playback, не само стоп кадър.\n\nВариантът „Увеличаваш blur, за да стане преходът по-плавен.“ не доказва: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Вариантът „Оставяш текста, защото се вижда на стоп кадър.“ оставя нерешено: Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане. Безопасната корекция е: Остави ефект само там, където помага, после провери целия export и свързаните файлове. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"quiz_2","block_type":"quiz","title":"Финална инспекция","content":{"question":"Кое е задължително преди handoff?","options":[{"id":"a","label":"Цялостно възпроизвеждане плюс проверка на версия, звук, captions, формат и файл."},{"id":"b","label":"Само статус „render complete“."},{"id":"c","label":"Само проверка на последния кадър."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Цялото видео може да съдържа кратък дефект, който кадър по избор пропуска.\n\nВариантът „Само проверка на последния кадър.“ не доказва: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Вариантът „Само статус „render complete“.“ оставя нерешено: Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане. Безопасната корекция е: Остави ефект само там, където помага, после провери целия export и свързаните файлове. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"scenario_2","block_type":"scenario","title":"Грешни субтитри във финала","content":{"prompt":"Целият export е добър, но първата версия на субтитрите е вградена. Какво предаваш?","options":[{"id":"a","label":"Изпращаш текущия, понеже промяната е малка."},{"id":"b","label":"Изпращаш два файла с еднакво име и оставяш клиента да избира."},{"id":"c","label":"Нов export от одобрения caption track, после повторна пълна проверка и ново име/версия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Предай една конкретна одобрена версия и повторно провери файла след поправка.\n\nВариантът „Изпращаш текущия, понеже промяната е малка.“ не доказва: Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките. Вариантът „Изпращаш два файла с еднакво име и оставяш клиента да избира.“ оставя нерешено: Ефектът се използва на всеки срез; финалната доставка е избрана по име, без цялостно възпроизвеждане. Безопасната корекция е: Остави ефект само там, където помага, после провери целия export и свързаните файлове. При реален клиент маркирай неизвестното и поискай решение преди да заключиш master или календара."},"scoring":{"mode":"single_choice"}},{"position":17,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди първите решения така, че проверката да дойде преди окончателното предаване.","items":[{"id":"s4","text":"Гледай целия master от първи до последен кадър със звук."},{"id":"s1","text":"Избери преход само ако посоката/действието го оправдават."},{"id":"s2","text":"Провери малка секция с blur и сравни с обикновен срез."},{"id":"s3","text":"Рендерирай на целевите export settings и огледай артефакти/текст."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред:\n1. Избери преход само ако посоката/действието го оправдават.\n2. Провери малка секция с blur и сравни с обикновен срез.\n3. Рендерирай на целевите export settings и огледай артефакти/текст.\n4. Гледай целия master от първи до последен кадър със звук."},"scoring":{"mode":"exact_order"}},{"position":18,"block_key":"summary","block_type":"summary","title":"Какво пренасяш в следващата задача","content":{"takeaways":["Ще използваш motion blur само когато помага на прехода и ще предадеш възпроизводим проект и проверен master.","Остави ефект само там, където помага, после провери целия export и свързаните файлове.","Одобреният master се отваря, няма видими дефекти, субтитрите/звукът са проверени, а колега намира проекта и настройките."],"nextStep":"Довърши клип от собствените си материали с един justified blur преход. Експортирай, гледай целия файл, поправи един открит проблем и направи handoff пакет за колега."},"points":1,"required":true}]}]$curriculum$::jsonb;
  expected_ids integer;
  catalog_count integer;
  v_module_counts integer[];
  lesson record;
  block jsonb;
  old_version public.academy_lesson_versions;
  new_version_id uuid;
  block_id uuid;
  validation_result jsonb;
  correct_id text;
  old_required integer;
  old_done integer;
  new_required integer;
  new_reading integer;
  mapped_done integer;
  mapped_keys text[];
  next_key text;
  progress_row record;
  progress_before integer;
  progress_after integer;
  progress_xp_before bigint;
  progress_xp_after bigint;
  history_after integer;
  release_started timestamptz := clock_timestamp();
  release_note text := 'Переработка модулей 7–9: практическо издание v6';
BEGIN
  IF jsonb_typeof(payload)<>'array' THEN
    RAISE EXCEPTION 'Curriculum payload must be a JSON array';
  END IF;
  SELECT count(*) INTO expected_ids FROM jsonb_to_recordset(payload)
    AS p(module_id text,lesson_id text);
  IF expected_ids<>43 THEN
    RAISE EXCEPTION 'Expected 43 lesson records, received %', expected_ids;
  END IF;

  SELECT count(*) INTO catalog_count
  FROM public.academy_lessons
  WHERE module_id IN ('s02-m07','s02-m08','s02-m09');
  IF catalog_count=0 THEN
    RETURN;
  END IF;
  IF catalog_count<>43 THEN
    RAISE EXCEPTION 'Expected all 43 published lessons; found %', catalog_count;
  END IF;

  SELECT ARRAY[
    count(*) FILTER (WHERE module_id='s02-m07')::integer,
    count(*) FILTER (WHERE module_id='s02-m08')::integer,
    count(*) FILTER (WHERE module_id='s02-m09')::integer
  ] INTO v_module_counts
  FROM public.academy_lessons
  WHERE module_id IN ('s02-m07','s02-m08','s02-m09');
  IF v_module_counts<>ARRAY[16,16,11] THEN
    RAISE EXCEPTION 'Unexpected module distribution: %',v_module_counts;
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload)
      AS p(module_id text,lesson_id text)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.academy_lessons l
      WHERE l.module_id=p.module_id AND l.lesson_id=p.lesson_id
    )
  ) OR EXISTS (
    SELECT 1 FROM public.academy_lessons l
    WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_to_recordset(payload)
          AS p(module_id text,lesson_id text)
        WHERE p.module_id=l.module_id AND p.lesson_id=l.lesson_id
      )
  ) THEN
    RAISE EXCEPTION 'Production lesson IDs do not match the authored release';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.academy_lessons l
    JOIN public.academy_lesson_versions v ON v.id=l.published_version_id
    WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
      AND v.change_note=release_note
  ) THEN
    RAISE EXCEPTION 'Release marker already exists; refusing a duplicate publication';
  END IF;

  LOCK TABLE public.academy_lessons IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.academy_lesson_progress IN SHARE ROW EXCLUSIVE MODE;

  IF EXISTS (
    SELECT 1 FROM public.academy_lessons
    WHERE module_id IN ('s02-m07','s02-m08','s02-m09')
      AND (
        status<>'published'
        OR published_version_id IS NULL
        OR (draft_version_id IS NOT NULL
            AND draft_version_id IS DISTINCT FROM published_version_id)
      )
  ) THEN
    RAISE EXCEPTION 'A lesson is unpublished or has an unreviewed draft';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload) AS p(blocks jsonb)
    WHERE jsonb_typeof(p.blocks)<>'array'
      OR jsonb_array_length(p.blocks)<13
      OR jsonb_array_length(p.blocks)>20
      OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(p.blocks) b
        WHERE b->>'block_type' IN (
          'practical_response','reflection','homework','submission','prompt_builder'
        )
      )
      OR (
        SELECT count(*) FROM jsonb_array_elements(p.blocks) b
        WHERE b->>'block_type' IN ('quiz','scenario','sequence_sort')
      )<>5
  ) THEN
    RAISE EXCEPTION 'Invalid lesson length, open response, or assessment count';
  END IF;

  SELECT count(*),coalesce(sum(xp),0) INTO progress_before,progress_xp_before
  FROM public.academy_lesson_progress p
  JOIN public.academy_lessons l ON l.id=p.academy_lesson_id
  WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09');

  FOR lesson IN
    SELECT * FROM jsonb_to_recordset(payload) AS p(
      module_id text,
      lesson_id text,
      title text,
      subtitle text,
      objective text,
      hook text,
      estimated_minutes integer,
      blocks jsonb
    )
    ORDER BY module_id,lesson_id
  LOOP
    SELECT v.* INTO old_version
    FROM public.academy_lessons l
    JOIN public.academy_lesson_versions v ON v.id=l.published_version_id
    WHERE l.module_id=lesson.module_id AND l.lesson_id=lesson.lesson_id
    FOR UPDATE OF l;

    INSERT INTO public.academy_lesson_versions(
      academy_lesson_id,version_number,origin_version_id,title,subtitle,duration,
      objective,hook,estimated_minutes,source_kind,validation,change_note,created_by
    )
    SELECT
      l.id,
      coalesce((SELECT max(v.version_number)+1
                FROM public.academy_lesson_versions v
                WHERE v.academy_lesson_id=l.id),1),
      l.published_version_id,
      lesson.title,
      lesson.subtitle,
      lesson.estimated_minutes::text || ' минути',
      lesson.objective,
      lesson.hook,
      lesson.estimated_minutes,
      'editor',
      jsonb_build_object('errors','[]'::jsonb,'warnings','[]'::jsonb),
      release_note,
      old_version.created_by
    FROM public.academy_lessons l
    WHERE l.module_id=lesson.module_id AND l.lesson_id=lesson.lesson_id
    RETURNING id INTO new_version_id;

    FOR block IN SELECT value FROM jsonb_array_elements(lesson.blocks)
    LOOP
      INSERT INTO public.academy_lesson_blocks(
        version_id,block_key,"position",block_type,title,content,required,points
      )
      VALUES(
        new_version_id,
        block->>'block_key',
        (block->>'position')::integer,
        block->>'block_type',
        block->>'title',
        block->'content',
        coalesce((block->>'required')::boolean,true),
        coalesce((block->>'points')::integer,1)
      )
      RETURNING id INTO block_id;

      IF block ? 'answer_key' THEN
        INSERT INTO academy_private.lesson_block_keys(
          block_id,answer_key,feedback,scoring
        )
        VALUES(block_id,block->'answer_key',block->'feedback',block->'scoring');

        IF block->>'block_type' IN ('quiz','scenario') THEN
          correct_id:=block->'answer_key'->>'correct';
          IF NOT EXISTS(
            SELECT 1 FROM jsonb_array_elements(block->'content'->'options') opt
            WHERE opt->>'id'=correct_id
          ) THEN
            RAISE EXCEPTION 'Answer key points to a missing option in % / %',
              lesson.lesson_id,block->>'block_key';
          END IF;
        END IF;

        IF block->>'block_type'='sequence_sort'
          AND jsonb_array_length(block->'answer_key'->'order')
              <> jsonb_array_length(block->'content'->'items') THEN
          RAISE EXCEPTION 'Sequence key length mismatch in %',lesson.lesson_id;
        END IF;
      END IF;
    END LOOP;

    validation_result:=academy_private.lesson_validation(new_version_id);
    IF jsonb_array_length(validation_result->'errors')<>0
      OR jsonb_array_length(validation_result->'warnings')<>0 THEN
      RAISE EXCEPTION 'Validation failed for %: %',
        lesson.lesson_id,validation_result;
    END IF;
    UPDATE public.academy_lesson_versions
      SET validation=validation_result
      WHERE id=new_version_id;

    UPDATE public.academy_lessons
      SET published_version_id=new_version_id,
          draft_version_id=new_version_id,
          status='published',
          updated_at=clock_timestamp()
      WHERE module_id=lesson.module_id AND lesson_id=lesson.lesson_id;
  END LOOP;

  -- Archive the exact prior row via the existing BEFORE UPDATE trigger. Map only
  -- the same fraction of completed reading blocks; new graded answers must be
  -- answered again against the new curriculum. XP and start time remain intact.
  FOR progress_row IN
    SELECT p.*,l.module_id,l.lesson_id,l.published_version_id AS new_version_id
    FROM public.academy_lesson_progress p
    JOIN public.academy_lessons l ON l.id=p.academy_lesson_id
    WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
      AND p.version_id IS DISTINCT FROM l.published_version_id
    ORDER BY l.module_id,l.lesson_id
    FOR UPDATE OF p
  LOOP
    SELECT count(*) INTO old_required
    FROM public.academy_lesson_blocks
    WHERE version_id=progress_row.version_id AND required;

    SELECT count(*) INTO old_done
    FROM unnest(coalesce(progress_row.completed_block_keys,ARRAY[]::text[]))
      AS done(block_key)
    JOIN public.academy_lesson_blocks b
      ON b.version_id=progress_row.version_id
     AND b.block_key=done.block_key
     AND b.required;

    SELECT count(*) INTO new_required
    FROM public.academy_lesson_blocks
    WHERE version_id=progress_row.new_version_id AND required;

    SELECT count(*) INTO new_reading
    FROM public.academy_lesson_blocks
    WHERE version_id=progress_row.new_version_id
      AND required
      AND block_type NOT IN ('quiz','scenario','sequence_sort');

    mapped_done:=least(
      new_reading,
      CASE WHEN old_required=0 THEN 0
           ELSE round((old_done::numeric/old_required)*new_required)::integer
      END
    );

    SELECT coalesce(array_agg(x.block_key ORDER BY x.position),ARRAY[]::text[])
      INTO mapped_keys
    FROM (
      SELECT block_key,"position"
      FROM public.academy_lesson_blocks
      WHERE version_id=progress_row.new_version_id
        AND required
        AND block_type NOT IN ('quiz','scenario','sequence_sort')
      ORDER BY "position"
      LIMIT mapped_done
    ) x;

    SELECT block_key INTO next_key
    FROM public.academy_lesson_blocks
    WHERE version_id=progress_row.new_version_id
      AND required
      AND NOT (block_key=ANY(mapped_keys))
    ORDER BY "position"
    LIMIT 1;

    UPDATE public.academy_lesson_progress
      SET version_id=progress_row.new_version_id,
          current_block_key=next_key,
          block_state='{}'::jsonb,
          completed_block_keys=mapped_keys,
          score_percent=NULL,
          mastery_status='learning',
          completed_at=NULL,
          last_activity_at=clock_timestamp()
    WHERE user_id=progress_row.user_id
      AND academy_lesson_id=progress_row.academy_lesson_id
      AND version_id=progress_row.version_id;

    IF NOT EXISTS(
      SELECT 1 FROM academy_private.lesson_progress_history h
      WHERE h.user_id=progress_row.user_id
        AND h.academy_lesson_id=progress_row.academy_lesson_id
        AND h.version_id=progress_row.version_id
        AND h.reason='version_change'
        AND h.snapshot->>'xp'=progress_row.xp::text
        AND coalesce(h.snapshot->>'current_block_key','')
            =coalesce(progress_row.current_block_key,'')
    ) THEN
      RAISE EXCEPTION 'Prior progress snapshot missing for % / %',
        progress_row.module_id,progress_row.lesson_id;
    END IF;
  END LOOP;

  SELECT count(*) INTO progress_after
  FROM public.academy_lesson_progress p
  JOIN public.academy_lessons l ON l.id=p.academy_lesson_id
  WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09');
  SELECT coalesce(sum(xp),0) INTO progress_xp_after
  FROM public.academy_lesson_progress p
  JOIN public.academy_lessons l ON l.id=p.academy_lesson_id
  WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09');

  IF progress_before<>progress_after OR progress_xp_before<>progress_xp_after THEN
    RAISE EXCEPTION 'Progress rows or earned XP changed during release';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.academy_lesson_progress p
    JOIN public.academy_lessons l ON l.id=p.academy_lesson_id
    WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
      AND p.version_id IS DISTINCT FROM l.published_version_id
  ) THEN
    RAISE EXCEPTION 'A progress row did not move to the current lesson version';
  END IF;

  SELECT count(*) INTO history_after
  FROM academy_private.lesson_progress_history h
  JOIN public.academy_lessons l ON l.id=h.academy_lesson_id
  WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
    AND h.reason='version_change'
    AND h.archived_at>=release_started;
  IF history_after<progress_before THEN
    RAISE EXCEPTION 'Expected % archived snapshots, found %',
      progress_before,history_after;
  END IF;

  IF EXISTS(
    SELECT 1
    FROM public.academy_lessons l
    JOIN public.academy_lesson_versions v ON v.id=l.published_version_id
    WHERE l.module_id IN ('s02-m07','s02-m08','s02-m09')
      AND (
        v.change_note<>release_note
        OR jsonb_array_length(v.validation->'errors')<>0
        OR jsonb_array_length(v.validation->'warnings')<>0
      )
  ) THEN
    RAISE EXCEPTION 'Final release verification failed';
  END IF;
END
$release$;
